window.__D("text/maamarei-admur-hazaken/c000",{"p":[[2100490062,"<h3>להבין ענין ק\"ש</h3>\n<b>בעזר\"ה ליל שבת פ' נח</b>\n<b>להבין</b> ענין ק\"ש<sup data-n=\"1\">1</sup>. הנה ענין ב' פרשיות דק\"ש שמע והיה אם שמוע<sup data-n=\"2\">2</sup> מבואר בכתבי האריז\"ל<sup data-n=\"3\">3</sup> דפ' הראשונה יש בה מ\"ב תיבות מואהבת עד ובשעריך הוא בחי' שם מ\"ב דאנא בכח כו' ופ' השני' והי' יש בה ע\"ב<sup data-n=\"4\">4</sup> תיבות (עד פסוק ושמתם את ומתיבת א\"ת עד כל הארץ נ' תיבות שהוא נגד בחי' שם ע\"ב וגם נגד חמשים שערי בינה שכלולי' בחכמ' שהוא שם ע\"ב כו' יעו\"ש). ולכאורה יש להקשו' קושיא חזקה, דלפ\"ז הפ' ראשונה שמע הוא בבחי' הגבורה שהרי ידוע דשם מ\"ב דאנא בכח הוא במדת הגבורה ושם ע\"ב שבפ' שני' הוא בבחי' החסד כידוע דחס\"ד בגי' ע\"ב<sup data-n=\"5\">5</sup> כו' ואנו רואי' בהיפוך מזה בסדר ענין ד' פרשיו' דתפילין בכתבי האריז\"ל<sup data-n=\"6\">6</sup> שהרי ידוע דפ' קדש בחכמה ופ' והי' כי יביאך בבינה שמע בחסד והי' אם שמוע בגבורה שהן ענין ד' מוחי' שבד' בתים דתפילין חו\"ב חו\"ג כידוע וא\"כ נהפוך הוא שפ' שמע בחסד ופ' והי' א\"ש בגבורה כו'. אך הנה התירוץ ע\"ז ע\"ד הקבלה פשוט הוא\nמשום דידוע פי' המאמר בזוהר במה דאחליפו דוכתייהו<sup data-n=\"7\">7</sup> כו' ואתכללא שמאלא",[["1","1","<b>להבין ענין ק\"ש</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1194 פא, ב. עח, א (גוכתי\"ק כ\"ק אדמו\"ר האמצעי). ומכת\"י 68 טו, א. 957 רמה, א. 1156 ס, ב (עם הגהות בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ). נמצא ג\"כ בכת\"י 369 תצד, א. 943 נד, א (נו\"א). 1001 לז, א (בין מאמרי תקס\"ו). 1245 רנה, א.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח.\nנוסח אחר נדפס לקמן ע' טו. הנחת ר' משה בן אדה\"ז נדפס לקמן ע' יז — ראה בהנסמן שם הערה 1. לקו\"ת ואתחנן יב, ד. וראה בארוכה אמרי בינה פמ\"ה ואילך."],["2","2","<b>שמע והיה אם שמוע</b>: ואתחנן ו, ד. עקב יא, יג."],["3","3","<b>בכתבי האריז\"ל</b>: ראה פרי עץ חיים (ושער הכוונות) שער (ז) הק\"ש פי\"ח. (פכ\"ד). פכ\"ה. סידור האריז\"ל (וסידור תפלה למשה להרמ\"ק בשם רעיא מהימנא) ק\"ש. משנת חסידים מסכת הבריאה דערבית פי\"ב, מ\"ו. פי\"ג, מ\"א. מ\"ט. תקוני זהר ת\"ע (קלד, סע\"ב). סידור שער הק\"ש עג, ג. דרך מצותיך שורש מצות התפלה פי\"ב."],["4","4","<b>שם מ\"ב. . ע\"ב</b>: ראה זהר תרומה קלב, ב. פרדס שער (כא) פרטי השמות פ\"ה. פי\"ב."],["5","5","<b>דחסד בגי' ע\"ב</b>: פרדס שער (כג) ערכי הכנויים מערכת חסד."],["6","6","<b>בכתבי האריז\"ל</b>: ראה פרי עץ חיים שער (ד) התפילין פ\"ח. משנת חסידים מסכת תיקון תפילין פ\"ג-ו. פי\"א. פי\"ב. זהר בא מג, ב. ואתחנן רסב, א. סידור (שם ו)שער התפילין ז, סע\"א."],["7","7","<b>בזוהר במה דאחליפו דוכתייהו</b>: באמרי בינה הנ\"ל ע\"פ ומלכי צדק [זהר לך פז, רע\"א. וראה במקדש מלך שם. בלקו\"ת הנ\"ל עיין מזה בהרמ\"ז פ' צו בדף כז [ב] וכנזכר מזה בביאור ע\"פ לבבתני (לקו\"ת שיר השירים ל, ג)]. סה\"מ תקס\"ז ע' רפג. אוה\"ת בשלח ע' תקנז."]]],[2100490063,"בימינא<sup data-n=\"8\">8</sup> וימינא בשמאלא כו' שהוא משום שהוחלפו האורות שבכלים מחסד לגבורה ומגבור' לחסד והיינו כמ\"ש בע\"ח (בשער מול\"מ) דאור החסד האיר בכלי הגבורה ואור הגבורה האיר בכלי החסד כו' ולכך הוא נמצא ענין ההתכללו' למעלה דשמאלא שהוא גבורה אתכלל בימינא שהוא חסד כו' וד\"ל ובזה מתורץ היטב הקושיא הנ\"ל דהגם שפ' שמע הוא בחסד<sup data-n=\"9\">9</sup> היינו בכלי החסד אבל אור הגבורה מאיר בו והוא ענין השם מ\"ב דאנא בכח כו' ופ' והי' א\"ש הוא בבחי' הגבורה היינו בכלי הגבורה אבל אור החסד מאיר בו והוא ענין שם ע\"ב שבחס\"ד כנ\"ל וד\"ל.\n<b>ואמנם</b> הגם שניתרצה הקושיא הנ\"ל ע\"ד הקבלה מ\"מ יש להבין תירוץ זה בהשגה וטעם מהו זה שאור החסד מאיר בכלי הגבורה ואור הגבורה בכלי החסד ולמה פ' שמע דוקא באור הגבור' בכלי החסד ופ' והי' באור החסד בכלי הגבור' כו' והנה תחלה יש להבין פי' פסוק ראשון דק\"ש שהוא שמע ישראל וכו' עד ואהבת. ויש להקדים תחלה הכלל הגדול הידוע בהשתלשלו' העולמו' שההשתלשלו' הוא מאין ליש וכמ\"ש בס' חינוך קטן<sup data-n=\"10\">10</sup>, וביאור ענינו ידוע להיות כי התהוות העולם השפל הזה הגשמי כמו שמים וארץ הגשמיי' הרי מתהווי' מכח אלקי שבכלים שבי\"ס האחרונו' דעולם העשי' וכל שהוא בבחי' אלקו' הגם שהוא מדרגה היותר תחתונה כמו גם ספי' מל' שבמל' די\"ס דעשי' הרי הוא מובדל בערך לגמרי מבחי' בעלי גבול ותכלית שהרי הוא ית' בחי' בלתי ב\"ג וקדמון לכל הקדומי'<sup data-n=\"11\">11</sup> כו' וכמאמר אין ערוך לך<sup data-n=\"12\">12</sup> כו' וא\"כ בהשתלשלו' השפע מאתו להוו' בעלי גבול כמו נבראי' שבעולם העשי' הוא בבחי' דילוג ההשפעה שלא בבחי' ערך והשתוו' כלל והיינו הנק' יש מאין וכמ\"ש במ\"א ולא כדרך כל עילה ועלול שהוא בבחי' יש מיש לפי שיש להן ערך זע\"ז כו'. ועד\"ז יובן גם למעלה בעולם הנאצלי' שנאצלו מן המאציל כי כמו שאין ערוך כלל בין נברא עם הבורא עד שבוראם יש מאין כך אין ערוך כלל לנאצלי' עם עצמו' המאציל דהיינו שגם הן נאצלי' בבחי' י\"ש מאי\"ן בלבד מעצמו' אור א\"ס כמו ע\"ד התהוו' הבריא' יש מאין מן הבורא כנ\"ל וד\"ל.\n<b>וביאור</b> הדבר הנה ידוע פי' המאמר אנת הוא חכים<sup data-n=\"13\">13</sup> ולא בחכמ' ידיע' כו' עד ולאו דאית לך צדק ידיע' כו' ולאו מכל אינון מדות כלל שהוא משום דבאמת הרי בחי' עצמו' אור הא\"ס הוא מובדל ומרומם לגמרי מכל ההשתלשלו' של",[["8","8","<b>ואתכללא שמאלא בימינא</b>: ראה ג\"כ זהר וארא (כז, א). תרומה (קסב, ב). ויקרא (כד, א). קרח (קעו, א. קעח, א)."],["9","9","<b>שפ' שמע הוא בחסד</b>: ראה פירוש המלות (מהדו\"ב) פס\"ט (מד, ב). דרך מצותיך הנ\"ל."],["10","10","<b>בחינוך קטן</b>: [שער היחוד והאמונה הנקרא בשם חינוך קטן]. ראה שם פ\"ב. פ\"ט. מאמרי אדה\"ז הקצרים ע' תקטז."],["11","11","<b>וקדמון לכל הקדומי'</b>: ראה חובת הלבבות שער (א) היחוד פ\"ז סוד\"ה והחמישי."],["12","12","<b>אין ערוך לך</b>: ברכת יוצר לשבת."],["13","13","<b>אנת הוא חכים</b>: ראה תקוני זהר בהקדמה (יז, ב)."]]],[2100490064,"י' ספי' בכלל ומכ\"ש בפרט וכמאמר אנת חד ולא בחושבן<sup data-n=\"14\">14</sup> פי' ולא בחושבן י\"ס כח\"ב כו' אלא דאנת אפיקת עשר תקונין וקרית לון י' ספירן כו' רק לאחזאה בהון איך אתנהיג עלמא כו' דהיינו רק כדי שיהא מהן מתנהג סוף מעשה והוא עולם הבריא' כו' אבל קמי' עצמותו לא יש מכל אינון מדות כלל אלא הוא חכים ולא בחכמ' ידיעא כו' וא\"כ מה שנאצל מאתו אור החכמה עד שנק' חכים הוא בא למטה בדרך ירידה וצמצום גדול כמו ע\"ד הירידה והצמצום מאצי' לבריא' כנ\"ל והיינו שאמרו ז\"ל במקום גדולתו<sup data-n=\"15\">15</sup> שם אתה מוצא ענוותנותו כו' משום דענוה גדולה היא מה שיורד אור א\"ס מעצמותו ומתלבש בחכמ\"ה להיו' נק' חכי\"ם וכן עד\"ז בשאר הספירו' והמדו' כו' ולהיות כן צריך שימשיכו מאור א\"ס שירד למטה ויתלבש בי\"ס והיינו שיעוררו אותו שיצמצם א\"ע בירידה זו ואם לא יעוררו אותו לזה הי' כל ההשתלשלו' די\"ס בכלל חוזרין למקור חוצבם בהתכללו' והי' בביטול מציאותם לגמרי בעצמו' אור א\"ס כמו שהי' הוא ושמו בלבד לפני ההשתלשלו' כידוע. אך הנה כדי לעורר אותו לזה מלמטה היינו ע\"י העלא' מ\"ן דוקא כידוע וקודם שהי' התחלת ההשתלשלו' לא הי' מי שיעלה מ\"ן מלמטה כידוע וזהו שאמר בזוהר כד סליק ברעותי'<sup data-n=\"16\">16</sup> כו' פי' שהי' העלא' הרצון הזה מצד עצמו כי חפץ חסד הוא<sup data-n=\"17\">17</sup> כו' וכמ\"ש בע\"ח<sup data-n=\"18\">18</sup> שלפני ההשתלשלו' הי' בלתי העלא' מ\"ן כלל רק מצד עצמו אך אח\"כ תלוי במעשה התחתונים כו' וזהו שאמר בהתחלת ספר הזוהר<sup data-n=\"19\">19</sup> בריש הורמנותא דמלכא גליף גליפו בטהירו עילא' כו' פי' בהתחלת ההשתלשלו' הי' ענין ההתעוררו' לזאת הירידה והצמצום להיו' מתלבש כלל בי\"ס כנ\"ל רק מצד עצמו והרצון הוא הנק' הרמנ\"א<sup data-n=\"20\">20</sup> כידוע ובריש העלא' הרצון לזה כמ\"ש כד סליק ברעותי' כו' הי' זה מצד עצמו והוא במה דגליף גליפו מתחלה בטהירו עילא' שהוא בבחי' העצמות כו' וכמבואר ענין הטהירו לי\"ח וד\"ל.\n<b>והנה</b> אחר ההשתלשלו' אזי עיקר סיבת הירידה של אור א\"ס בנאצלי' כו' הוא בא ע\"י העלא' מ\"ן מלמטה דוקא וכנ\"ל ופי' העלא' מ\"ן ידוע שע\"י התבוננו' הנשמו' והמלאכי' בעולם הבריא'<sup data-n=\"21\">21</sup> איכו' ביטול היש לאין מפני שמשיגי' בעצמו' אור האצי' איך שהוא מובדל ומרומם כו' וכמ\"ש קדוש<sup data-n=\"22\">22</sup> כו' והאופנים ברעש גדול<sup data-n=\"23\">23</sup> כו' אזי הן מתבטלי' ממציאותם וכידוע וזהו ענין העלא' מ\"ן מעולם הבריא' להיו' יש",[["14","14","<b>אנת חד ולא בחושבן</b>: ראה תקוני זהר שם (יז, א)."],["15","15","<b>במקום גדולתו</b>: ראה מגילה לא, א. סה\"מ ה'ש\"ת ע' 40 בהערה. לקוטי הגהות לתניא פ\"ד."],["16","16","<b>כד סליק ברעותי'</b>: ראה זהר לך פו, סע\"א. לקו\"ת (וסה\"מ תקס\"ט) שיר השירים טז, א (ע' עד)."],["17","17","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["18","18","<b>וכמ\"ש בע\"ח</b>: שער (ח) דרושי הנקודות ספ\"ו."],["19","19","<b>בהתחלת ספר הזוהר</b>: טו, א."],["20","20","<b>והרצון הוא הנק' הרמנ\"א</b>: ראה דרך אמת לזהר שם. אור החמה ומקדש מלך שם. הדרת מלך ספ\"ט מג, א-ב. ערוך מערכת הרמן."],["21","21","<b>והמלאכי' בעולם הבריא'</b>: ראה תניא פל\"ט בהג\"ה."],["22","22","<b>וכמ\"ש קדוש</b>: ישעי' ו, ג."],["23","23","<b>והאופנים ברעש גדול</b>: ראה ברכת יוצר."]]],[2100490065,"נכללי' בעולם האצי' כו' ועד\"ז יובן ג\"כ בחי' העלא' מ\"ן מאצי' לגבי עצמו' המאציל כו' וד\"ל ואז עי\"ז מעוררי' עצמו' אור המאציל שירד ויצמצם א\"ע מחדש בהשתלשלו' דאבי\"ע ובזה יובן בדרך כלל סדר דברי הפסוק הראשון דק\"ש בכלל שמע ישראל ה' אלקינו כו' פי' ע\"י בחי' העלא' מ\"ן מלמטה בב' תיבו' הללו דשמ\"ע ישראל כמשי\"ת בסמוך בעזר\"ה בזה הוא בא עיקר סיבת ירידת אור עצמו' המאציל בנאצלי' ונבראי' כנ\"ל ונעשה ה' אלקינו פי' הוי'<sup data-n=\"24\">24</sup> הוא בבחי' אור החכמה דאצי' להיו' נק' חכי\"ם כנ\"ל ואלקינו הוא בחי' אור הבינה והוא בכלל ענין יחוד אורו' אבא ואימא דאצי' שנק' תרין ריעין דלא מתפרשין<sup data-n=\"25\">25</sup> כידוע וד\"ל ומה שהבינה נק' אלקינו ידוע הטעם משום דהבינה הוא הנק' רחובו' הנה\"ר<sup data-n=\"26\">26</sup> כו' מפני שבאה בבחי' השגה ותפיס' בהרחבה כו' ולכך נק' אלקינ\"ו פי' שהוא אלוה שלנו כלומר שהוא מושג לנו ע\"י התבוננו' בהתפשטו' גדולתו בהשתלשלו' העולמו' כו' אבל החכמ\"ה נק' מעיין<sup data-n=\"27\">27</sup> כמו המעיין הנובע בהעלם מתחת לארץ כו' כך החכמ\"ה היא למעלה עדיין מבחי' ההשגה והתפיסה באור א\"ס ולכך נק' כח מ\"ה<sup data-n=\"28\">28</sup> כלומר מ\"ה פשפשת<sup data-n=\"29\">29</sup> מ\"ה ידעת כו' וכמ\"ש במ\"א וזהו והחכמ\"ה מאין תמצא<sup data-n=\"30\">30</sup> פי' החכמ\"ה דוקא מאי\"ן נמשכה להיותה בבחי' מ\"ה כנ\"ל שהוא בחי' הביטול והוא ההפשטה מגדר דבר י\"ש כו' משא\"כ הבינה נק' י\"ש וכמ\"ש להנחיל אוהבי יש<sup data-n=\"31\">31</sup> כו' וכידוע ועיקר הענין הוא במה שאמר והחכמ' מאין כו' שהחכמה היא יש מאין מאור הכת\"ר שנק' אי\"ן<sup data-n=\"32\">32</sup> כידוע דוקא ולא הבינה משום דהבינה מן החכמה נמשכה בבחי' יש מיש כמו עד\"מ משכל למדו' משא\"כ מכת\"ר לחכמה שהוא מאין ליש כו' וכמ\"ש במ\"א וד\"ל. וזהו הוי' אלקינו כי כל הוי' הוא בחכמ' וכמ\"ש כולם בחכמה עשית<sup data-n=\"33\">33</sup> ואפי' גם בעולמו' התחתוני' הרי ספי' חכמה דאצי' מתלבש בחכמ' בי\"ס דבריא' ובחכמה דבריאה נבראו כל הנבראי' שבבריא' ועד\"ז חכמה דבריאה מתלבש עוד בחכמה די\"ס דיצי' כו' עד בחי' חכמה שבמל' דמל' דעשי' שמהוו' שמים וארץ גשמי' וזהו כולם בחכמ\"ה עשית כו' וד\"ל ומהוי' דחכמה הוא שנמשך ונתגלה אח\"כ באור הבינה והוא פי' אלקינו כנ\"ל וע\"כ קדם לומר הוי' ואח\"כ אלקינו ואמנם כל זה שיהי' יחוד אורו' דאו\"א שהן חו\"ב הנ\"ל הנק' תרין ריעין כו' הוא בא מחמת שאור א\"ס ירד מבחי' עצמותו מלמעלה למטה להיו' נק' הוי' אלקינו באצי' כנ\"ל ונעשה זה ע\"י העלא' מ\"ן תחלה שבב' תיבו' דשמ\"ע ישרא\"ל כנ\"ל וד\"ל.",[["24","24","<b>הוי'. . החכמה. . ואלקינו. . הבינה</b>: ראה פע\"ח שער (ז) הק\"ש פי\"א. ועוד. תקוני זהר תי\"ח (לד, ריש ע\"ב)."],["25","25","<b>תרין ריעין דלא מתפרשין</b>: ראה זהר ויקרא ד, א. אור התורה נצבים א'רכב."],["26","26","<b>דהבינה. . רחובו' הנהר</b>: זהר (אדרא רבא) נשא קמב, א."],["27","27","<b>החכמה נק' מעיין</b>: ראה פרדס שער (כג) ערכי הכנויים מערכת מעיין."],["28","28","<b>החכמה. . כח מ\"ה</b>: זהר (רעיא מהימנא) צו כח, א. לד, א."],["29","29","<b>מ\"ה פשפשת</b>: ראה הקדמת הזהר (א, ב)."],["30","30","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["31","31","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["32","32","<b>הכתר שנק' אי\"ן</b>: ראה תקוני זהר תמ\"ב (פא, ב). ת\"ע (קכז, א). פרדס שער (ג) אם הא\"ס הוא הכתר פ\"א. שער (יד) המציאות פ\"ב. שער (כג) ערכי הכנויים מערכת אין."],["33","33","<b>כולם בחכמה עשית</b>: תהלים קד, כד."]]],[2100490066,"<b>ועתה</b><sup data-n=\"34\">34</sup> יש להבין שרש ענין ב' תיבות דשמע ישראל איך שהן בחי' העלאת מ\"ן תחלה כנ\"ל, הנה ידוע בכתבי האריז\"ל<sup data-n=\"35\">35</sup> בפי' שמע שהוא שם ע' והע' הוא ע' רבתי<sup data-n=\"36\">26</sup> ופי' שם הוא בחי' רפ\"ח ניצוצים עם שם ב\"ן המברר<sup data-n=\"37\">37</sup> אותם שהוא בגימ' שם וכמ\"ש ויעש דוד שם<sup data-n=\"38\">38</sup> שהוא לאחר הבירור מרפ\"ח כו', וביאור הדברים ידוע דמפני סיבת השבירה בז' מלכין דתהו ירדו הכלים שנשברו למטה ונעשה מהן עולמות הנפרדי' וכמ\"ש ומשם יפרד<sup data-n=\"39\">39</sup> כו' עד שנתהוו גם היכלות דקליפת נוגה בבי\"ע והן הע' שרים של מעלה הסובבים את הכסא כו' ובחי' העלא' הניצוצים שנפלו שם בהיכלות דנוגה ע\"י מס\"נ וביטול במציאות של הנשמות והמלאכים באמרם שירה כו' זהו הנק' העלאת מ\"ן פי' מיין נוקבין היינו זה שירדו האורות והניצוצי' דתהו כשנפלו ונשברו למטה בעולמות הנפרדים וההעלאו' דרפ\"ח ניצוצי' נק' העלא' מ\"ן שנכללים ועולים למעלה מן הפירוד אל היחוד כו' וסיבת ההעלאה שלהן הוא ע\"י שם ב\"ן שמסתתר למטה בעולמות הנפרדים ומבררן וכמ\"ש ותקם בעוד לילה<sup data-n=\"40\">40</sup> ותתן טרף שהוא רפ\"ח ע\"ה<sup data-n=\"41\">41</sup> כו' וכמ\"ש במ\"א. וזהו פי' שמע שם ע' כי כללות ההעלא' מרפ\"ח ע\"י שם ב\"ן נק' שם ולהיות כי עיקר השבירה הי' בז\"ת<sup data-n=\"42\">42</sup> דבינה<sup data-n=\"43\">43</sup> שהוא נק' ע' רבתי כמשי\"ת ע\"כ ההעלא' שלהן הוא בע' רבתי שהוא שרש שרשן להיות כמו שהיו קודם הנפילה והירידה והיינו שהשם נכלל בע' רבתי כו' וד\"ל. ודוגמת זה יובן למטה במה שהמדות הטבעיי' שבחומר הגופני מתהפכין מרע לטוב בשעת התפלה דוקא מפני ההתבוננו' בגדולת אוא\"ס כו' וכן מכל מה שאכל ושתה והתענג בענינים גשמיי' כולן מתהפכין לטוב ע\"י ההתבוננו' וה\"ז עליי' רפ\"ח ניצוצין בע' רבתי שהרי כל עניני' הגשמיי' לא נלקח שרשן רק מרפ\"ח ניצוצי' דתהו כו' וד\"ל. והטעם שנק' העלאת רפ\"ח דוקא בלשון שם כענין שם האדם הוא לפי ששם ב\"ן<sup data-n=\"44\">44</sup> הוא בחי' מל' דאצי' כידוע ונעוץ סופן בתחלתן<sup data-n=\"45\">45</sup> דהיינו בבחי' כתר עליון וידוע דבחי' הכתר<sup data-n=\"46\">11</sup> הוא בחי' ממוצע<sup data-n=\"47\">46</sup> בין המאציל להנאצלים כו' וכמ\"ש במ\"א, והיינו שיש בו ג\"כ מבחי' התחתונה שבמאציל עצמו והוא הנק' בחי' מל' דא\"ס בכללו' ההשתלשלו' כו' והוא רק בחי' שם בלבד וכידוע בפי' המאמר שקודם שנברא העולם<sup data-n=\"48\">47</sup> הי' הוא ושמו בלבד שהוא בחי' מל' דא\"ס שנק' שמו כו' וזהו כי אני הוי'",[["34","34","<b>ועתה</b>: [כאן חסר בגוכי\"ק ו]נעתק מכת\"י 957. 1156."],["35","35","<b>בכתבי האריז\"ל</b>: ראה פרי עץ חיים שער (ז) הק\"ש פ\"ט."],["36","26","<b>שמע שהוא שם ע'. . ע' רבתי</b>: ראה זהר (רעיא מהימנא) פינחס רלו, ב."],["37","37","<b>שם ב\"ן המברר</b>: ראה ג\"כ מאמרי אדה\"ז פרשיות ע' ריט."],["38","38","<b>ויעש דוד שם</b>: שמואל-ב ח, יג."],["39","39","<b>ומשם יפרד</b>: בראשית ב, י."],["40","40","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["41","41","<b>טרף שהוא רפ\"ח ע\"ה</b>: בסה\"מ תקס\"ה ע' תרפה — בע\"ח. וראה מקדש מלך לזהר אחרי ס, א (מט, א)."],["42","42","<b>עיקר השבירה הי' בז\"ת</b>: ראה עץ חיים שער (ח) פ\"ב. שער (ט) שבירת הכלים פ\"ו."],["43","43","<b>השבירה. . דבינה</b>: ראה מבוא שערים ש\"ב ח\"א פ\"א. סה\"מ תקס\"ה ע' תשיט."],["44","44","<b>ששם ב\"ן. . מל' דאצי'</b>: ראה עץ חיים שער (לט) מ\"ן ומ\"ד דרוש ז."],["45","45","<b>ונעוץ סופן בתחלתן</b>: ספר יצירה פ\"א, מ\"ז."],["46","11","<b>הכתר דאצי' שנק' אין</b>: נסמן לעיל ע' ד."],["47","46","<b>הכתר. . ממוצע</b>: ראה ע\"ח שער (מב) דרושי אבי\"ע פ\"א. סידור שו, א."],["48","47","<b>שקודם שנברא העולם</b>: בסה\"מ תרנ\"ד (קה\"ת — תשמ\"ג) ע' רחצ: בפדר\"א. . (כן הוא הלשון בפרד\"ס [שער (ד) עצמות וכלים פ\"ח הקב\"ה] ובשל\"ה ועמ\"ש בשל\"ה ד\"ד ע\"א וכ\"ה הלשון בכה\"מ בלקו\"ת ובשא\"ד, וע' בתו\"א פ' וירא ד\"ה פתח אלי' [יד, א], ובד\"ה רפאני תקס\"ח [סה\"מ תקס\"ח (קה\"ת — תשל\"ב) ע' רטז]. — וראה הנסמן במאמרי אדה\"ז פרשיות (פ' יתרו) ע' שיג."]]],[2100490067,"הוא שמי<sup data-n=\"49\">48</sup> בלבד וכמ\"ש במ\"א וד\"ל. ומה שהע' הוא ע' רבתי דוקא הענין הוא מפני שבחי' הז\"ת דאימא שהוא הנק' ע' רבתי כנ\"ל הרי הוא בחי' המדות שבשכל שהן גדולים הרבה בהתפשטות והתרחבות גדולה מאד לכך נק' ע' רבתי מלשון גדלות ביותר (ולפי שכל מדה מז' המדות כלולה מי' כידוע ע\"כ נק' ע' דז\"פ י' בגימ' שבעים כו'), והטעם הנה יובן באדם התחתון למטה שהמדות שהן כבר נמשכו בלב בהתגלות ההתפעלות אהבה או שנאה ופחד כו' הם עדיין בבחי' הקטנות מאד משא\"כ מקור התפעלות המדות כמו שהן עדיין בשכל והתבוננו' שם הוא התפשטות התפעלותם בלתי מוגבלת כלל, והמופת לזה ממה שאנו רואים שלא יוכל איש להביא בלבו כל ההתפעלות שנתפעל בשכלו כמו שהיא ממש במוחו אלא רק אפס קצהו מתפשט בלב בהתפעלות הלב כנראה זה בחוש כו' וע\"כ נק' המדות שבשכל בשם ע' רבתי מפני בחי' הגדלות שבהן ששם הן גדולים מאד משא\"כ בלב הן באים בבחי' הקטנות כו' וד\"ל וזהו שנק' המדות שבלב בשם אתוון זעירין והמדות שבשכל בשם אתוון רברבין כו' והוא ענין הע' רבתי שהוא בחי' ז\"ת דאימא כו' (והיינו ג\"כ הטעם שנק' בחי' המדות עליונות דאצילות שיצאו מז\"ת דאימא בשם זעיר אנפין כי הרי הוא בבחי' הקטנות בבחי' אותיות קטנות הנק' בשם אתוון זעירין כו' וד\"ל). והנה כתיב אני ראשון ואני אחרון<sup data-n=\"50\">49</sup> כו', פי' אני ראשון הוא בחי' מל' דא\"ס שבכתר עליון כנ\"ל ואני אחרון הוא בחי' מל' דאצי' שהוא שם ב\"ן המברר כנ\"ל ב\"פ אני הללו הכל א' בהשוואה לפני עצמותו ומהותו של אור א\"ס ב\"ה וכמ\"ש אני הוי' לא שניתי<sup data-n=\"51\">50</sup>, פי' אין בו שינוי גם מקודם השבירה והתיקון לאחר השבירה והתיקון או כמו שהוא בשעת התיקון והבירור עכשיו דהיינו ג' זמנים הללו דקודם השבירה ובשעת התיקון עכשיו דכתיב היום לעשותם<sup data-n=\"52\">51</sup> כו' ולאחר שיושלם הבירור והתיקון לע\"ל לאחר תח\"ה כו' כולם שוין לפניו ממש משום דקמי' ממש כחשיכה כאורה<sup data-n=\"53\">52</sup> כו' ולא הי' ענין השבירה בחי' שינוי אלא לגבי המקבלים בלבד למטה מפני שנעשה בהן ירידות האור כו' אבל קמי' עצמותו אין השבירה ענין ירידה ולא התיקון אח\"כ ענין עלי' כי מאחר דקמי' כחשיכה כאורה כו' ממש בשוה א\"כ גם בחי' החושך וההסתר שנעשה מסיבת השבירה ובחי' האור שנעשה ע\"י התיקון שוה ג\"כ לפניו כו' ומ\"ש וימלוך וימת<sup data-n=\"54\">53</sup> כו' היינו רק לגבי בחי' ההשתלשלות של העולמות בלבד כו' וד\"ל.\n<b>וביאור</b> הדברים יובן הטעם שלא הי' השבירה רק בבחי' הכלים ועי\"ז גרם הסתלקות האורות<sup data-n=\"55\">54</sup> כידוע דהאורות דתהו נסתלקו<sup data-n=\"56\">55</sup> כו' וירד מהן למטה",[["49","48","<b>כי אני הוי' הוא שמי</b>: ראה ישעי' מב, ח."],["50","49","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["51","50","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["52","51","<b>היום לעשותם</b>: ואתחנן ז, יא."],["53","52","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["54","53","<b>וימלוך וימת</b>: וישלח לו, לב. לג."],["55","54","<b>השבירה. . האורות</b>: ראה ג\"כ מאמרי אדה\"ז פרשיות ע' תשכא."],["56","55","<b>דהאורות דתהו נסתלקו</b>: ראה עץ חיים שער (ח) דרושי הנקודות ספ\"ד."]]],[2100490068,"רפ\"ח ניצוצים כו' והנה ידוע שאין ערוך כלל וכלל בין בחי' אור לבחי' המאור עצמו ועד\"מ זיו ואור השמש לגבי השמש עצמה שנק' מאור כידוע והרי כשיסתירו האור והזיו של השמש בעננים ומסכים רבים וכיוצא הרי אין זה בחי' שינוי כלל לגבי עצמות מאור השמש כי איננו בגדר אור וזיו שיסתירנו מסך מבדיל כו' ועד\"מ זה יובן גם למעלה שנאמר כי שמש ומגן<sup data-n=\"57\">56</sup> ה' אלקים וכידוע וע\"כ נק' הנאצלים בשם אורות עליונים כי הן רק בבחי' זיו ואור לגבי עצמות המאציל שנק' בחי' מאור כו' וע\"כ נא' דקמי' כחשיכה כאורה כו' וכנ\"ל וא\"כ אין שינוי לפניו כלל מקודם השבירה לאחר השבירה ומקודם התיקון לאחר התיקון גם באלף הז' כו' מטעם זה וד\"ל. וזהו פי' ב' תיבות דק\"ש דשמע<sup data-n=\"58\">57</sup> ישראל, פי' שמע שם ע' כנ\"ל היינו בחי' העלאות רפ\"ח ניצוצים דתהו שעולין ונכללין בע' רבתי שרשם כנ\"ל עד שיהיו כמו שהיו קודם השבירה כו' והוא משום דע\"י העלאת מ\"ן זה דרפ\"ח כו' הרי המה עולין עד עצמות אור א\"ס ששוה לפניו כחשיכה כאורה כו' עד אשר אז יכול להיות מחושך השבירה כמו שהי' לפני השבירה כו' וד\"ל. והנה העלא' זו דתיבת שמע הוא רק שעלו הניצוצים דתהו בשרשן בלבד והוא בבחי' ע' רבתי שהוא בחי' ז\"ת דאימא כנ\"ל, ואח\"כ עולין עוד עלייה שני' גבוה יותר והוא בבחי' אור אבא שלמעלה מאור אימא הרבה כידוע שהחכמה נק' אין והבינה נק' יש וכנ\"ל וזהו בתיבת ישראל דוקא כי פי' ישראל הוא ישר אל<sup data-n=\"59\">58</sup> כידוע ופי' אל הוא בחי' אור אבא וכמ\"ש בזוהר בדוכתי טובא דאל הוא נהירו דחכמתא<sup data-n=\"60\">59</sup> כו' וכמ\"ש בזהר ע\"פ השמים מספרים<sup data-n=\"61\">60</sup> כבוד אל כו' באריכות איך שהשמים מספרים מנהרין ומנצצין מנהירו דחכמתא כו' וד\"ל ולהיות כן כאשר עולין בחי' רפ\"ח ניצוצים דתהו עד אור אבא בתיבת ישראל וידוע דאור א\"ס אינו שורה רק בחכמה<sup data-n=\"62\">61</sup> בלבד מטעם דהחכמה הוא בבחי' הביטול ונק' כח מ\"ה וכנ\"ל וע\"כ בחי' החכמה הוא דוקא בחי' הממוצע בין אור א\"ס לנבראים בכל עולם ועולם לפי ערכו כמ\"ש למעלה ע\"פ כולם בחכמה עשית כו' ואפי' בבינה אין התלבשות אוא\"ס אלא ע\"י החכמה דוקא הוא שמתלבש בבינה כו' וד\"ל וכנ\"ל בפי' הוי' אלקינו כו' ע\"כ מבחי' עליי' זו השני' דבתיבת ישראל דוקא עי\"ז נמשך האור בעצמות אור א\"ס מפני שמתלבש באור אבא<sup data-n=\"63\">62</sup> דוקא וכנ\"ל, ובכל זה מובן מה הטעם שע\"י העלאת מ\"ן שמב' תיבות הללו דשמע ישראל תחלה הוא שנמשך ונעשה אח\"כ ירידות האור והשפע שיהי' התלבשות אור א\"ס בחו\"ב תרין ריעין כו' והוא ב' תיבות דהוי' אלקינו כנ\"ל ואם לאו לא הי' אור א\"ס מתלבש בחו\"ב כו' כי מפני בחי' העלאות מ\"ן דרפ\"ח כו' עלו הניצוצים בבחי' עלי' אחר עלי' עד שעלו בבחי' העצמו' דקמי' כחשיכה כאורה כנ\"ל ע\"כ הרי יכול משם לחזור ולירד האור בחו\"ב כו', וזהו",[["57","56","<b>כי שמש ומגן</b>: תהלים פד, יב."],["58","57","<b>ב' תיבות. . דשמע</b>: בכמה כת\"י ליתא תיבה ב'."],["59","58","<b>ישראל הוא ישר אל</b>: ראה פי' ר\"מ בוטריל לספר יצירה פ\"א, מ\"א (טו, א). רמ\"ז לזהר ר\"פ שמיני. לקו\"ת שלח מ, ג. סה\"מ תקס\"ד ע' קפא. אור התורה משפטים ע' א'שטז."],["60","59","<b>דאל הוא נהירו דחכמתא</b>: זהר לך צד, א. צו ל, ב. לא, א. אחרי סה, א."],["61","60","<b>השמים מספרים</b>: תהלים יט, ב. וראה זהר תרומה קלו, ב."],["62","61","<b>דאור א\"ס אינו שורה רק בחכמה</b>: ראה תניא פל\"ה בהג\"ה."],["63","62","<b>באור אבא</b>: בכמה כת\"י: בחכמה."]]],[2100490069,"מ\"ש בע\"ח דעכשיו תלוי זה בהעלאת מ\"ן ממעשה התחתונים דוקא וכנ\"ל וד\"ל. וזהו סדר ופי' הפסוק שמע ישראל וע\"כ ממילא ה' אלקינו מטעם הנ\"ל ואח\"כ או' הוי' אחד שהוא בחי' יחוד זו\"נ כידוע.\n<b>והנה</b> מתחלה יש להבין פי' אחד, דהנה לשון אחד אינו שייך רק בב' וג' דברים הנפרדים תחלה ואח\"כ מתייחדים שזהו הנק' אחדות מפני שנתאחדו ב' דברים שהיו מחולקים תחלה אבל בדבר שהוא יחידי מעולם ואין שני להתחבר אליו עמו<sup data-n=\"64\">*62</sup>* לא יתכן לומר בו ענין לשון אחד שהרי אין לו דבר זולתו להתאחד עמו מאחר שהוא יחידי כו' וכמ\"ש בחו\"ה שער היחוד<sup data-n=\"65\">63</sup> וכך הוא ענין למעלה שבבחי' עצמות אור א\"ס כמו שהוא לפני ההשתלשלו' שנק' יחיד חי העולמים<sup data-n=\"66\">64</sup> מפני שאין שני לו כו' א\"כ מאחר שאין עוד מלבדו לא שייך בו לומר לשון אחד אלא לשון יחיד כי הרי הוא יחידי כו' אך בהתגלות אור השפע מאתו בנאצלים שם יתכן לומר ענין ולשון אחד מפני שכבר יצא האור והשפע שם בבחי' התחלקות לכמה מיני מדרגות ויש בהם שהן ב' הפכים כמו חו\"ג ע\"כ בהתחברם יחד נק' אחד וה\"ז כמשל ענין מחלוקת ב' כתות למטה כמו ב\"ש וב\"ה הגם שהן מחולקים מ\"מ אלו ואלו דברי אלקים חיים<sup data-n=\"67\">65</sup> ויכולים להתחבר לשרש ומקור אחד<sup data-n=\"68\">66</sup> מאחר שאלו ואלו דברי אלקים חיים אבל עכ\"ז נק' ב' דברים מפורדים תחלה שהרי אמר בלשון אלו ואלו כו' רק שמתאחדים במה שהן דברי אלקים חיים בכלל כו', וכך יובן הדוגמא מזה למשכיל למעלה שהגם שבחי' המדות עליונות הגדולה והגבו' והתפארת כו' הן כבר בבחי' התחלקות ממש שהרי אין בחסד גבורה ואין בגבורה חסד כו' מ\"מ מתאחדים לשרש ומקור א' שהוא במה שאלו ואלו נמשכים מאור א\"ס המאצילן כו' וד\"ל. וזהו פי' הוי' אחד, פי' הוי' הוא בחי' ז\"א<sup data-n=\"69\">67</sup> דאצי' שנק' הוי' בכלל והוא מתחלק לששה מדות בפרט ולפרטי פרטיות כו', אבל מפני הארת אור א\"ס שבהם המה מתאחדים בתכלית היחוד והוא ענין אות האלף שבאחד כי אות הח'<sup data-n=\"70\">68</sup> מורה על ז' רקיעים וארץ שהן בחי' זו\"נ בכלל והאלף הוא מבחי' אור א\"ס שהוא נק' אלופו של עולם כי בבוא ההארה מאתו יתבטלו כל הנאצלים ויתאחדו בתכלית כמ\"ש לך הוי' הגדולה<sup data-n=\"71\">69</sup> והגבורה כו' וד\"ל. והטעם לסיבת בחי' הביטול שלהם כמ\"ש לך ה' הגדולה כו' הענין הוא לפי שבחי' עצמות אור המאציל הרי הוא מובדל ומרומם בערך מכל ההשתלשלות די\"ס אורות וכלים כמאמר הנ\"ל ולאו מכל אינון מדות כלל כו', א\"כ מאחר שבעצמות המאציל לא יש מכל אינון מדות כלל מפני שגבוה מהם הרבה",[["64","*62","<b>עמו</b>: בכמה כת\"י: אליו."],["65","63","<b>בחו\"ה שער היחוד</b>: [בחובת הלבבות]. ראה שם פ\"ח. תורה אור (וסה\"מ תקס\"ב) וארא נה, ב (ע' קלה). לקוטי תורה ואתחנן יא, ג. אמרי בינה שער הק\"ש פ\"ח."],["66","64","<b>יחיד חי העולמים</b>: ברכת ברוך שאמר וישתבח."],["67","65","<b>אלו ואלו דברי אלקים חיים</b>: עירובין יג, ב."],["68","66","<b>ויכולים להתחבר. . אחד</b>: ראה זהר ויקרא ו, סע\"ב."],["69","67","<b>הוי' הוא בחי' ז\"א</b>: זהר (אדרא רבא) נשא קכט, א."],["70","68","<b>אות האלף. . הח'</b>: ראה בית יוסף לטור אורח חיים סס\"א ד\"ה כתב סמ\"ק."],["71","69","<b>לך הוי' הגדולה</b>: דברי הימים-א כט, יא."]]],[2100490070,"ועליו נא' לך ה' הגדולה כו' מפני שהם שם בבחי' ביטול באמת עד שאין עולין שם בשם מדות כלל ע\"כ גם בירידת האור מעצמות המאציל במדות דאצי' לכך יתבטלו ג\"כ מבחי' ההתחלקות שלהם ויתאחדו בתכלית היחוד כנ\"ל והוא ע\"י אות האל\"ף משום דקמי' ממש לא יש מכל אינון מדות כלל וכנ\"ל וכמ\"ש במ\"א וד\"ל. ואח\"כ ממשיכים יחוד זה בבשכמל\"ו<sup data-n=\"72\">70</sup> והוא בבחי' מל' דאצי' כמו שהיא מסתתרת בבי\"ע שהן עולמות הנפרדים וגם בעולמות והיכלות דבי\"ע יש בחי' היחוד הזה העליון שהי' בבחי' המדות דאצי' רק שהוא בא בירידת המדרגה יותר והיינו שאור א\"ס יורד גם למטה יותר וזהו פי' ברוך לשון המשכה כידוע והוא מבחי' עצמות המאציל בשם כבוד מלכותו שהן ג' עולמות הידועים בי\"ע כו' וזה היחוד נק' יחודא תתאה לגבי יחוד העליון דהוי' אחד כנ\"ל כידוע וד\"ל.\n<b>והנה</b> אחר היחודים הנ\"ל גם בזו\"נ דאצי' בפסוק ראשון דק\"ש ובשכמל\"ו כנ\"ל או' ואהבת עד ובשעריך שהן מ\"ב תיבות נגד שם מ\"ב דאנא בכח כו' כנ\"ל והוא בחי' אור הגבורה בכלי החסד כנ\"ל. ולהבין זה תחלה יש להקדים הטעם שנא' בפ' זו דשמע ואהבת בכל מאדך ובפ' שני' לא נאמר אלא בכל נפשכם ולא בכל מאדכם כו' בהיות מבואר למעלה דעיקר היחוד הנעשה בהוי' אלקינו הוי' אחד הוא מסיבת בחי' העלאות מ\"ן תחלה בב' תיבות דשמע ישראל כו' וענין העלא' המ\"ן מבואר שהוא בחי' עליות הרפ\"ח כו' עד שעולין לבחי' עצמיות אור א\"ס ומשום דקמי' כחשיכה כאורה כו' וגם הרי שם הוא למעלה מבחי' התחלקות כו' ע\"כ ירד האור מאתו אח\"כ בנאצלים להיות על ידו בחי' היחודים הנ\"ל באו\"א וזו\"נ כו' וא\"כ צריך לסיבת היחודים הללו בחי' העלי' בהעלאות מ\"ן תחלה וידוע דכל העלאת מ\"ן א\"א כ\"א ע\"י מס\"נ והוא לצאת מן הגבלת הכלי ולהיות כלתה נפשו דוקא לכלל בעצמות כמ\"ש כלה שארי<sup data-n=\"73\">71</sup> כו' ועי\"ז רוח אייתי רוח<sup data-n=\"74\">72</sup> ואמשיך רוח כו' וכמ\"ש אם ישים אליו לבו אליו דוקא יכלה נפשו לצאת לגמרי מן הכלי כו' וליכלל בעצמותו דוקא אזי רוחו ונשמתו<sup data-n=\"75\">73</sup> יאסוף ההמשכה מלמעלה כו' וזהו שנא' כאן אהבת בכל מאדך כי בחי' מאד הוא התפעלות בלתי מוגבלת כלל דהיינו מה שלא יוכל הלב להכיל כי עד כלות נפשו מגיע עומק ההתפעלות כו' וע\"י המס\"נ שלמטה נעשה גם למעלה בחי' העלאת מ\"ן דרפ\"ח הנ\"ל והוא ג\"כ לצאת האור הנאצל מן הכלי בבחי' עלי' והסתלקות ליכלל בעצמות המאציל וד\"ל כי הנה ידוע דלמעלה ענין בחי' הכלי של האור הוא מה שלמטה נק' בשם גבול מה שמגביל הכח כו' וא\"כ ע\"י בכל מאדך למטה שהיא בלא גבול גם למעלה יהי' האור בלא כלי המגביל והוא עליות האורות והתכללותן במאציל כו' וכנ\"ל בפי' ב' תיבות דשמע ישראל שעולין ונכללין בעצמות אור המאציל דקמי' כחשיכה כאורה כו' וע\"כ נאמר דוקא בפ' זו בכל מאדך וד\"ל. והנה בחי' העלי' וההסתלקות הזאת למעלה ולמטה הוא ע\"י שם מ\"ב דאנא בכח כו' כי",[["72","70","<b>בבשכמל\"ו</b>: פסחים נו, א."],["73","71","<b>כלה שארי</b>: תהלים עג, כו."],["74","72","<b>רוח אייתי רוח</b>: ראה זהר (תרומה) קסב, ריש ע\"ב. (וירא) צט, ריש ע\"ב. אוה\"ת חנוכה רפו, א."],["75","73","<b>אם ישים אליו. . רוחו ונשמתו</b>: ראה איוב לד, יד."]]],[2100490071,"הנה מבואר בכהאריז\"ל<sup data-n=\"76\">74</sup> בכמה דוכתי שכל ההעלאות הוא דוקא ע\"י ש' מ\"ב ולכך בק\"ש שעל המטה שאז זמן העלא' הנשמה של האדם להעלותה להכלל במקור חוצבה (כמ\"ש בידך אפקיד רוחי<sup data-n=\"77\">75</sup> אותיות באר דהיינו בבחי' יסוד דנוק') אומרים אנא בכח כו' שבו מרומז שם מ\"ב כידוע וד\"ל. וכללות ענין שם מ\"ב הוא בחי' הגבורה שהוא בחי' ההסתלקות והעלי' מלמטה למעלה כידוע דשש כנפים שש כנפים שבמלאכים הנושאים הכסא היינו מבחי' שם מ\"ב אלא שבשם מ\"ב יש ז' פעמים ששה כו' והן מ\"ב תיבות דאנא בכח כו' והרי נאמר בהם בשתים יכסה פניו ובשתים יכסה רגליו ובשתים יעופף<sup data-n=\"78\">76</sup> דהיינו בחי' העלי' וההסתלקות מלמטה למעלה מעלה כו' שהוא ענין היציאה מן הכלי הנ\"ל וע\"כ יש בפ' זו מואהבת עד ובשעריך ג\"כ מ\"ב תיבות שהוא בחי' שם מ\"ב לפי שמבואר למעלה דכל עיקר ענין הפ' הזאת הוא בחי' ההעלאו' וההסתלקות מטעם הנ\"ל וכל העלאה א\"א כ\"א ע\"י שם מ\"ב כנ\"ל וד\"ל. אך מה שנק' בחי' זו בשם אור הגבורה בכלי החסד כנ\"ל בתירוץ הקושיא, הענין הוא להיות ידוע דהאור הוא בחי' הפנימיות והכלי הוא בחי' החיצוניות כו' וכמ\"ש במ\"א וגם כאן הרי אמר ואהבת וכל אהבה הוא בחי' חסד<sup data-n=\"79\">77</sup> כידוע<sup data-n=\"e1\">*</sup> אך שהאהבה בבחי' החיצוניות בלבד אבל בחי' הפנימיות שבה הוא בחי' הגבורה דוקא<sup data-n=\"e2\">*</sup> והוא בחי' בכל מאדך שהוא בחי' הסתלקות והעליות לצאת מן הכלי כנ\"ל וא\"כ ה\"ז כמו בחי' אור הגבורה שבכלי החסד דהפנימיות גבורות והחיצוניו' חסד כו' וד\"ל. וזהו ע\"י שם מ\"ב שבפ' זו שהוא בחי' הגבורות ושם זה הרי הוא בחי' הפנימיות כי כל כוונה בשם אינו אלא דוקא בבחי' הפנימיות והוא ע\"י רעותא דלבא בעיקר המכוון של הלב ולכך נק' בשם כוונה כי הוא נעשה דוקא ע\"י כוונת הלב והמכוון שבלב מוסתר הוא בבחי' אור פנימי' והחיצוני' שלו מתגלה לעין הרואה כו' והיינו מ\"ש ואהבת סתם כו' שהוא רק בחי' כלי החסד לגבי אור הגבורה שבשם מ\"ב כו' וזהו נק' ג\"כ בחי' גבורה שבחסד שהגבורה הוא בחי' הפנימיות המוסתר בחסד הנגלה וכמ\"ש במ\"א וד\"ל, והראי' לזה שהאהבה במ\"ש ואהבת הוא רק בחי' כלי לאור כו' כי הרי אותה הפרשה דשמע כתובה היא בתורה סתם דברים כהווייתן ולא",[["76","74","<b>בכהאריז\"ל</b>: ראה פע\"ח שער (ה) עולם העשי' (הקרבנות) פ\"ה. שער (טו) קשעהמ\"ט פ\"ב."],["77","75","<b>בידך אפקיד רוחי</b>: תהלים לא, ו. וראה הנסמן במאמרי אדה\"ז פרשיות (נח) ע' נט."],["78","76","<b>שש כנפים. . ובשתים יעופף</b>: ישעי' ו, ב. וראה פע\"ח שער (ה) עולם העשי' (הקרבנות) פ\"ב. הנסמן לעיל ע' א בהערה בכהאריז\"ל."],["79","77","<b>אהבה הוא בחי' חסד</b>: ראה פרדס שער (כג) ערכי הכנויים מערכת אהבה."],["e1","*","<b>כידוע</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: כמ\"ש אהבת עולם אהבתיך ע\"כ משכתיך חסד."],["e2","*","<b>דוקא</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: פי' שאהבה זו תוכה רצוף בחי' גבורה כי עיקר המכוין הוא להסתלק מן הכלי והגוף וה\"ז בחי' גבורה וזה נשלם ע\"י האהבה והתשוקה שעל ידה נעשה ההסתלקו' והאהבה מצד עצם מהותה היא בחי' חסד רק שאהבה זו היא רק בחי' כלי בכאן והאור שבה ר\"ל הפנימי' שהוא המכוין להיו' הסתלקות מן הכלי הוא בחי' גבורה וזהו ענין אור הגבורה בכלי החסד: והוא בחי'."]]],[2100490072,"נגלה בה שום רמז לשם מ\"ב רק ע\"י מספר התיבות בלבד כו' וא\"כ זהו בהכרח מפני שבחי' החיצוני' הנגלית לנו הוא רק בחי' חסד והוא שאמר ואהבת סתם בלתי רמז לבחי' גבורה אבל בחי' הגבורה והוא ההסתלקות הרי היא רק בהעלם לכך לא נרמז ממנה שום רמז בגלוי הכתב אלא היא מוסתרת בכוונה שבלב בלבד כנ\"ל והוא ע\"י כוונה דשם מ\"ב כנ\"ל וד\"ל (ובכל<sup data-n=\"80\">78</sup> זה מתורץ היטב הקושיא הנ\"ל דפ' שמע הרי היא בחסד כו' דמ\"ש שהיא בחסד היינו בבחי' האהבה החיצוני' בלבד אבל בבחי' הפנימיות שבה היא בחי' גבורות והוא כמו בחי' אור הגבורה שמאיר בכלי החסד וכו' (ובזה מובן מה שהצריכו חז\"ל כוונת הלב בפ' ראשונה<sup data-n=\"81\">79</sup> דוקא כמאמרם עד כאן צריכה כוונת הלב ולא בפ' שניה כו') וד\"ל.\n<b>ועתה</b><sup data-n=\"82\">80</sup> יש להבין שרש ענין פ' שני' והי' א\"ש שהיא בחי' אור החסד בכלי הגבורה כנ\"ל. הנה כתיב והחיו' רצוא ושוב<sup data-n=\"83\">81</sup> כו' שאחרי בחי' ההעלא' הנ\"ל במס\"נ לצאת דוקא מן הכלי כו' שנק' בחי' רצוא כמ\"ש אם רץ לבך<sup data-n=\"84\">82</sup> כו' אזי הוא בחי' השוב מלמעלה למטה שהוא בהיפוך מבחי' הרצוא כי בחי' השוב הוא דוקא ירידת האור והשפע למטה להיו' שורה בכלים מכלים שונים<sup data-n=\"85\">83</sup> כידוע ועל כן לא נאמר כלל בכל מאדיכם בפ' זו דוהי' כי בחי' בכל מאדך הוא ענין היציא' מן הכלי והגבול כנ\"ל ובפ' זו אין העיקר רק בבחי' שוב שהוא דוקא התלבשות האורו' בכלים שהוא ההיפך ממש מבחי' הרצוא שבכל מאדך כידוע (והיינו שאמר ר' יהושע ב\"ק<sup data-n=\"86\">84</sup> במשנה למה קדמה פ' שמע לוהי' כדי שיקבל עליו עול מ\"ש תחלה שהוא ע\"י בחי' הרצוא במס\"נ באהבת בכל מאדך כנ\"ל ואח\"כ יקבל עליו עול מצות שהוא בחי' השוב שבפ' והי' דוקא כנ\"ל וד\"ל) והנה באמת עיקר המכוון שהי' בבחי' הרצוא בפ' שמע הוא רק בשביל בחי' השוב שיהי' אח\"כ כי הרי כתי' לא לתוהו בראה<sup data-n=\"87\">85</sup> אלא לשבת יצרה פי' לא לבחי' הרצוא שהוא בחי' ההסתלקו' של האורו' במאצילן שנק' תוהו בראה וכמ\"ש והארץ הית' תוהו<sup data-n=\"88\">86</sup> כו' אלא לבחי' השו\"ב שיהי' אח\"כ שהוא לשב\"ת אורו' בכלים (והטעם שזה נק' בריא' וזה יצירה מובן לי\"ח עפ\"י המבואר במ\"א) וע\"כ בחי' שם ע\"ב דחסד בפ' זו השני' דוקא להיות כי זהו חסד גדול מה שירד האור ויתלבש בכלים מכלים שונים כו' ולכך יש בה ע\"ב תיבו' עד ושמתם וכוללת גם נ' שערי' דבינה נגד בחי' אור החסד דשם ע\"ב בגי' חסד כנ\"ל והנה מבואר למעלה דהשם הוא בחי' הפנימי' להיותו בחי' הכוונה שבלב כו' וגם כאן בחי' הפנימי' שבפ' זו השני' הוא שם ע\"ב דחס\"ד ובחי' החיצוניו' הוא בחי' כלי הגבורה וע\"כ נא' בפ' זו עניני דיני' ורוגז כמו וחרה<sup data-n=\"89\">87</sup> אף הוי' כו' ועצר את השמים כו' כי בחי' הכלי החיצוניו' הוא בחי' גבורה ודין וד\"ל.",[["80","78","<b>(ובכל</b>: בהכת\"י לא נסמן סיום החצאי עיגול."],["81","79","<b>כוונת הלב בפ' ראשונה</b>: ראה ברכות יג, ב."],["82","80","<b>ועתה</b>: מכאן ואילך מגוכתי\"ק."],["83","81","<b>והחיו' רצוא ושוב</b>: יחזקאל א, יד."],["84","82","<b>אם רץ לבך</b>: ספר יצירה פ\"א, מ\"ח."],["85","83","<b>בכלים מכלים שונים</b>: ע\"ד אסתר א, ז."],["86","84","<b>שאמר ר' יהושע ב\"ק</b>: ראה ברכות רפ\"ב (יג, א)."],["87","85","<b>לא לתהו בראה</b>: ראה ישעי' מה, יח."],["88","86","<b>והארץ הית' תהו</b>: בראשית א, ב."],["89","87","<b>וחרה. . ועצר</b>: עקב יא, יז."]]],[2100490073,"<b>ולהבין</b> הענין הזה איך שהיא בבחי' הגבורו' והדינין כו' הנה תחלה יש להבין פי' שם ע\"ב למה הוא במספר ע\"ב כו' וגם הטעם מה שנקראי' בשם ע\"ב גשרים<sup data-n=\"90\">88</sup> כידוע, דהנה עד\"מ הגשר שעושין ע\"פ הנהר עושין אותו בבנין חדרים קטני' זה אצל זה ומכסין עליהם ומצדדי' שלהם בנסרים והמים הולכי' בין הגשר העליון וביניהם עפ\"י מדידה וקצבה בלבד בצמצומי' הרבה ואם לא בנין החדרים הללו היו המים שוטפי' בשטף רב ויפוצו את הארץ כו' אבל החדרי' עשויי' לצמצם להעביר בהן מי הנהר בצמצום מעט מעט כפי המדה הצריכה כידוע ועל תועלת זה הוא כלל ענין בנין החדרי' ופרטי אופני התחלקו' ריבוי החדרים הוא לפי אופן המצטרך לגשר אם הנהר גדול ביותר ירבו בו החדרים ואם אינו גדול כ\"כ ימעטו מספר החדרי' כו' והנמשל מכל אלה יובן למשכיל למעלה כי בהיו' שאור החסד העליון של המאציל הרי הוא יוצא בשפע רב מאד עד\"מ הנהר הגדול כו' והנה אם הי' יוצא כמו שהוא לא הי' מתקבל כלל למטה בהשתלשלו' העולמו' עד\"מ הנהר הגדול ששוטף כו' ע\"כ הוצרך לעשות ע\"ב גשרים עד\"מ בנין החדרי' הנ\"ל והוא להיו' בא אור החסד הזה בהתחלקו' לע\"ב חלקי החסד קטני' ושיצומצם על ידן להיו' אור החסד הולך ואור מעט מעט ולא בשטף כו' ולכך נק' שם ע\"ב שבחסד עליון בשם ע\"ב גשרים כי מטעם תועלת המקבלי' כדי שיוכלו לקבל כו' נתחלק לע\"ב חלקי' כו' וד\"ל וגם עוד תועלת יש בהתחלקו' הזאת כי הנה אם הי' האור הולך ומאיר כמו שהוא לא הי' נמצא למטה ענין התחלקו' המדרגו' במדת החסד אלא הי' הכל מציאת אור חסד א' בלבד והרי אנו רואי' ריבוי התחלקו' המדרגו' במדת החסד כמו ע\"ד דוגמא הנה ידוע דיום הראשון<sup data-n=\"91\">89</sup> מו' ימי בראשית האיר אור החסד ולכך נברא בו כל הדברי' שהן ממדרגת מדת החסד והוא כמו מאמר יהי אור<sup data-n=\"92\">90</sup> וידוע שהאור הוא מבחי' החסד כו' ונברא בו גם המים שהוא ג\"כ ממדת החסד<sup data-n=\"93\">91</sup> וכיוצא בזה למטה במראו' הגוונין דלובן<sup data-n=\"94\">18</sup> שמורין בחי' החסד<sup data-n=\"95\">92</sup> יש הרבה מדרגו' כו' וכן בטעמי' מתיקו' יש בו הרבה מינים וכיוצא בכל אלה הרי מהיכן ימצאו ריבוי התחלקו' כאלה אור ומים למעלה<sup data-n=\"96\">93</sup> לבן ומתיקו' כו' למטה כי אם הי' השפע אור חסד העליון הולך ונובע בלתי התחלקו' הרי הי' צריך להיו' הכל רק מציא' דבר א' בלבד אם אור או מים כו' אלא מפני בחי' ההתחלקו' לע\"ב חלקי' בע\"ב גשרי' הנ\"ל מזה ימצא בחי' ריבוי התחלקו' מיני חסד גם למטה וד\"ל.\n<b>והנה</b> מה שנחלק לע\"ב חלקי' בלבד זהו במקורו שהוא מתחלק דרך כלל עדיין אבל בבוא אור החסד עד למטה מטה בריבוי ההשתלשלו' מתחלק לרבבו' מדרגו' עד אין שיעור כו' והיינו מה שאנו מוצאי' שיש רבבו' מדרגו' בקבלת זיו",[["90","88","<b>ע\"ב גשרים</b>: פרדס שער (כא) פרטי השמות פ\"ה. שער (כג) ערכי הכנויים מערכת חסד. שיעור קומה (לרמ\"ק) סצ\"ד."],["91","89","<b>דיום הראשון. . החסד</b>: ראה שער היחוד והאמונה פ\"י."],["92","90","<b>יהי אור</b>: בראשית א, ג. וראה אור החמה לזהר בראשית מו, א."],["93","91","<b>המים. . ממדת החסד</b>: זהר שמיני מא, א."],["94","18","<b>בן. . המברר</b>: ראה ג\"כ מאמרי אדה\"ז פרשיות (שמות) ע' ריט."],["95","92","<b>הגוונין דלובן. . החסד</b>: ראה פרדס שער (י) הגוונים פ\"א."],["96","93","<b>שו\"ה התחלקו' — למעלה</b>: בגוכי\"ק יש סימן עגול בפנים ועה\"ג ניתוספה תיבה זו."]]],[2100490074,"השכינה בג\"ע העליון והתחתון שהוא ג\"כ מבחי' אור החסד האלקי במה שיהנו מזיוו ואורו כו' עד שיש לכל צדיק וצדיק ש\"י עולמו'<sup data-n=\"97\">94</sup> כו' ויש רבוא רבבו' מלאכי' חלוקי' במדרגו' השיר שלהם ג\"כ זה מרנן ומנגן כך וכך וזה כך וכך והכל ממדרג' החסד וכמבואר בהיכלו' דפ' פקודי דלסטר דרומא מאת אלף כו' וכן מתחלקי' הן במדרגו' קבלו' הזיו והאור מאור וזיו השכינה שנתלבשה למטה בסטרא דדרום בריבוא רבבו' מדרגו' שונו' כו' כי כל זה הוא ע\"י התחלקו' פרטיו' דפרטיו' משם ע\"ב העליון שהוא בחי' הכולל במקור החסד כו' וד\"ל וזהו ששם ע\"ב בגי' רי\"ו<sup data-n=\"98\">95</sup> מספר גבורה כי זה ההתחלקו' א\"א כ\"א ע\"י צמצום ומיעוט האור אמנם הוא רק בשביל תועלת המקבלי' כדי שיתקבל בהן החסד ע\"כ בחי' הפנימי' המכוון הוא בחי' אור החסד ובחי' החיצוניו' שלו הוא בחי' הגבורה והוא בחי' הצמצום לחלק החסד לע\"ב חלקי' בכלל כנ\"ל וזהו שפ' זו דוהי' הוא בבחי' אור החסד שבכלי הגבורה דהיינו כונת שם ע\"ב הוא פנימיו' והוא אור החסד כנ\"ל וענין התחלקות בע\"ב גשרים הוא בבחי' הכלי שהוא החיצוני' כי עיקר המכוון לבחי' חסד הוא כו' וד\"ל ובזה יובן מה שאומרי' בברכת אתה גיבור<sup data-n=\"99\">96</sup> כו' מוריד הגשם וידוע שהגשמי' יורדין בגבורה<sup data-n=\"100\">97</sup> ולכאורה אינו מובן דהלא הגשם צריך האדם לפרנסה שהוא מבחי' החסד ואיך או' אותו בברכת אתה גבור כו' אלא הענין הוא כנ\"ל דלפי שאור החסד לא יבא למקבלי' כ\"א ע\"י התחלקו' ע\"כ גם הגשמי' שהן חסד וברכה בעצם אבל צריכין לבא בבחי' התחלקו' טיפין טיפין<sup data-n=\"101\">98</sup> דאם לאו הי' שוטפי' העולם כמי המבול והי' דין וגבורה ולא חסד וע\"כ או' אותו באתה גבור כו' מפני שצריכין לירד בגבורה והיינו כמו בחי' הכלי גבורה שבחסד דע\"ב הנ\"ל ומפני שמטר דוקא יורד בגבורה כו' לכך או' אותו בפ' זו דוהי' כמ\"ש ונתתי מטר ארצכם<sup data-n=\"102\">99</sup> כו' דשם ע\"ב זה בגי' גבורה כנ\"ל וד\"ל.\n<b>ועתה</b> יש להבין מה שאמר בפ' זו ונתתי מטר כו' דלכאורה זה פלא, דהלא משה אמר פ' זו ואיך יאמר ע\"ע ונתתי כו' וגם למה לא אמר כלשון זה בכל פרשיו' שאמר במשנ' תורה רק בפ' זו אמר כן והגם דידוע שהיתה שכינה מדברת מתוך גרונו<sup data-n=\"103\">100</sup> של משה הרי אכתי תקשה למה לא אמר כן בשאר הפרשיו' שג\"כ הית' שכינה מדברת בו כו', אך הענין יובן עפ\"י ענין הנ\"ל דבפ' זו הוא בחי' המשכת אור א\"ס למטה דוקא בכלים מכלים שונים ע\"י שם ע\"ב כו' והנה ידוע דאין התלבשו' אור א\"ס אלא בחכמה מטעם שהוא בחי' ביטול כו' שאז אינו מרגיש א\"ע כלל לבחי' יש ודבר ומה שמדבר אין זה של עצמותו כלל אלא רוח ה' שמדבר בו וז\"ש ודברי",[["97","94","<b>לכל צדיק וצדיק ש\"י עולמות</b>: עוקצים בסופה."],["98","95","<b>ששם ע\"ב בגי' רי\"ו</b>: ראה זהר בשלח (נב, א) ער, א. פרדס שער (כא) פרטי השמות פ\"ה. פע\"ח שער (כה) תפילות ר\"ה פ\"ז."],["99","96","<b>בברכת אתה גיבור</b>: שמו\"ע."],["100","97","<b>שהגשמי' יורדי' בגבורה</b>: תענית ב, א."],["101","98","<b>טיפין טיפין</b>: ראה ב\"ב טז, א."],["102","99","<b>ונתתי מטר ארצכם</b>: עקב יא, יד."],["103","100","<b>שכינה מדברת מתוך גרונו</b>: תניא פל\"ד (אמרו עליו). אגה\"ק סכ\"ה (כמארז\"ל). אור תורה בחוקותי מג, סע\"ג (ומ\"ש רז\"ל). שו\"ת בית אפרים חאה\"ע סק\"ז (מו, א — מאחז\"ל). וראה זהר פנחס רלב, ב. שם תוספתא שו, ב. ויקרא ז, א. ואתחנן רסה, א. שמו\"ר פ\"ג, טו. ויק\"ר פ\"ב, ג. מכילתא שמות יח, יט. עיון יעקב לפסחים סח, ב."]]],[2100490075,"אשר שמתי בפיך<sup data-n=\"104\">101</sup> כו' וכמ\"ש במ\"א ע\"פ ולא תחללו<sup data-n=\"105\">102</sup> את שם קדשי כו' פי' ולא תעשו חלל בלבד כו' אלא יהי' בנפשו רק כמו בחי' כלי בלבד לאור השורה בו כו' וכענין שכינה מדברת מתוך גרונו של משה כו' אך אמנם א\"א להיו' זאת המדרגה כ\"א כאשר יוקדם אליה בחי' מס\"נ דבחי' הרצוא הנ\"ל שאז יוכל לבטל א\"ע מכל וכל ולהיו' רק כמו בחי' כלי בלבד אבל בלא מס\"נ בתחלה הרי ירגיש עצמותו מאד כו' וד\"ל וזהו שבפ' זו דוהי' נאמר בכל נפשיכם שהוא בחי' ביטול במציאו' מכל וכל כענין ולא תחללו כו' והוא מפני שכבר קדם במדרג' מס\"נ בפ' ראשונה כנ\"ל דהיינו באהבת בכל מאדך כנ\"ל וע\"כ דוקא בפ' זו השני' הוא בחי' המשכת אור א\"ס למטה בכלים מכלים שוני' ע\"י שם ע\"ב כנ\"ל כי עתה דוקא יוכל להיות בנפש האדם בחי' הביטול ויוכל לשכון בנפשו אור א\"ס כי אין התלבשו' אור א\"ס אלא בבחי' הביטול כנ\"ל וע\"כ גם כל אדם יכול לומר ונתתי מטר ארצכם כמו שאמר משה כו' שאינו אומר זה על עצמו כ\"א בחי' אור א\"ס ששורה בנפשו אומר ונתתי כו' מפני שאינו אלא בחי' כלי לאור א\"ס בלבד מטעם הנ\"ל כי מאחר שבפ' ראשונה הי' לו מס\"נ הרי יכול להיו' כלי להמשכו' אור א\"ס בפ' שני' זו באמרו בכל נפשיכם ולאו דוקא משה כו' אלא רק שמשה<sup data-n=\"106\">103</sup> הי' שרש נשמתו מבחי' הביטול דשם מ\"ה דחכמ\"ה כידוע וע\"כ היתה שכינה מדברת מתוך גרונו ואעפ\"כ בשאר הפרשיו' לא אמר כלשון ונתתי כי דוקא בפ' זו המשכת אור א\"ס בכלי כי הרי הוא בבחי' אור החסד שבכלי כנ\"ל וד\"ל וזהו שאמר ונתתי מטר ארצכם פי' מ\"ד נק' מטר<sup data-n=\"107\">104</sup> ומ\"ן נק' ארצכם ושניהם באין ונמשכי' למטה בשם ע\"ב הנ\"ל במדידה כמה כו' וכענין שירו' של המלאכי' וקבלת זיו שלהן שנק' מ\"ן ומ\"ד ג\"כ והוא בא למטה במדידה וקצבה ע\"י שרש ההתחלקו' דשם ע\"ב בע\"ב גשרים בכלל במקור החסד כנ\"ל וד\"ל.\n<b>והנה</b> ידוע דבפ' זו שנגד שם ע\"ב הרי כלולי' בה ג' השמו' ע\"ב היוצאי' מג' פסוקי' הידועי' שהן ויסע ויבא ויט<sup data-n=\"108\">105</sup> כו' וידוע שהן בבחי' ישר והפוך וישר כו' והענין הוא מפני שגם בחי' הצמצום של אור החסד דשם ע\"ב הנ\"ל צריך להיו' בג' מדרגו' שבבחי' ג' הקוין כו' והוא בבחי' אור ישר מלמעלה למטה ובבחי' אור חוזר מלמטה למעלה ואח\"כ בבחי' אור ישר בבחי' מלמעלה למטה שע\"י אמצעו' ג' מדרגו' הללו דוקא יתקיים אור השפע למקבלי' והוא ענין ג' שמו' ע\"ב הישר וההפוך והישר ואם לאו עדיין לא היתה יכולה השפע להתקבל במקבלי' כו' ומבואר זה לי\"ח וד\"ל.",[["104","101","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["105","102","<b>ולא תחללו</b>: אמור כב, לב. ראה תורה אור יתרו סח, ב. לקו\"ת ויקרא ד, ד. חקת (וסה\"מ תקס\"ה) נז, ב (ע' תרעה). שיר השירים א, א. שם (וסה\"מ תקס\"ד) יב, ד (ע' ח)."],["106","103","<b>שמשה. . מ\"ה דחכמ\"ה</b>: ראה לקוטי שיחות (ח\"ו) הוספות / שמות ע' 244."],["107","104","<b>מ\"ד נק' מטר</b>: ראה פע\"ח שער (ז) הק\"ש פכ\"ד."],["108","105","<b>ויסע ויבא ויט</b>: ראה בשלח יד, יט. כ, כא. זהר בשלח נב, א. פרדס הנ\"ל."]]],[2100490076,"<h3>נוסח שני: שמע ישראל</h3>\n<b>שמע</b> ישראל<sup data-n=\"109\">1</sup> הוי' אלקינו<sup data-n=\"110\">*1</sup>* כו' הנה ד' בתי תפילין<sup data-n=\"111\">2</sup> קדש והי' כי יביאך חו\"ב שמע והי' אם שמוע חו\"ג כו' ולכך נא' בוהי' אם שמוע וחרה אף ה'<sup data-n=\"112\">3</sup> כו' וא\"כ יש להפלא על מ\"ש בכוונות דשמע יש לכוין שם מ\"ב דאנא בכח בחי' גבורה ובוהי' אם שמוע שם ע\"ב<sup data-n=\"113\">4</sup> כו' והלא נהפוך הוא. אך הנה נא' בזהר לאכללא שמאלא בימינא<sup data-n=\"114\">5</sup> אור החסד נכנס בכלי הגבורה<sup data-n=\"115\">6</sup> ואור הגבורה בכלי החסד וזהו דשמע הכלי היא בחי' חסד והאור שהוא השם הוא בחי' גבורה ונק' מ\"ב כו' וכן והי' אם שמוע הכלי היא גבורה והאור הוא חסד שם ע\"ב כו' וביאור הדבר הנה פי' יש מאין עד\"מ למטה שמים וארץ גשמיי' נתהוו בכל רגע המחדש בכל יום<sup data-n=\"116\">7</sup> מעשה בראשית מעצמו' א\"ס בלתי בע\"ג למעלה מן הזמן כו' ולמעלה ג\"כ אנת חכים<sup data-n=\"117\">8</sup> ולא בחכמ' ידיעא שהוא למעלה הרבה מהנאצלי' ובראשית הבריא' הי' חסד חנם<sup data-n=\"118\">9</sup> כי חפץ חסד<sup data-n=\"119\">10</sup> כו' בריש הורמנתא דמלכא<sup data-n=\"120\">11</sup> כו' כד סליק ברעותא<sup data-n=\"121\">12</sup> ועכשיו צריך להמשיך<sup data-n=\"122\">13</sup> להיות אנת חכים מקור לחכמ' כו' והיינו ע\"י ק\"ש שמע ישראל הוי' אלקינו פי' ה' אלקינו יחוד או\"א<sup data-n=\"123\">14</sup> דבחי' אבא הוא למעלה מן ההשגה כח מ\"ה בחי' ביטול ועיקר ההשגה הוא הבינה שלכך נק' אלקינ\"ו שלנו צריך לעשו' יחוד שיושפע אור א\"ס המלובש בחכמ' דווקא<sup data-n=\"124\">15</sup> הוי' בחכמ'<sup data-n=\"125\">16</sup> לבחי' הבינה בתחתוני' כו' ומי הגורם היחוד הוא ע\"י מה שהקדים תחלה באומרו שמע ישראל הוא בחי' תשובה לברר הבירורי' ע\"י מה שהאדם אוכל, ומתפלל עי\"ז וכן כל ל\"ט מלאכו' החורש כו' וכן למעלה ע' רבתי פי' רפ\"ח ניצוצי' דתהו שנפלו ושם ב\"ן דתיקון במילוי ההי\"ן המברר נק' שם בגי'<sup data-n=\"126\">17</sup> לפי שהשבירה והתיקון אינו אלא אצלינו שלא היתה רק באורו' משא\"כ אליו ית' לא שייך לומר שום שייכות בעצמותו מהשבירה כחשכה כאורה<sup data-n=\"127\">19</sup> וכמו שאין נוגע להשמש במה שהענן מסתיר זיוו כך אני הוי'. . הוא שמי<sup data-n=\"128\">20</sup> שם בלבד כו' והנה העלי'",[["109","1","<b>שמע ישראל</b>: נעתק מבוך 1116 עט, א גוכתי\"ק כ\"ק אדמו\"ר הצ\"צ. נו\"א לעיל ע' א. וש\"נ.\nמאמר זה נעתק בדרך מצותיך שרש מצות התפלה פי\"ב-פט\"ו.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשכ."],["110","*1","<b>שמע ישראל הוי' אלקינו</b>: ואתחנן ו, ד."],["111","2","<b>ד' בתי תפילין</b>: ראה הנסמן לעיל ע' א הערה 6."],["112","3","<b>וחרה אף ה'</b>: עקב יא, יז."],["113","4","<b>שם מ\"ב. . ע\"ב</b>: נסמן לעיל ע' א הערה 3."],["114","5","<b>לאכללא שמאלא בימינא</b>: נסמן לעיל ע' ב הערה 8."],["115","6","<b>אור החסד נכנס בכלי הגבורה</b>: ראה לעיל ע' ב בע\"ח שער מול\"מ."],["116","7","<b>המחדש בכל יום</b>: ראה ברכת יוצר."],["117","8","<b>אנת חכים</b>: ראה תקוני זהר בהקדמה יז, ב."],["118","9","<b>ובראשית הבריא' הי' חסד חנם</b>: ראה עץ חיים שער (ו) דרושי הנקודות ספ\"ו."],["119","10","<b>כי חפץ חסד</b>: מיכה ז, יח."],["120","11","<b>בריש הורמנתא דמלכא</b>: זהר בראשית טו, א."],["121","12","<b>כד סליק ברעותא</b>: נסמן לעיל ע' ג."],["122","13","<b>ועכשיו צריך להמשיך</b>: עץ חיים שם."],["123","14","<b>ה' אלקינו יחוד או\"א</b>: נסמן לעיל ע' ד."],["124","15","<b>אור א\"ס המלובש בחכמ' דוקא</b>: ראה ג\"כ הג\"ה בתניא פל\"ה."],["125","16","<b>הוי' בחכמה</b>: משלי ג, יט."],["126","17","<b>רפ\"ח. . בן. . שם בגי'</b>: ראה פרי עץ חיים שער (ז) הק\"ש פ\"ט."],["127","19","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["128","20","<b>אני הוי'. . שמי</b>: ישעי' מב, ח."]]],[2100490077,"דבחי' ב\"ן רפ\"ח הוא בע' רבתי דמשם הי' שרש השבירה ופי' ע' ז' מדו' וכאו\"א כלול מיו\"ד ונק' רבתי להיו' זהו קודם שנתפשטו בלב שהוא בחי' הכלי שהרי ביד לא יהי' התפעלו' כו' הי' כלולי' בשכל ואז היו יותר רחבי' כי הלב לא תקבל רק הארה בלבד כו' וזהו שנק' ע' רבתי פי' רחבי' אתוון רברבן לך ה' הגדולה<sup data-n=\"129\">21</sup> כו' ואחר שנמשכו בלב הם מצומצמי' והוא בפרצוף ז\"א אתוון. . ונק' זעיר כו' וכל העליי' הזאת הוא רק בבחי' הרצוא ואח\"כ שוב בחי' ישראל נהירו. . השמים מספרי' מתנוצצי'<sup data-n=\"130\">22</sup> כבוד אל כו' ועי\"ז אח\"כ נגמר היחוד להיות הוי' אלקינו שנמש. . מלמעלה למטה שתבא השפע מחכמ' לבינה יש מיש משא\"כ החכמ' מאין תמצא<sup data-n=\"131\">23</sup> לכך מתלבש בה אור א\"ס עוטה אור<sup data-n=\"132\">24</sup> כו' ואח\"כ הוי' אחד א\"ח ט\"ס דז\"א ד' לאה בשכמל\"ו רחל<sup data-n=\"133\">25</sup> שכ.. ג' עולמו' כו' והנה אין שייך לומר אחד אם אין כלל רק מהו' אחד בלבד דממי ישלול. . הי' אפשר לומר כו' וכמו אלו ואלו דברי אלקי' חיים<sup data-n=\"134\">26</sup> דאם לא הי' רק דעה אחת לא הי' אומר כלל שהיא דבר אלקי' חיים דאיך אפשר לומר מאחר שאין סברא אחרת רק. . שיש שני' והי' אפשר שא' טעה לכך צריך לומר אלו ואלו כו' כך לפי שז\"א יש בו הת.. חסד שבגבורה וגבורה שבחסד כו' שהי' אפשר לומר שהוא בחי' פירוד לכך אומר אחד כו' והוא א' ח\"ד ע\"י המשכו' אור א\"ס הנק' אלף נעשה חד כו'.\n<b>ואהבת</b> הנה מכאן מתחיל שם מ\"ב<sup data-n=\"135\">27</sup> שכל ההעלאו' הם על ידו בשתים יעופף<sup data-n=\"136\">28</sup> עלי' הנשמה אומרי' אנא בכח לפי ששרשו מבחי' גבורו' עליי' והסתלקות כו' והנה בכל מאדך בלי כלי בלי גבול והוא הסתלקות בעצמותו ליפרד מן הכלי והוא בחי' גבורו' רק שאור הגבורה נכנס בכלי החסד שההסתלקו' דגבורו' נגמר ע\"י החסד האהבה ואהבת עד בכל מאדך כו' וזהו דשמע הוא ש' מ\"ב שהוא הפנימי' שהרי אינו מפורש בתורה רק הוא הכוונה שהמכוון והפנימי' הוא גבורה הסתלקות כו'. אך לא לתהו בראה<sup data-n=\"137\">29</sup> לשבת יצרה להמשיך אורות בכלי' זהו בפרשה והי' אם שמוע שבו לא נאמר בכל מאדך רק בכל נפשך המשכות למטה ע\"י השוב בחי' ביטול ולכך הוא שם ע\"ב כי ע\"ב הוא ע\"ב גשרי'<sup data-n=\"138\">30</sup> שבחסד וכמו הגשר מסתיר ומצמצם המים לבלתי ישטפו בשטף רב על הארץ והמים יוצאי' מן החדרי' העשוי' בו מחדר זה כך ומחדר השני כך כו' וכך הנה יום ראשון חסד<sup data-n=\"139\">31</sup> נבראו בו כמה בחי' מים אור<sup data-n=\"140\">32</sup> כו' והוצרך להיו' ע\"ב גשרים כמה מיני המשכות משא\"כ אם הי' השפעה באופן אחד לא הי' כמה ברואי' כו' וזהו דהמכוין הוא שם ע\"ב בחי' חסד שיבראו הברואי' רק שבא ע\"י הכלי דגבורה הוא הצמצומי' שמתצמצם השפע ונק' רי\"ו כו'",[["129","21","<b>לך ה' הגדולה</b>: דברי הימים-א כט, יא."],["130","22","<b>השמי' מספרי' מתנוצצי'</b>: תהלים יט, ב. וראה זהר תרומה קלו, ב."],["131","23","<b>החכמה מאין תמצא</b>: ראה איוב כח, יב."],["132","24","<b>עוטה אור</b>: תהלים קד, ב."],["133","25","<b>ד' לאה בשכמל\"ו רחל</b>: ראה פרי עץ חיים שער (ז) הק\"ש פי\"ג."],["134","26","<b>אלו ואלו דברי אלקים חיים</b>: עירובין יג, ב."],["135","27","<b>ואהבת. . שם מ\"ב</b>: ואתחנן ו, ה. הנסמן לעיל ע' א בכהאריז\"ל."],["136","28","<b>בשתים יעופף</b>: ראה ישעי' ו, ב."],["137","29","<b>לא לתהו בראה</b>: ראה ישעי' מה, יח."],["138","30","<b>ע\"ב גשרי'</b>: נסמן לעיל ע' יב."],["139","31","<b>יום ראשון חסד</b>: ראה שער היחוד והאמונה פ\"י."],["140","32","<b>יום ראשון. . מים אור</b>: ראה חגיגה יב, א."]]],[2100490078,"ומוריד הגשם אתה גבור שיורדין בגבורה<sup data-n=\"141\">33</sup> טיפין<sup data-n=\"142\">34</sup> טיפין ועכ\"ז הוא מכוין חסד שהרי אם הי' שטף כמו במבול ארובות השמים נפתחו<sup data-n=\"143\">35</sup> לא הי' גם גידול התבואה כו' וזהו שאמר משה בפרשה זו ונתתי<sup data-n=\"144\">36</sup> ולא אמר כן בכל החומש הגם דשכינה מדברת מתוך גרונו<sup data-n=\"145\">37</sup> אך לפי שכבר הי' לו מס\"נ בפרשה שמע ואינו כלום רק הגילוי אלקות שבו לכך אומר ונתתי וכל נפש מישראל שמתפלל אומר ונתתי על עצמו לפי שכבר הי' במס\"נ תחלה כו' ופי' ונתתי מטר ארציכם הוא מ\"ד ומ\"ן כי כל ההתחלקות שיש בג\"ע כמה השגו' וש\"י עולמו'<sup data-n=\"146\">38</sup> לכל צדיק וכן מחנה מיכאל כו' הכל תלוי בערך המ\"ד ומ\"ן כו' וכל הענין הוא בחי' ג' שמו' דויסע ויבא ויט<sup data-n=\"147\">39</sup> ישר הפוך ישר מלמעלה למטה ומלמטה למעלה ומלמעלה למטה כו'.\n&lt;יב&gt;",[["141","33","<b>הגשם. . שיורדין בגבורה</b>: תענית ב, א."],["142","34","<b>הגשם. . טיפין</b>: ראה בבא בתרא טז, א."],["143","35","<b>ארובות השמים נפתחו</b>: ראה נח ז, יא."],["144","36","<b>ונתתי</b>: עקב יא, טו."],["145","37","<b>דשכינה מדברת מתוך גרונו</b>: נסמן לעיל ע' יג."],["146","38","<b>וש\"י עולמו'</b>: ראה עוקצים בסופה."],["147","39","<b>ג' שמו'. . ויט</b>: נסמן לעיל ע' יד."]]],[2100490079,"<h3>נוסח שלישי: שמע ישראל</h3>\n<b></b><b>בעזרה\"י. ליל ש\"ק פ' נח, תקס\"ואו לפ\"ק</b>\nליל ש\"ק פ' נח\n<b>שמע</b><sup data-n=\"148\">*1</sup> ישראל הוי' אלקינו הוי' אחד<sup data-n=\"149\">1</sup>* וגו'. להבין הטיב ענין ק\"ש בכללה דהנה נאמר בזוהר<sup data-n=\"150\">2</sup> ע\"פ ויקח רמ\"ח בידו דא רמ\"ח תבין דק\"ש, עוד מ\"ב תיבין דיחודא בפ' ראשונה דק\"ש מואהבת עד ובשערך הוא כנגד שם מ\"ב, וע\"ב<sup data-n=\"151\">3</sup> תבי\"ן דיחודא שבוהיה אם שמוע כו' פ' שניה דק\"ש הוא כנגד שם ע\"ב. ולכאורה הוא דבר פלאי כי הלא פ' ראשונה דק\"ש היא נגד מדת החסד דאצי' ויהי' נרמז בה מ\"ב תיבי\"ן דש' מ\"ב שהוא ממדת הגבורה כנודע, ופ' שניה דק\"ש שהיא כנגד מדת הגבורה וגם מבואר בה בחי' גבורה וחרה אף ה' בכם וגו' יהי' נרמז בה ש' ע\"ב שהוא מספי' החסד עליון כנודע כלפי לייא. אך התירוץ מבואר בע\"ח, כמ\"ש בזוהר לאכללא שמאלא בימינא<sup data-n=\"152\">4</sup> דאחלופי דוכתי כו', שאור הגבורה נכנס ומתלבש בכלי החסד ואור החסד נכנס ונתלבש בכלי הגבורה שלפעמים מתחלפים האורו' ועי\"ז",[["148","*1","ואתחנן ו, ד."],["149","1","<b>שמע ישראל הוי' אלקינו הוי' אחד</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קמז, א).\nנזכר בדרך מצותיך (קכ, ב) ”כן שמענו מפה ק' כאאזמו\"ר נ\"ע בליל ש\"ק פ' נח שנת תקס\"ה באריכות בעת היות משולחי הרב הק' ר' אהרן מטוטיאב נכד הבעש\"ט ז\"ל אצל כ\"ק ועמהם יחד שמענו מאמר הנ\"ל\".\nהנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נדפס לעיל ע' א בהתחלה: להבין ענין ק\"ש. וראה בהנסמן שם."],["150","2","<b>בזוהר ע\"פ ויקח רמח</b>: בלק כה, ז. ראה פע\"ח שער קשעה\"ט רפי\"א. ובזח\"א (יב, א). ובלקו\"ת תצא לח, א מציין — ”וע' בספר מאורי אור אות ריש סט\"ו\"."],["151","3","<b>מ\"ב. . ע\"ב</b>: נסמן לעיל ע' א הערה 4."],["152","4","<b>בזוהר לאכללא שמאלא בימינא</b>: נסמן לעיל ע' א."]]],[2100490080,"נתכלל שמאלא בימינא כו' שלפי\"ז יתורץ הטיב שפ' ראשונה דק\"ש שהיא כלי החסד נתלבש אור הגבורה שזהו ע' בחי' הכונה דמ\"ב תיב\"ן שהוא כנגד ש' מ\"ב שהוא ממדת הגבורה כנ\"ל, ובפ' שניה דק\"ש שהיא בחי' כלי הגבורה נתלבש אור החסד שזהו הכונה דש' ע\"ב שנרמז בע\"ב תבין שבה עד ושמתם כו'.\n<b>אך</b> לבאר הדבר היטב לקרב אל השכל מצטרך תחלה לבאר ענין יחודא עלאה ויחודא תתאה שב\"ך<sup data-n=\"153\">5</sup> כו'. דהנה הוי'<sup data-n=\"154\">6</sup> אלקינו הוא בחי' יחוד או\"א דאצי' שהם תרין ריעין דלא מתפרשין<sup data-n=\"155\">7</sup> דזיווגייהו תדיר ולא פסיק לעלמין, כי בטובו מחדש בכל יום<sup data-n=\"156\">8</sup> מעשה בראשית מאין ליש ממש וכמו שלמטה בהנפעלי' הגשמיים הנראי' בעיני בשר שמתחדשי' בכל שעה ובכל רגע מאין המוחלט ליש גשמיי הנראה לעין כל, כי אין הדבר עושה א\"ע ואלו הי' נפסק החיות מהם רגע אחת מיד הי' חוזרי' לאין ואפס כקדם כמ\"ש (בלק\"א ח\"ב<sup data-n=\"157\">9</sup>). כך ממש למעלה מעלה בהנפעלי' הרוחניים שמתחדשים בכל יום ובכל רגע מאין ליש ממש והיינו כי החכמה דאצי' מאי\"ן תימצא שנובעת בתמידיות בלי הפסק ממקורה אי\"ן האמיתי וממנה מקבלת כלי הבינה<sup data-n=\"158\">10</sup> דאצי' שנק' רחובת הנה\"ר עליון שהוא בחי' י\"ש כמ\"ש להנחיל אוהבי יש<sup data-n=\"159\">11</sup> וגו' מצד שהיא כלי הבינה והשגה ממש שנתפס אור אין סוף בכלי השגה והבינה ממש משא\"כ סקירת החכמה שמאי\"ן תמצא שלמעלה מגדר השגה שהוא כמשל מעיין הנובע מן הארץ שמאי\"ן תימצא שלא ניכר מאין נובע המעיין כו' וממנו יומשך רחובת הנהר בשטף מים רבים כו' כך למעלה כתיב ונהר יוצא מעדן<sup data-n=\"160\">12</sup> וגו' שזהו בחי' ההתחדשו' מאין ליש בתמידו' שהחכמה שמאין תימצא תחי' את כלי הבינה שנק' בחי' יש ולא פסקא מימו לעלמין מצד שהם מקור כל סדרי ההשתלשלות כולן שקיומם הוא מהיחוד תמידי דאו\"א דאצי' שמתחדש השפע בתמידות מאין ליש כנ\"ל. אך בהיות ידוע שעצמות המאציל ב\"ה מרומם לבדו ומתנשא מימות עולם עד שאין ערוך אליו כלל אף ע\"ס הנאצלי' כמאמר אליהו אנת הוא חד<sup data-n=\"161\">13</sup> ולא בחושבן שאיננו בחשבון ומנין הע\"ס &lt;יג&gt;\nכ\"א מרומם לבדו זולתי הוא משפיל להתלבש בע\"ס הנאצלי' שהוא בחי' שפלות וירידה גדולה לגבי', וזהו אנ\"ת בחי' עצמו' אור אין סוף מתלבש בחכים ולא בחכמה ידיעא<sup data-n=\"162\">14</sup> מבין ולא בבינה ידיעא אבל לאו דאית לך צדק ידיעא כו' ולאו ביה מאינון מדות כלל וכמ\"כ לאו בי' מכל התוארי' הללו דחב\"ד כלל כ\"א פשוט בתכלית הפשיטות מרומם לבדו ומתנשא מימות עולם. ולזאת מצטרך להמשיך באתערותא דלתתא אתערותא דלעילא שיומשך השפע מעצמות אור אין סוף ב\"ה ולהתלבש בכלים דע\"ס הנאצלי' כי מתחלת האצלת הנאצלים הי' חפץ חסד בלתי אתערותא דלתתא כלל כמ\"ש בזוהר בריש הורמנותא דמלכא<sup data-n=\"163\">15</sup> גליף בגליפו כו'",[["153","5","<b>שב\"ך</b>: ש'מע, ב'רוך (שם) כ'בוד."],["154","6","<b>ה' אלקינו הוא יחוד או\"א</b>: נסמן לעיל ע' ד."],["155","7","<b>תרין ריעין דלא מתפרשין</b>: נסמן לעיל ע' ד."],["156","8","<b>מחדש בכל יום</b>: ראה ברכת יוצר אור."],["157","9","<b>(בלק\"א ח\"ב)</b>: שעהיחוה\"א פ\"ב, פ\"ט."],["158","10","<b>הבינה. . רחובת הנהר</b>: נסמן לעיל ע' ד."],["159","11","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["160","12","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["161","13","<b>אנת הוא חד</b>: ראה תקו\"ז בהקדמה (יז, א)."],["162","14","<b>בחכים ולא בחכמה ידיעא</b>: שם (יז, ב)."],["163","15","<b>בריש הורמנותא דמלכא</b>: נסמן לעיל ע' ג."]]],[2100490081,"טהירא עלאה כו' שכך עלה ברצונו הפשוט ית' אבל עתה מצטרך להיות ההתעוררו' מלמטה בהעלא' מ\"ן להמשיך מ\"ד מבחי' אור אין סוף ב\"ה שיתלבש בכלים דנאצלי' שיקרא חכים ולא בחכמה ידיעא מבין ולא בבינה ידיעא כו'.\n<b>וז\"ש</b> שמע ישראל שב' תיבות אלו מורי' על בחי' ההעלאו' מ\"ן שמלמטה למעלה להמשיך התלבשו' אור אין סוף ב\"ה בכלים דאו\"א דאצי' שזהו מ\"ש אח\"כ הוי' אלקינו שהוא יחוד או\"א עלאין כו' כנ\"ל והיינו כי שמ\"ע<sup data-n=\"164\">16</sup> הוא בחי' שם ע' רבתי, שזהו בחי' ההעלא' מ\"ן דב\"ן דתיקון עם המתבררין דרפ\"ח ניצוצין דתה\"ו שנפלו דרך שבירה בו דכאשר הם מתבררי' ונכללי' בש' ב\"ן דתיקון להיותו מעלה מ\"ן בהם אז נק' בחי' שם שרפ\"ח עם ב\"ן גי' ש\"ם שזהו בחי' היחוד דב\"ן עם רפ\"ח ניצוצין המובלעי' בו להיותו מעלה מ\"ן בהם למעלה מעלה כנ\"ל. ועוד שלכך נק' בחי' ש\"ם מצד שרש שרשם של רפ\"ח ניצוצין דתה\"ו ודש' ב\"ן דתיקון הוא הכל מבחי' שמ\"ו ית' בלבד היינו בחי' מלכות דאין סוף ב\"ה שרש כל הנאצלי' דתה\"ו ותיקון שהשבירה והתיקון הי' הכל בבחי' שמו ית' הוא בחי' מל' דא\"ס ראשית הארת הקו כו' משא\"כ מהותו ועצמותו של המאציל מרומם ונשגב לבדו ומתנשא מימות עולם עד שאין בו שום שינוי והתפעלות בין קודם שנאצל כל העולמות דעקודי' נקודי' וברודים ובין אח\"כ ובין קודם השבירה ובין לאחר השבירה ובין בזמן הברו\"ר ובין לאחר גמר הברור שכל השנויים הם רק לגבי הנפעלי', אבל לגבי מהותו ועצמותו ית' אין שינוי והתפעלות כלל מאחר שמרומם לבדו ומתנשא מימות עולם וכ\"ז נעשה בבחי' שמו הגדול ית' בבחי' מלכות דאין סוף שהוא רק בחי' הודו וזיו בעלמא ממנו כנודע וזהו אנ\"י ה' לא שניתי היינו כמ\"ש אנ\"י<sup data-n=\"165\">17</sup> ראשון ואני אחרון ומבלעדי אין אלקי\"ם פי' אנ\"י הוא ראשון קודם השבירה ואני אחרון לאחר גמר הברורין שיחזור להיות כמקדם השבירה שזה יהי' לע\"ל בימות המשיח ומבלעדי אין אלקי' הוא באמציעתא בזמן הגלות שעתה שהוא זמן הברורין שכל העתי\"ם הללו שוי' קמי' בלי שום שינוי והתפעלות כלל זולתי השינוי הוא אל הנפעלי' דוקא, וכמשל אור השמש המאיר על הארץ ולדרים עלי' דכאשר השמש יצא על הארץ להאיר ולהזריח עליהם וטהר יומא מעננים ועבי' שאין מסתירי' אורה שאז נראה ונגלה הארתה וזריחתה על כל הארץ או כאשר יכסה שמים &lt;יד&gt;\nבעבים שנתקשרו בעבים וסכותה בענן את אור השמש שנסתרה מבני האדם שלמטה שיש שינוי והפרש גדול ביניהם, שכ\"ז השינוי הוא אל המקבלים הארתה למטה שיש שינוי גדול בין התגלות האור להעדר הגילוי כו' אבל לגבי עצמות מאור השמש אין שום שינוי והתפעלות כלל שמאירה אורה בשוה זולתי שהעבים מכסים עליה להסתירה מבני האדם שלמטה שלא יגרום בזה בה שום שינוי והתפעלות או מיעוט וחסרון כלל כנ\"ל.\n<b>כך</b> עד\"מ למעלה דכתיב אני<sup data-n=\"166\">18</sup> הוי\"ה הוא שמ\"י כו' שכל סדרי ההשתלשלות כולן מריש כל דרגין עד סוף כל דרגין נמשכו הכל מבחי' שמו ית' בלבד ששרש",[["164","16","<b>שמע. . ע' רבתי</b>: נסמן לעיל ע' ה."],["165","17","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["166","18","<b>אני הוי' הוא שמי</b>: ראה ישעי' מב, ח."]]],[2100490082,"הכל הוא בחי' מל' דא\"ס ב\"ה ראשי' הארת הק\"ו כו' שהוא רק הארה בעלמא מעצמות ית' כמשל שם האדם כו' כנודע ולזאת אין בו ית' שום שינוי והתפעלות ח\"ו, והשינויים שנפעלו בסדר ההשתלשלות בין קודם השבירה ובין לאח\"כ כו' ובין לאחר גמר הברורין ושלימות התיקון שכ\"ז הוא השינוי אצל המקבלים האור ממנו ית' שיש שינוי בין קודם השבירה ובין אח\"כ ובין זמן הברורין לגמר ותכלית הברורין שיתגלה הארתו בגילוי יותר אשר<sup data-n=\"167\">19</sup> עין בעין יראו כו' אבל לגבי' ית' אין שינוי כלל מאחר שסבת מקור כל ההשתלשלות הוא בחי' מלכות דא\"ס שהוא בחי' שמו ית' בלבד בחי' הודו על הארץ ושמים וכביטול זיו השמש במאור השמש כנ\"ל. ולכך כולם בשם יקרא אף בחי' העולמו' דעקודים נקודי' שלפני האצי' שמקור שרשם הוא בחי' שמו הגדול ית' בחי' מלכו' דאין סוף ב\"ה כנ\"ל. וזהו שמ\"ע ש\"ם ע' רבתי שזהו בחי' רפ\"ח ניצוצין דתה\"ו עם שם ב\"ן דתיקון שנתחברו יחד בבחי' העלא' מ\"ן מלמטה למעלה שהם גי' ש\"ם ועוד מצד שרשן מבחי' שמו מל' דא\"ס ית' והיינו שההעלא' מ\"ן דב\"ן עם המתבררין דרפ\"ח ניצוצין מתעלה לשרש שרשם אל בחי' ע' רבתי שהם ז\"ת דאימא ששרשן מז' נקודות דתהו, ולכך נק' בשם ע' רבתי בהיות ידוע שיש בחי' אתווין<sup data-n=\"168\">20</sup> רברבין ואתווין זעירין שהאותיו' הם הכלים של המדות עליונו' שאם המדות עליונות הם בבחי' הגדלה והרחבה בהתפשטות מאד אזי האותיו' הם הכלים שלהם ג\"כ רחבים והם אתווין רברבין משא\"כ כשהמדות הם בבחי' צמצום וקטנות אזי האותיו' הם הכלים קטנים והם אתווין זעירין, והיינו שבחי' ז\"ת דאימא הם המדו' עליונו' שהם בהגדלה והרחבה מאד בבחי' התפשטות מאחר שעדיין הם נכללין באימא דאצי' שלא נתפשטו בהכלי' דז\"א להתצמצם בהכלי' דז\"א שמתפשטים שם בהרחבה מאד להיות כאו\"א מז' מדות כלולה מעשר הרי עולה ע', וזהו בחי' ע' רבתי ששם שרש אתוון רברבין מאחר שהמדות שם בהגדלה והרחבה מאד משא\"כ כשמתלבשי' בהכלי' דז\"א דאצי' שמתצמצם בהן בבחי' צמצום וקטנות אזי שם שרש בחי' אתוו\"ן זעירי\"ן שהם הכלים קטנים שלהם, ומטעם זה נק' בשם<sup data-n=\"169\">21</sup> זעיר אנפין שאנפין של המדות המלובשי' בכלים קטנים דז\"א הם בבחי' קטנות כנ\"ל ששם שרש אתווין זעירין, ומבשרי אחזה עד\"מ בנפש המשכלת בגדולת ה' ב\"ה ותתפעל מזה במדות אהוי\"ר כו' שכאשר המדות נכללים ונעלמי' עדיין בעמקות ההשכלה ההיא אזי הם &lt;טו&gt;\nבהרחבה והתפשטות מאד משא\"כ כשמתפשט בכלי הלב להתלבש בה עד שנרגשים בבחי' הרגשה ממש בכלי הלב אזי נתמעט אורם בצמצום וקטנות יותר מכמקדם בעודן נעלמים בעמקות ההשכלה מצד שכלי הלב אינו מספקת להכיל המדות ההם שבשכל פי' שכפי חיוב השכלי שמחויב בההשכלה ההיא איך יאתה<sup data-n=\"170\">22</sup> לאהבה וליראה כו' שזהו בחי' המדות שבשכל בחי' התפעלות השכל כו' לעולם לא יהי' באפשרי להמצא בכלי הלב כ\"כ להיותה יוצאי' ידי חובתו של השכל מצד שהיא קטון מהכיל המדות הגדולי' ההם של השכל מפני שכלי הלב היא",[["167","19","<b>אשר עיין בעין יראו</b>: ראה לשון הכתוב — שלח יד, יד."],["168","20","<b>אתווין רברבין</b>: ראה זהר ר\"פ ויקרא. וראה בהנסמן במאמרי אדה\"א ויקרא ע' יד."],["169","21","<b>בשם זעיר אנפין</b>: ראה ג\"כ לקו\"ת עקב יד, ב."],["170","22","<b>איך יאתה</b>: ראה ג\"כ תו\"א פרשת זכור פה, ג."]]],[2100490083,"מוגבלת בצמצום וגבול משא\"כ המדו' שבשכל שהם מופשטי' מגדר כלי המגביל שמתפשטי' מאד בהרחבה והתפשטות משא\"כ כשמתלבשי' בכלי הלב אזי מתמעט אורם להיות כלי הלב מגביל אותם ומצמצם אותם כו' כך ממש עד\"מ למעלה בהמדות עליונות כשגנוזות עדיין בבחי' אימא דאצי' אזי הם בבחי' הגדלה והרחבה מאד שאז הם אתווין רברבין משא\"כ כשמתצמצם בכלי' דז\"א דאצי' שאז הם אתווין זעירין כו'.\n<b>וזהו</b> שמ\"ע שבחי' ש\"ם שהוא ההעלאו' מ\"ן דב\"ן עם הברורין דרפ\"ח ניצוצין מתעלה אל מקור שרשו בחי' ע' רבתי שהם ז\"ת דאימא ששרשם מבחי' ז' נקודות דתהו כנודע. וכמ\"כ ממש למטה בעבודת האדם בל\"ט מלאכות דחו\"ל שהמה הכל בחי' ברורין שמברר האדם שלמטה ע\"י המאכלים ומלבושי' שמעלה אותן אח\"כ לקדושה ע\"י העבודה שבלב זו תפלה<sup data-n=\"171\">23</sup> וזהו בחי' שמע ש\"ם ע' רבתי כנ\"ל וד\"ל.\n<b>ישראל</b> פי' זהו עלי' השניה שיתעלה ונכלל בחי' שמ\"ע בכללו בחי' השם עם הע' רבתי בבחי' ישראל סבא<sup data-n=\"172\">24</sup> שהוא למעלה אפי' מבחי' ע' רבתי כי ישראל עלה במחשבה<sup data-n=\"173\">25</sup> כו' והוא בחי' חכמה עליונה הקדומה כמ\"ש בזוהר שא\"ל הוא נהירו דחכמתא<sup data-n=\"174\">26</sup> כו' וזהו יש\"ר אל<sup data-n=\"175\">27</sup> שבו מתעלה בחי' שמ\"ע בכללו כנ\"ל וד\"ל (וכן למטה בעבודת האדם כשאומר שמ\"ע ישראל ומבין בכל זה ומאמין באמונה שלימה שכן הוא עי\"ז מתעלה נשמתו עם הברורי' שבירר בל\"ט מלאכות בישראל דלעילא).\n<b>הוי\"ה</b> אלקי\"נו פי' דכאשר נתעלה ההעלא' מ\"ן דרפ\"ח ניצוצין שבשם ב\"ן למעלה הגבה מאד נעלה עד בחי' ישראל סבא שהוא עלה במחשבה קדומה אזי נמשך המ\"ד משם להיות היחוד דאו\"א עלאין דאצי' ע\"י התלבשו' אור אין סוף בכלי החכמה דוקא והבינה מקבלת השפע דאור א\"ס כמו שהוא מלובש בכלי החכמה מפני שאין אור אין סוף יוכל לשרות זולתי בכלי הביטול שהיא כלי החכמה<sup data-n=\"176\">28</sup> כ\"ח מ\"ה דוקא משא\"כ הבינה היא בחי' י\"ש כמ\"ש להנחיל<sup data-n=\"177\">29</sup> אוהבי י\"ש לכך מקבלת ע\"י אמצעות החכמה המתמצע ביניהם ולא ממנו בעצמו כנ\"ל, וכן מעולם ועד עולם בכל סדרי ההשתלשלות דאבי\"ע עיקר השראת אור אין סוף ב\"ה הוא בכלי החכמה כ\"ח מ\"ה שהיא כלי &lt;טז&gt;\nהביטול מכון לשבתו וע\"י החכמה דווקא יתחבר אור אין סוף ב\"ה עם כל הנפעלים כו' כמשנת\"ל ע\"פ עוטה אור כשלמה<sup data-n=\"178\">30</sup> שהוא לבוש המחבר אור אין סוף עם כל הנפעלים כנ\"ל. וזהו הוי\"ה אלקי\"נו בחי' היחוד דאו\"א דאצי' תרין רעין דלא מתפרשין דזיווגייהו תדיר ולא פסיק לעלמין כי בטובו מחדש בכל יום ובכל",[["171","23","<b>העבודה שבלב זו תפלה</b>: ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א."],["172","24","<b>ישראל סבא</b>: ראה תו\"א ד, ד. נ, ד. לקו\"ת מצורע כה, ב. במדבר ט, ד. ועוד."],["173","25","<b>ישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד."],["174","26","<b>שא\"ל הוא נהירו דחכמתא</b>: זהר לך צד, א. צו ל, ב. לא, א. אחרי סה, א."],["175","27","<b>יש\"ר אל</b>: נסמן לעיל ע' ז."],["176","28","<b>החכמה כח מה</b>: זח\"ג לד, א."],["177","29","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["178","30","<b>כמשנת\"ל ע\"פ עוטה אור כשלמה</b>: תהלים קד, ב. וראה סה\"מ תקס\"ה ע' תתקפ ואילך."]]],[2100490084,"שעה מע\"ב מאי\"ן ליש דהיינו החכמה<sup data-n=\"179\">31</sup> מאין תימצא ומתלבש' בכלי הבינה שנק' יש כמ\"ש להנחיל אוהבי יש וד\"ל.\n<b>הוי\"ה</b> אח\"ד הנה ידוע מארז\"ל שאחד הוא כולל ד' רוחות וז' רקיעים והארץ<sup data-n=\"180\">32</sup> ועל כולם הוא אלופו של עולם שע\"ז מורה הא' דאחד וכמ\"כ למעלה מעלה בהמדות דז\"א דאצי' דכתיב לך הוי' הגדולה<sup data-n=\"181\">33</sup> והגבורה והת\"ת כו' שכולל ט\"ס שזהו א\"ח דאחד והד' רבתי הוא בחי' פרצוף לאה שמאחוריו כו' והיינו כי אחד לא יתכן לקרות זולתי על שני בחי' ומדרגו' המתחברים יחד דוקא דה\"א שהם שנים לזאת אומר שהם אחד ומיוחד בתכלית היחוד בלי פירוד כלל, משא\"כ על דבר אחד המיוחד ואין שני לו להחבירה לא יתכן לכנותו בשם אח\"ד כ\"א בשם יחיד<sup data-n=\"182\">34</sup> כנודע. והיינו בהיות המדות דז\"א דאצי' יש בהם בחי' התחלקות המדריגו' שונות עד שהם הפכיי' ומנגדים זל\"ז שהחסד הוא המנגד אל הגבורה כו' וה\"א שיש ח\"ו בחי' פירוד ממש ולזאת קמל\"ן קרא דמלת אח\"ד דאיהו וגרמוהי<sup data-n=\"183\">9</sup> וחיוהי כולי חד בהון ממש, הגם שהכלי' דז\"א הם הפכיים ומנגדים זל\"ז אך כאשר יתלבש בהן בחי' אור אין סוף ב\"ה המרומם לבדו אזי יתבטלו במציאות הכלי' דז\"ת ולהתיחד כולם כאחד בתכלית היחוד (כמ\"ש במ\"א ע\"פ עושה שלום במרומיו<sup data-n=\"184\">35</sup> כו' ע\"ש). וזהו הוי\"ה שהוא בחי' ז\"א דאצי' שהם המדו' עליונות דאצי' אח\"ד ומיוחד בתכלית היחוד מצד התלבשות אור אין סוף ב\"ה בהן שהוא מיחד לון כחדא ומקשר לון כחדא מצד הביטול וההתכללות שלהן בו ית' וכדכתיב לך הוי\"ה הגדולה והגבורה והתפארת וגו' לך דוקא בטלי' במציאות כנודע.\n<b>בשכמ\"ל</b> הוא בחי' יחודא תתאה<sup data-n=\"185\">36</sup> להמשיך בחי' הארת מלכות דאצי' בתוך כל העולמות בי\"ע כמ\"ש לכבוד\"י<sup data-n=\"186\">37</sup> בראתי\"ו יצרתי\"ו אף עשיתי\"ו. וזהו ברוך הוא המשכה<sup data-n=\"187\">38</sup> שיומשך ש\"ם כבו\"ד מלכות\"ו הם ג' בחי' ומדרגו' שבמל' דאצי' בתוך ג' עולמות בי\"ע וזהו לעול\"ם וע\"ד כנ\"ל וד\"ל.\n<b>ואהבת</b> את הוי' אלקיך<sup data-n=\"188\">39</sup> בכל לבב\"ך ובכל נפש\"ך ובכל מאדך וגו' שמואהבת עד ובשעריך יש מ\"ב תבות<sup data-n=\"189\">40</sup> כנגד שם מ\"ב שהוא ממדת הגבורה שלמעלה כנודע שש' מ\"ב נרמז באנא בכח וגו' שהוא שית שית תבין כו' נגד שית",[["179","31","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["180","32","<b>שאחד. . והארץ</b>: בסידור שער הק\"ש פו, סע\"ד: כמ\"ש בטור [הל' ק\"ש סס\"א. וראה שו\"ע אדה\"ז שם]."],["181","33","<b>לך הוי' הגדולה</b>: דברי הימים-א כט, יא."],["182","34","<b>בשם יחיד</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קלה (ומקבילו בתו\"א וארא נה, ב) וע' רמט. פרשיות התורה ח\"ב ע' תשיד. לקו\"ת בלק ע, א. ואתחנן יא, ג. דרך מצותיך קכד, א. אמרי בינה שער הק\"ש פ\"ח."],["183","9","<b>דאיהו וגרמוהי</b>: הקדמת ת\"ז (ג, ב)."],["184","35","<b>במ\"א ע\"פ עושה שלום במרומיו</b>: תו\"א מקץ מג, ב. בשלח סו, א. סז, ב. לקו\"ת נשא כז, א. ובכ\"מ."],["185","36","<b>בשכמ\"ל. . יחודא תתאה</b>: זהר בראשית יח, ב. וראה בארוכה תו\"א קטו, א ואילך."],["186","37","<b>לכבודי בראתיו</b>: ישעי' מג, ז."],["187","38","<b>ברוך הוא המשכה</b>: ראה כלאים רפ\"ז. וראה תו\"א בשלח רכ, ב."],["188","39","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["189","40","<b>שמואהבת. . מ\"ב תבות</b>: נסמן לעיל ע' א."]]],[2100490085,"גדפין עלאין בשתים יכסה פני\"ו ובשתים יכסה רגליו ובשתים יעופף בבחי' רצוא והעלא' מ\"ן מלמטה למעלה, ולכך צ\"ל בק\"ש שעל המטה<sup data-n=\"190\">41</sup> בכדי שתתעלה נשמתו למעלה כו' וכנודע שש' מ\"ב הוא מצד הגבורה שכל העליות עולמות ממדרגה למדרגה הוא הכל ע\"י ש' מ\"ב (כמשנ\"ת במ\"א בענין מ\"ב מסעות ע\"ש), אך הפרשה ראשונה דק\"ש<sup data-n=\"191\">42</sup> בעצמה היא כלי החסד רק הכונה שלה שהוא פנימיו' האור שלה הוא שם מ\"ב אור הגבורה המתלבש &lt;יז&gt;\nבכלי החסד, והיינו כי אהבת מאוד\"ך היא בחי' מדת האהבה שא\"א ליתפס בגדר כלי הלב שהיא קטן מהכיל אותה להיותה מלובשת בתוכה ממש כ\"א היא בבחי' רצוא והסתלקות מכלי הלב לגמרי שזהו בחי' כלות הנפש ממש (כענין תשובת ר\"א בן דורדי'<sup data-n=\"192\">43</sup> שיצאת נשמתו ממש כו') וזהו בכל מאוד\"ך שמא\"ד הוא בלי גבול שלמעלה מגדר הכלי הלב המגביל האהבה להיותה בגדר גבוליי כ\"א היא מסתלקת מן הכלי ברצוא והסתלקות ממש מצד שא\"א לה לשרות בכלי הלב כנ\"ל. הנה זהו בחי' התלבשות אור הגבורה בכלי החסד שנק' בחי' גבורה שבחסד פי' האו\"ר הוא גבורה והכלי הוא חסד שאור הגבורה מתלבש בכלי החסד, והיינו כי חצוניות אהבת מאדך דהיינו מה שנתפס ומתלבש בכלי הלב שניכר ונרגש בכלי הלב בבחי' הרגשה ממש הוא בחי' חסד דהיינו שמדת האהבה היא מדת החסד שנמשך אליו באהבה וחסד שבלבו, אך זהו בחי' כלי החסד דהיינו במה שנתפס בכלי הלב ונרגש באהבה בהרגשה שנמשך אליו באהבה וחסד כנ\"ל וד\"ל.\n<b>אך</b> בתוך זה מלובש האור הפנימי של הגבורה דהיינו האור הפשוט של אהבת מאד\"ך מה שאינו יכול ליתפס בכלי הלב שהוא הכונה הפנימיות שלהם שהוא בחי' רצוא והסתלקות בגבורו' רשפי אש לצאת מנרתק הגוף בכלות הנפש ממש שזהו פנימית אור האהבה של מאד\"ך שהוא אור הגבורה רק שמלובש בכלי החסד הוא חיצוניות האהבה המלובש בכלי הלב ונרגש בה בבחי' הרגשה שהוא בחי' כלי החסד לימשך אחרי' כמים כו' נמצא עצמות אור הפשוט של האהבה מה שמופשט מגדר כלי הלב שא\"א לו להתלבש בה הוא בחי' גבורה והכלי דהיינו חצוניותה מה שמלובש בכלי הלב הוא בחי' חסד כנ\"ל. וזהו בחי' הכונה שפ' ראשונה דק\"ש מה שאין נראה בה בבחי' גילוי זולתי דרך העלם והתלבשות שהוא הכונה שינה האור הפנימי שלה הוא ש' מ\"ב שהוא אור הגבורה שנרמז במנין מ\"ב תיבות שבה אבל אין מבואר בה להדיא בהמשך פשט הפרשה כו' והכלי שהוא המשך פשט הפרשה שניכר בבחי' גילוי הוא בחי' חסד שנאמר ואהבת את ה' אלקיך וגו' והיו הדברים האלה כו' ודברת בם כו' שזהו בחי' גבורה שבחסד פי' אור הגבורה מלובש בכלי החסד שהעיקר הוא בחי' גבורה רק התלבשותו בכלי החסד שזהו ענין כונת ש' מ\"ב שבפרשה ראשונה דק\"ש שעיקר המכוון הפנימי שבה הוא ש' מ\"ב רק הכלי הוא המשך הפרשה שנראה בגילוי הוא חסד וכ\"ז נכלל באהבת מאד\"ך שהוא התלבשו' אור הגבורה בחי' הרצוא וההסתלקות בכלי החסד כנ\"ל (ולקרב אל השכל יותר בחי'",[["190","41","<b>בק\"ש שעל המטה</b>: נסמן לעיל ע' י הערה 74."],["191","42","<b>הפרשה ראשונה דק\"ש</b>: נסמן לעיל ע' ב."],["192","43","<b>תשובת ר\"א בן דורדי'</b>: ע\"ז יז, א."]]],[2100490086,"גבורה שבחסד שעיקר המכוון האור הפנימי הוא הגבורה רק התלבשותו בכלי החסד שאז יוכל להתקיים עיקר המכוון של הגבורה כמו באדם שמאכיל ומשקה לשונאו בכדי לקיים מ\"ש אם<sup data-n=\"193\">44</sup> רעב שונאך וגו' כי גחלים אתה חותה על ראשו שהגילוי הוא כלי החסד שמטיב עמו שמאכיל אותו לחם כו' והכונה לרעתו כו' להיותו גחלי' חותה על ראשו כו' ולהפך בחי' חסד שבגבורה הוא שעיקר המכוון הוא בחי' חסד רק מלובש בכלי הגבורה בכדי שיתקיים עיקר החסד<sup data-n=\"194\">45</sup> כמו האב המיסר את בנו מצד האהבה להדריכו בדרך הישר כו' וכמש\"ת לקמן).\n&lt;יח&gt;\n<b>והיה</b> אם שמוע<sup data-n=\"195\">46</sup> תשמעו אל מצותי כו' ולעבדו בכל לבבכם ובכל נפשכם וגו' ונתתי מטר ארציכם וגו' ונתת\"י עשב בשדך וגו' השמרו לכם פן יפתה לבבכם וגו' וחרה אף ה' בכם וגו' עד ושמתם יש ע\"ב תיבות נגד ש' ע\"ב, שהוא אור החסד שלמעלה שמקו ימין חח\"ן שנמשך מחכמה עלאה שמתלבש בכלי הגבורה הוא המשך הפרשה דוהיה אם שמוע כו' וחרה אף ה' כו' שזהו בחי' חסד שבגבורה אור החסד שמתלבש בכלי הגבורה כו'. והענין דהנה ידוע שמדת החסד דאצי' מתחלק באצי' לע\"ב מיני התחלקות שונות שהמה ע\"ב גשרים שלמעלה<sup data-n=\"196\">47</sup> דבויס\"ע<sup data-n=\"197\">48</sup> ויב\"א וי\"ט כו' שזהו בחי' ש' ע\"ב דאצי', וצריך להבין היטב ענין המשל דגשרים כו', והיינו כמו עד\"מ למטה הגשר עשוי על נהר גדול משפתו אל שפתו ובתוך הגשר חדרים ימלאו שמחולקים זמ\"ז כמה וכמה בתים מיוחדים וחדרים קטנים עד שהמים יורדים תחת הגשר עוברת דרך התחלקות הבתים מיוחדים שבגשר להיות נתמלא כל חדר מיוחד במים המגיע בחלקו כו', כך ממש עד\"מ למעלה שבחי' אור מדת החסד עליון הכולל דאצי' נמשל למים נדמה כטבע המים שיורדים ממקום גבוה<sup data-n=\"198\">49</sup> למקום נמוך כך בחי' החסד נמשך ממקום גבוה הגבה למעלה למטה במורד לעולמו' בי\"ע הנפרדי' ממש ולזאת מוכרח להיות אור החסד כוללי דאצי' להתחלק לחלקי' רבים פרטיים שונים בכלים מכלי' פרטי' שונים בכדי שיוכל להיות נמשך לבי\"ע להנבראי' פרטיים להיות מתלבש כל חלק פרטיי בנברא פרטיי ההוא המלאך או הנשמה להחיותו ולקיימו תמיד מאין ליש כנודע שכל הנבראי' פרטיי הם משוני' זמ\"ז בשכלי' הנבדלי' שלהן עד שאין האחד דומה לחבירו באופן ההשגה ובאופן הביטול שלו המסתעף מההשגה עד שאין השירה של מלאך פרטי' זו דומה לחבירו<sup data-n=\"199\">50</sup> כמשי\"ת במ\"א, שכ\"ז נסתעף מרבוי ההתחלקות פרטיי' של אור החסד כוללי דאצי' בכלי' מכלי' שונים פרטי' מה דלא סגי בלא\"ה שלא הי' אפשר להתמשך מהחסד הכוללי דאצי' בחי' התחלקות הנבראי' פרטי' מינים ממיני' שונים שנמשכים ממהו' מדת החסד עצמו דאצי' זולתי ע\"י התחלקותו בכלים מכלי' שונים, והמה ע\"ב גשרים שלו שבאצי'",[["193","44","<b>אם רעב שונאך</b>: משלי כה, כא."],["194","45","<b>ולהפך. . עיקר החסד</b>: ראה ג\"כ תו\"ח בראשית מ, ב."],["195","46","<b>והיה אם שמוע</b>: עקב יא, יג."],["196","47","<b>ע\"ב גשרים שלמעלה</b>: נסמן לעיל ע' יב."],["197","48","<b>דבויסע ויבא ויט</b>: נסמן לעיל ע' יד."],["198","49","<b>המים שיורדים ממקום גבוה</b>: ראה תענית ז, א."],["199","50","<b>השירה של מלאך. . לחבירו</b>: ראה סידור שער המילה קמב, ג. סה\"מ תקס\"ה ע' רל. וראה טעמי המצות להרח\"ו פ' ואתחנן שער האמונה לאדה\"א ע' סא, ב."]]],[2100490087,"מתחלק לע\"ב חלקים שונים בע\"ב מיני כלים שונים שהמה ע\"ב גשרים דכמו עד\"מ המים העוברין תחת הגשר מתחלקים בע\"ב בתים מיוחדים שיש בו שכל חדר מיוחד נתמלא ממים המגיע בחלקו כנ\"ל כך עד\"מ למעלה ימצא ע\"ב מיני כלים שונים שמכונים בשם גשרי\"ם שבכל כלי מיוחדת תתלבש אור החסד פרטיי שנבדל מהכלל המגיע בחלקה כפי אופן מזג הכלי ההיא דכמו שהכלי' הם שונים זמ\"ז במהותן ואיכותן, כך השינוי בהאורו' המחולקי' של החסד שמתלבש בהם שכל אור מיוחד פרטיי מתלבש בכלי פרטי הראוי לו שמשונה מחברתו כנ\"ל עד שמבחי' התחלקות פרטי' של אור החסד כללי דאצי' בע\"ב גשרים שהם ע\"ב כלי\"ם שונים יסתעף מזה בבי\"ע בחי' התחלקות הנבראים פרטי' שנתהוו ממהו' מדה אחת של החסד דאצי' רק השנוי הוא מצד שינוי מקורם בבחי' התחלקותו של החסד דאצי' בע\"ב גשרים מאיזה גשר פרטי נמשך הנברא פרטי ההוא שנבדל ומשונה מנברא חבירו שנמשך מגשר השני כו' וכנראה בעליל שיש כמה &lt;יט&gt;\nוכמה מדרגו' חלוקות במהות הנבראים שנמשכו ממדה אחת של החסד דאצי' דכמו בחי' אור שלמטה נמשך ממדת החסד דאצי' כמ\"ש<sup data-n=\"200\">51</sup> ויאמר אלקים יהי או\"ר כו' ויום ראשון מימי השבוע הוא נמשך ג\"כ ממדת החסד<sup data-n=\"201\">52</sup> כו' ומים נמשך ג\"כ ממדת החסד ובגוונין גוון לבן נמשך ג\"כ ממדת החסד<sup data-n=\"202\">53</sup> כו' שלא ידמה וישתווה בחי' אור למים וגוון לבן כו' וכולם אל בחי' יום ראשון שהוא ג\"כ נמשך ממהו' החסד דאצי' שכ\"ז בלתי אפשרי הי' להתמשך רבוי ההתחלקות פרטי' שונים ההם ממהו' אחד של החסד זולתי ע\"י התחלקותו בע\"ב מיני כלים שונים שהם ע\"ב גשרים שעצמו' אור החסד כולו נק' בשם מים שמשתנה לפי אופן שינוי הכלים המה ע\"ב מיני חדרים של הגשרים שהמים שנמשכו בחדר השני יסתעף מהם בחי' מים ובהשלישי יסתעף גוון לבן כו' ועד\"ז יש ע\"ב מיני התחלקות כוללים באצי' שמהם יסתעף רבוי התחלקות פרטיים אין קץ בבי\"ע כי אין חקר לרבוי ופרודי התחלקות הנבראים שונים ומשונים בבחי' העבודה והביטול שלהן השיר של המלאכים שיוצאין בשיר שאין הא' דומה לחבירו מצד רבוי התחלקות של החסד בבי\"ע כנודע שנסתעפו ממהות א' של מדת החסד דאצי' כנ\"ל וד\"ל.\n<b>והנה</b> עיקר סבת ההתחלקות האורות של החסד כוללי דאצי' בכלי' מכלי' שונים דע\"ב גשרים הוא ע\"י כלי הגבורה דוקא מפני שטבע הגבורה לפרר השפע עליונה ומחלקה לחלקי' רבים וכמ\"ש אתה<sup data-n=\"203\">54</sup> פוררת בעז\"ך י\"ם כמשנ\"ת במ\"א, והיינו שהכלי' דע\"ב גשרים הנ\"ל שבהם מתלבש מדת החסד עליון בבחי' התחלקות פרטי' הם בעצמן שרשן מבחי' הגבורו' עליונו' דטבען לפרר השפע של החסד כוללי לפרורים וחלקים רבים שונים כאופן שינוי הכלי מכלים שונים דע\"ב גשרים ולכך יש בהם הכח הגדול הזה לחלקו בהתחלקו' פרטי' מצד שהם כלי הגבורו' פי' ששרשן מבחי' הגבורות עליונות כנ\"ל, אך באמת זהו עיקר הקיום של אור החסד שמתלבש",[["200","51","<b>ויאמר אלקים יהי אור</b>: בראשית א, ג."],["201","52","<b>ויום ראשון. . ממדת החסד</b>: ראה ג\"כ תו\"א מגלת אסתר צב, ב. דרך מצותיך יז, ב. קנא, א."],["202","53","<b>גוון לבן. . ממדת החסד</b>: ראה ג\"כ לקו\"ת ואתחנן יג, ב. שה\"ש יד, א. נ, ד. ובכ\"מ."],["203","54","<b>אתה פוררת בעזך ים כמשנ\"ת במ\"א</b>: תהלים עד, יג. וראה תו\"א הוספות מגלת אסתר קכג, א. לקו\"ת בלק עב, ב."]]],[2100490088,"בכלי' הגבורות בבחי' התחלקות פרטים בכדי שיוכל להתלבש בבי\"ע להתהוות נבראי' פרטיים שונים משא\"כ אם הי' נמשך כמו שהוא אור פשוט כוללי לא הי' אפשר להתהוות ממנו שום נברא כלל וגם בלתי אפשרי הי' לו לירד למטה כלל כנ\"ל לזאת עיקר קיומו הוא ע\"י הגבורו' דכלי' דע\"ב גשרים שמתלבש בהן בבחי' התחלקות פרטי' שעי\"ז יפעול פעולתו בשלימו' בבי\"ע כנ\"ל. וזהו בחי' חסד שבגבורה שהעיקר האור הוא החסד רק שמתלבש בכלי הגבורה שעי\"ז דוקא יתקיים עיקר פעולתו של החסד כנ\"ל.\n<b>וכענין</b> שארז\"ל מזכירין<sup data-n=\"204\">55</sup> גבורו' גשמים בתחי' המתים כו' שלכך נק' גבורות גשמים מפני שיורדין בגבורה כו' והיינו הגם שבאמת ירידת המטר על הארץ הוא מעיקר אור החסד עליון להשפיע למטה לרוות הארץ ולהשקותה בכדי להצמיח כל טוב הארץ תבואות השדה ופירות האילן ותדשא הארץ דשא כו' שיתברכו כל יושבי הארץ בשובע. אך ירידתו למטה הוא ע\"י כלי הגבורה שאז דוקא יתקיים עיקר פעולתו החסד והיינו שכלי הגבור\"ה במה שמתלבש בה הח\"ע מפרדת השפע של &lt;כ&gt;\nהחסד לטפין דקין בהתחלקות פרטי' שאז דוקא יתקיים עיקר החסד לרוות הארץ ולהצמיח כל טוב הארץ כנ\"ל. אבל אם לא הי' מתלבש אור החסד בכלי הגבורה כ\"א היו יורדים המים בשפע שיפתחו ארובות השמים אז יסתעף מזה עיקר הגבורה להיות מבול על הארץ לשחתה נמצא שמה שיורדים בגבורה דהיינו שמתלבש החסד בכלי הגבורו' זהו עיקר קיומו של החסד כנ\"ל ולכך תיקנו הזכרת גשמים בברכה שניה דאתה גבור כו' שבתפלה וכמ\"כ בפ' שניה דק\"ש שהיא כלי הגבורה שנאמר וחרה אף ה' וכו' נרמז בה ש' ע\"ב שבה מלובש עיקר אור החסד עליון שמתלבש בכלי הגבורה הם הע\"ב תיבו' שבה שכנגד ע\"ב גשרים שהם הכלי' שנמשכו מצד הגבורה שבהם דוקא תתפרר השפע של אור החסד עליון ואז יהי' עיקר קיומו שזהו בחי' חסד שבגבורה שהעיקר האור הפנימי הוא החסד רק שמתלבש בכלי הגבורה הם ע\"ב גשרים שלו וכן המשך הפרשה הוא כלי הגבורה, רק עיקר המכוון הפנימי שבה הוא אור החסד שמלובש בע\"ב תיבות שבה שכנגד ע\"ב גשרים דש' ע\"ב (ששם ע\"ב עצמו הוא הכלי לאור החסד כנ\"ל), וזהו מ\"ש בזוהר אחליפו<sup data-n=\"205\">56</sup> דוכתי' כמבואר בע\"ח שאור החסד נכנס בכלי הגבורה וזהו פ' שניה דק\"ש ואור הגבורה נכנס בכלי החסד שזהו פ' ראשונה דק\"ש כנ\"ל וד\"ל (וזהו ג\"כ ג' פ' דויסע ויבא וי\"ט שהיא בחי' אור החסד שמלובש בכלי הגבורה כנ\"ל ולכך הוא ישר והפוך וישר שהוא נגד ג' קוין שלמעלה שתחלה הוא ההמשכה ביושר מלמעלה למטה ואח\"כ הפוך בא\"ח מלמטה למעלה ואח\"כ ישר כו').\n<b>וז\"ש</b> בפ' שני' דק\"ש, ולעבדו בכל לבבכם<sup data-n=\"206\">57</sup> ובכל נפשכ\"ם וגו' ולא נאמר בכל מאדכ\"ם כמ\"ש בפ' ראשונה בכל מאדך, מפני שבפ'<sup data-n=\"207\">58</sup> ראשונה הוא בחי' התלבשות אור הגבורה בכלי החסד שזהו אהבת מאדך שהוא בחי' הרצוא",[["204","55","<b>מזכירין גבורו' גשמים</b>: ברכות לג, א."],["205","56","<b>אחליפו דוכתי'</b>: נסמן לעיל ע' א."],["206","57","<b>ולעבדו בכל לבבכם</b>: ואתחנן יא, יג."],["207","58","<b>שבפ' ראשונה — אור הגבורה בכלי החסד</b>: ראה ג\"כ לקו\"ת ואתחנן יב, ד."]]],[2100490089,"וההסתלקות חוץ לגדר כלי הלב שקטן מהכיל אותה שזהו בחי' אור הגבורה שבכלי החסד כנ\"ל משא\"כ פ' שניה דק\"ש שהוא בחי' התלבשות אור החסד בכלי הגבורה כו' שטבע אור מדת החסד להתמשך ולהתפשט בהכלי דוקא מלמעלה למטה היפך הגבורה שהוא ההסתלקו' מן הכלי' כו' לכך נאמר בה בכל נפשכם ולא נז' בכל מאדכם שהכונה להמשיך האורו' עליוני' של החסד בתוך הכלים דוקא וכנ\"ל, וזהו ונתתי עשב בשדך<sup data-n=\"208\">59</sup> וגו', ונתת\"י מטר ארצכם וגו' וכמארז\"ל שכינה מדברת מתוך גרונו של משה<sup data-n=\"209\">60</sup> כו' דלכאורה הוא פלא מפני מה במקום הזה דוקא נאמר ונתתי שזה משה אמרן מפי הגבורה ששכינה מדברת מתוך גרונו הלא הכל משה מפי הגבורה אמרן<sup data-n=\"210\">61</sup> כו'. אך הענין כנ\"ל שבפ' שני' דק\"ש נרמז ש' ע\"ב שהוא התלבשו' אור החסד בהתחלקו' ע\"ב גשרים כו' שזהו בחי' ומדרגו' מרע\"ה כנודע שעיקר הכונה להמשיך האורו' בכלי' דש' ע\"ב דוקא לכך אמר משה ונתת\"י ושכינה מדברת מתוך גרונ\"ו הוא התלבשו' האורו' דח\"ע בכלי' דע\"ב גשרי' כנ\"ל וכמ\"כ אנחנו קוראין ק\"ש ואו' ג\"כ ונתת\"י מצד בחי' הביטול במס\"נ בפ' &lt;כא&gt;\nראשונה דק\"ש באהבת מאדך להתבטל במציאות מכל וכל בבחי' משה שאמר ונחנו<sup data-n=\"211\">62</sup> מ'\"ה שאזי שכינה מדברת מתוך גרונ\"ו להיות יוכל לומר ונתתי כנ\"ל וכדכתי' ואשים דברי בפי\"ך<sup data-n=\"212\">63</sup> וגו' כנודע, ונתתי מטר ארצכם זהו בחי' היחוד דמ\"ד ומ\"ן שהמ\"ן דארצכ\"ם מתחבר עם המ\"ד דדוכרא שיורד בגבורה שהוא בחי' מט\"ר שהוא התלבשו' אור החסד בכלי הגבורה כנ\"ל וד\"ל.",[["208","59","<b>ונתתי עשב בשדך</b>: עקב יא, טו."],["209","60","<b>שכינה מדברת מתוך גרונו של משה</b>: נסמן לעיל ע' יג."],["210","61","<b>מפי הגבורה אמרן</b>: ראה מגילה לא, ב."],["211","62","<b>ונחנו מה</b>: בשלח טז, ז."],["212","63","<b>ואשים דברי בפיך</b>: ישעי' נא, טו."]]],[2100490090,"<h3>תניא בספרי מי כה' אלקינו</h3>\n<b></b><b>בעזרה\"י, יום א' פ' וירא (שנת תקסואו לפ\"ק)</b>\nיום א' פ' וירא\n<b>תניא</b> בספרי מי כה' אלקינו<sup data-n=\"213\">1</sup> בכל קראינו אלי\"ו, אליו ולא למידותיו כו', והובא בפרד\"ס<sup data-n=\"214\">2</sup> ובכל ספרי המקובלים הקדומים, ומביאי' ראיה מזה שעיקר התפלה והקריאה צריך להיות אל עצמות המאציל ולא למדותיו הם ע\"ס הנאצלי' שלו ית' ומקשין ע\"ז ממרז\"ל<sup data-n=\"215\">3</sup> ע\"פ לדבקה בו וכי אפשר לידבק בשכינה כו' אלא",[["213","1","<b>תניא בספרי מי כה' אלקינו</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קנה, א).\nהנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נמצא בגוכתי\"ק 1194 עח, ב. בכותרת: יום א' פ' לך לך. ונדפס בסידור עם דא\"ח פה, ב. (נעתק בכת\"י 1001, 68 כא, א).\nהמאמר עם הגהות וקיצורים (על נוסח זה) נדפס באוה\"ת ואתחנן ע' שעו ואילך.\nלכללות מאמר זה ראה אמרי בינה פתח השער פס\"ז ואילך. שרש מצות התפלה להצ\"צ פ\"ז ואילך. ושם פ\"א ואילך."],["214","2","<b>בפרדס ובכל ספרי המקובלים</b>: פרדס שער הכוונה (לב) פ\"ב. אילמה רבתי מעיין א תמר א. וראה סה\"מ תקס\"ז ע' רמו בשם הספרא. וראה בחיי ואתחנן ד, ז. עקב יא, ג."],["215","3","<b>ממרז\"ל ע\"פ ולדבקה בו</b>: ראה סוטה יד, א. כתובות קיא, ב. ויק\"ר פכ\"ה, ג."]]],[2100490091,"הדבק במדותיו מה הוא רחום אף אתה רחום כו' דמשמע איפכא שא\"א לידבק בשכינה הוא עצמו' אור אין סוף ב\"ה (בחי' מל' דא\"ס שנק' שכינה<sup data-n=\"216\">4</sup> כנודע) דלית מחשבה תפיסא בי'<sup data-n=\"217\">5</sup> כלל זולת הדבק במדות הם ע\"ס שלו ית'. ומעתה איך נאמ' בספרי ע\"פ בכל קראינו אלי\"ו אליו ולא למדותיו. ומתרצי' שהכונה בהקריאה אלי\"ו ולא למדותי\"ו, היינו אל בחי' אור א\"ס ב\"ה המלובש בתוך הכלי' דע\"ס שלא תהי' הקריאה אל מדותיו הם הכלי' דע\"ס בלבד זולתי אל בחי' פנימי' האורו' המלובשי' בהם שנמשכו מאור אין סוף ב\"ה, ובזה בלבד נאמר אליו ולא למדותיו אבל אל בחי' עצמו' אור אין סוף ב\"ה הפשוט בתכלית הפשיטו' המרומם לבדו למעלה מגדר וסוג ע\"ס לית מחשבה תפיסא בי' כלל וע\"ז נאמ' מארז\"ל וכי אפשר לידבק בשכינה אלא הדבק במדותי' פי' בבחי' אור אין סוף המלובש בתוך מדותיו דוקא כנ\"ל. ומביאין עוד ראיה ממארז\"ל מפני מה ישראל צועקין<sup data-n=\"218\">6</sup> ואינן נענין בתפילה מפני שאינן יודעי' לצעוק בשם כו' הוי אומר שהקריאה הוא בשמותיו ית' הם הע\"ס שלו פי' אל בחי' האורות פנימי' המלובשי' בתוך הכלי' דע\"ס שמצטרך לכוין וליחד שם של ספי' ההיא שמצטרך בעת ההיא משא\"כ כשאינו יודע לכוין בשם ההוא לכך אינו נענה, וממשלי' משל בזה כמו עד\"מ במלך ב\"ו שיש אצלו שרים העומדי' על הפקודים שעל האוצרות ממונה אחר ועל התבואה ממונה אחר ועל המשפט ממונה אחר כו' דכאשר מצטרך העבד לבקש מאדונו המלך שיתן לו מעות אזי צריך לבקש פיתקא אל הממונה על הממון דוקא וכן תבואה צריך פתקא כתב המלך אל הממונה על התבואות לכך צריך לידע לקרוא אל המלך שיצוה אל הממונה ההוא שצריך לו דוקא אבל אם אינו יודע ש' הממונה שיבקש הפתקא של המעות &lt;כב&gt;\nאל הממונה על התבואות אזי יהי' מהצועקין ואינן נענין כו'. כך מפרשי'<sup data-n=\"219\">7</sup> מארז\"ל מפני מה ישראל צועקין ואינן נענין מפני שאינן יודעי' לכוין בשם שצריך לכוין בספי' ומדה ההיא שיצעוק אל בחי' אור א\"ס המלובש בה כנ\"ל במשל.\n<b>אך</b> ההכרע האמתי שביניהם הוא שיש הפרש בין בחי' ק\"ש לתפלה, שבק\"ש צריך להיות בחי' הקריאה והזעקה מנקודת הלב באהבת מאד\"ך<sup data-n=\"220\">8</sup> שהוא בלי גבול ותכלית (כמשמעו' פי' המלת בתיבת מאד בכל תנ\"ך (בל\"א זייאר) אל עצמות אור אין סוף ב\"ה דוקא הפשוט בתכלית הפשיטות המרומם לבדו שלמעלה מבחי' ע\"ס הנאצלי' (דלא כדברי המקובלים הקדומי').\n<b>וזהו</b> בכל קראינו אלי\"ו, אלי\"ו ממש ולא למדותיו דהיינו אל מהותו ועצמותו ית' שלמעלה מע\"ס הנאצלי' כו', אך בתפלה בלבד צדקו דבריהם להיות הכונה",[["216","4","<b>מל' דא\"ס שנק' שכינה</b>: ראה גם שערי אורה ח, ב. כב, א. לו, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' ס. שע\"ת קמה, ג. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] ה, ג."],["217","5","<b>דלית מחשבה תפיסא בי'</b>: תקו\"ז בהקדמה."],["218","6","<b>מפני מה ישראל צועקין</b>: ראה מדרש תהלים סו\"ס צא."],["219","7","<b>כך מפרשי'</b>: ראה תו\"ח יתרו [הוצאת קה\"ת — תשס\"ג] רנח, ד. וראה מקומות הנסמנים בראש המאמר."],["220","8","<b>מאדך. . בלי גבול</b>: ראה תו\"א ט, ג. יח, ב. לה, ד. לט, ג. סד, א. לקו\"ת ויקרא ד, ג. אמור לד, ב. שלח מז, א. ובכ\"מ."]]],[2100490092,"בפנימיות האורות המלובשי' בתוך הכלי' דע\"ס הנאצלי' שזהו כונת רז\"ל במה שאמרו מפני מה ישראל צועקי' בתפלה דוקא ואינן נענין מפני שאין יודעין לכוין בשם כו', בהיות ח\"י ברכאן דצלותא הם הכל בחי' המשכו' השפע מלמעלה למטה שיורדת השפע דרך הכלי' דע\"ס הנאצלי' דוקא שלזאת מצטרך לכוין בכונת הלב השם המיוחד של הספי' ההיא שמצטרך להתברך ממנה דוקא והיינו בהיות ידוע שהשמות של הספי' הם בחי' הפנימיו' האורו' של הכלי' דע\"ס הנאצלי', כמו ש'<sup data-n=\"221\">9</sup> הוי\"ה בנקוד פת\"ח הוא בחי' אור החכמה ראשית הנאצלי', והיינו כי החכמה<sup data-n=\"222\">10</sup> מאי\"ן תמצא והוא הכת\"ר דאצי' שנק' אי\"ן מצד שהוא סתום ונעלם כדכתי' ישת<sup data-n=\"223\">12</sup> חשך סתרו, שהוא מקור החכמה הגלויה דאצי' שהמשכת החכמה ממקורה אי\"ן האמיתי ראשית הגילוי שלה תחלת נביעתה ממקורה שנפתח מקורה אי\"ן האמתי הנעלם, ומתחיל לנבוע ראשית הגלוי של החכמה זהו ע\"י ש' הוי' בנקוד פת\"ח שהוא בחי' פנימית אור החכמה כמו שהיא נעלמה עדיין במקורה ושרשה בחי' אי\"ן דאצי' והאור מתחיל להתגלות ולנבוע מן המקור האין שנפתח מקורו ע\"י הפת\"ח דהוי' שיומשך ויתגלה בכלי החכמה דאצי' שלזה מורה נקודת הפת\"ח שתחת ש' הוי' שהוא פתיחו דיודין שנפת\"ח המקור המעיין הנובע מאי\"ן דאצי' ומתחיל לנבוע ולהתגלות מההעלם המקור בכלי החכמה דאצי' (כמו בנפש האדם תחלת הברקת החכמה המבריק במוחו מלמעלה מהשכל, דהיינו כשנובע בשכלו פתאום השכלה חדשה שמאי\"ן תימצא שאין מורגש המקור מאי\"ן נובעת החכמה ההיא לזאת התחלת וראשית הגילוי שלה שנפתח מקורה שלה אי\"ן האמיתי זהו בחי' אור הפנימי של החכמה שלכן יתלבש בכלי השכל שבמוחו כו' וד\"ל כנ\"ל). ולזאת בברכת<sup data-n=\"224\">13</sup> &lt;כג&gt;\nאתה חונן לאדם דעת צריך לכוין בשם הוי' שבניקוד פת\"ח להיות נפתח מקור חב\"ד דאצי' שהוא אי\"ן האמיתי דכת\"ר דאצי' ויביע השפע של האורו' דחב\"ד דאצי' בתוך הכלי' דחב\"ד דאצי' וזהו אתה חונן לאד\"ם דעת כו' וחננו מאתך חב\"ד כו'. ועד\"ז כשמצטרך לבקש פרנסה וכלכלה אזי צריך לכוין בשם של מדת הגבורה שהוא אור הפנימי של הגבורה שנק' צפון העליון כמ\"ש מצפון זהב יאתה וגו' וכשמצטרך לבקש חיים ארוכים אזי מצטרך לכוין בכונ' הלב לשם המיוחד האור הפנימי של ספי' החסד וזהו <sup data-n=\"225\">14</sup>מכלכל חיים בחסד כו' שהוא בחי' שם הוי\"ה בנקו\"ד סגו\"ל, וכשמצטרך לבקש רפואה יכוין לאור הפנימי דת\"ת שהוא בחי' רחמי' שלמעלה ועד\"ז כולן, וה\"ז כמשל הנ\"ל במלך ב\"ו שמצטרך לבקש ממנו פיתקא להממונה ההוא שמצטרך לו שהממונה אינו יכול לעשות מאומה זולתי בציווי המלך ששולח הפיתקא לו כו' כך עד\"מ למעלה הספי' הם הכלי' שבהם מלובשי' האורו' עליוני' של",[["221","9","<b>ש' הוי\"ה בנקוד פתח</b>: ראה פרדס (שער הנקודות) שכ\"ח פ\"ה. פע\"ח (שער העמידה) ש\"ט, פי\"ט. סידור האריז\"ל ומ\"ח שם. וראה ג\"כ תו\"א יתרו סז, ד. פיה\"מ קיב, ג. ובאוה\"ת ואתחנן ע' שעט מציין לזהר תולדות קמה, סע\"א."],["222","10","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["223","12","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["224","13","<b>בברכת אתה חונן</b>: נוסח שמו\"ע. ראה תו\"ח שם."],["225","14","<b>ספירת החסד. . מכלכל חיים</b>: נוסח תפלת העמידה. וראה מאמרי אדה\"א נצבים ע' תתקסב. שערי אורה כו, ב."]]],[2100490093,"המאציל ב\"ה שכאשר מצטרך להמשיך שיחננו בחב\"ד אזי צריך לכוין בשם הוי\"ה בנקוד פת\"ח שהוא שליח השפע מן המאציל ב\"ה אל בחי' אי\"ן האמתי דכת\"ר דאצי', שיתפתח מקורו להביע שפע אור החכמה בכלי החכמה בבחי' גילוי משא\"כ הוי\"ה בנקוד קמ\"ץ שהוא מורה על סתימו' החכמה הנעלמה בכ\"ע כמו הקמץ במבטא השפתיי' שנעשי' סתימה וקמיצה בשפתיי' מה שא\"א בלא\"ה להוציאו במבט\"א. כך למעלה נקודת הקמ\"ץ מורה על סתימו' הכ\"ע שהוא טמיר ונעלם דכתיב ישת חשך סתרו וגו' אבל הפת\"ח במבטא שנפתחי' השפתיים היפך הקמץ לכך למעלה מורה על פתיחו דיודי\"ן שנפתח המקור דאי\"ן דאצי' להביע שפע אור החכמה בבחי' גילוי דוקא כנ\"ל וזהו כונת רז\"ל מפני מה צועקים ואינן נענין שאינן יודעין לכוון בשם, שזהו דוקא בתפלה כנ\"ל אבל בק\"ש מצטרך להיות הרצוא מנקודת הלב אל מהותו ועצמותו ית' המרומם לבדו בבחי' אין ערוך אליו עד שאפי' החכמה דאצי' כעשי' גשמיות נחשבת קמי' במשקל ובפלס א' כדכתיב כולם בחכמה עשית<sup data-n=\"226\">15</sup>, עד שאין יתרון לחכמה דאצי' מן עשי' גשמיות ד' יסודו' ארמ\"ע הפשוטי' דעשי' נגד מהותו ועצמותו ית' דכלא קמי' כלא חשיבי בשוה השוה ומשוה קטן וגדול דכחשיכה כאורה שוין כו' כנודע וזהו כמ\"ש בספרי בכל קראינו אלי\"ו ממש, ולא למדותיו אפי' לא אל האורו' פנימים שבתוך מדותיו כ\"א אל מהותו ועצמותו ממש כנ\"ל וד\"ל<sup data-n=\"e3\">*</sup>.\n<b>וזהו</b> ענין יחודא<sup data-n=\"227\">16</sup> עלאה דק\"ש שנרמז במלת אח\"ד ענין היחוד דט\"ס דז\"א דאצי' בתכלית היחוד וההתכללות שזהו א\"ח דלי\"ת פי' ז\"א נק' א\"ח שהוא א\"ח להדלי\"ת הוא פרצוף לא\"ה בחי' מחשבה עלאה ופרצוף רח\"ל נרמז ביחודא תתאה דבשכמל\"ו כו' ולהבין כ\"ז באר הטיב צריך להבין ענין סדר ההשתלשלות עולמות דאבי\"ע כו'.\n&lt;כד&gt;\n<b>הנה</b> מבשרי אחזה אלוה<sup data-n=\"228\">17</sup>, דכמו עד\"מ בנפש האדם שהחכמה שבנפש השכלית מאין תימצא שלא כדרך ההשתלשלות כנודע אבל מחכמה ואילך נמשך הכל בסדר הדרגת ההשתלשלות דהיינו שהבינה נמשכת מהחכמה ומהבינה נמשכים ונולדים המדו' אהוי\"ר ומהמדות נמשכים ונובעת המחשבה ומהמחשבה הדיבור משא\"כ<sup data-n=\"229\">18</sup> המעשה היא נפרדת ממש שנמשכה שלא כדרך ההשתלשלות כמ\"ש במ\"א",[["226","15","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["227","16","<b>יחודא עילאה. . אחד</b>: זהר בראשית יח, ב."],["228","17","<b>מבשרי אחזה אלוה</b>: לשון הפסוק — איוב יט, כו."],["229","18","<b>משא\"כ המעשה. . כמ\"ש במ\"א (ע\"פ לכבודי)</b>: ישעי' מג, ז. ראה תו\"א מג\"א צה, ג. לקו\"ת אחרי כה, ד. ר\"פ בלק."],["e3","*","<b>בכת\"י 1042 הגה\"ה בגוכתי\"ק הצ\"צ בצידי הגליון</b>: וראי' לכל הנ\"ל ממי שתורתו אומנתו דמפסיק לק\"ש לפי שהיא בחי' אליו ממש ואינו מפסיק לתפלה שהיא לכוין בשם להמשיך לחיי שעה הוא המל' והתורה היא חיי עולם המשכה לז\"א כו'."]]],[2100490094,"(ע\"פ לכבודי בראתיו וגו' א\"ף עשיתיו שמלת א\"ף לחלק יצאת ע\"ש) שכ\"ז הוא סדר והדרגת ההשתלשלות נראה בעליל שכאשר יתחכם האדם ויתבונן בשכלו היטב באיזה מו\"מ כדומה שיראה בעין שכלו שיש ריוח גדול באותו סחורה אזי יתפעל לבבו מאד באהבה וחפץ לסחור הסחורה ההיא שהאהבה נולדה מן השכל וההתבוננות שמבין שיש בה ריוח בהמשך הזמן מ\"ה הגם שעתה אין ניכר הריוח כו' רק שהשכל מכריח שירויח אח\"כ לזאת תתפעל לבבו באהבה משא\"כ טרם שהשכיל בשכלו בהעמקת הדעת לא נתפעל לבבו שלא הרגיש עדיין בה טוב טרם שיסתעף מזה אח\"כ אך איזהו חכם הרואה את הנולד דוקא כנ\"ל, וכן בחי' מדת היראה יסתעף מהתבוננות השכל דכאשר מרגיש בעין שכלו שפלוני הוא שונא ואויב גדול לו אזי שומר נפשו ממנו שירא ממנו פן יארוב לדמו כו' הגם שמדבר עמו במענה רכה בשפת חלקות שמראה א\"ע לאוהב נאמן שלו בשפת מרמה אפשר ששבע תועבת בלבו והחכם<sup data-n=\"230\">19</sup> עיניו בראשו להבין דבר מתוך דבר<sup data-n=\"231\">20</sup> שלא יאונה לו כל און ומרמה, ולזאת ישמור נפשו ממנו שלא ילכד ברשתו, משא\"כ הפתי יאמן לכל דבר<sup data-n=\"232\">21</sup>, וידמה לו שהוא אהבו ומאמין לו בזה ולא יהי' נשמר ממנו ולבסוף יפול ברשתו ומצודתו הרעה. נמצא שעיקר הולדת המדות אהוי\"ר הוא מן השכל דוקא שע''י השכל נולדי' המדו' אהוי\"ר בבחי' גילוי לאהוב ולחפוץ לסחורה ההיא לסחור אותה שירוח בה אח\"כ, וכן להיות ירא מן האויב ולשמור נפשו ממנו שלא ילכד במצודתו הרעה כנ\"ל, משא\"כ זולתי השכל לא יהי' נולדים המדו' אהוי\"ר שכליים הללו כנ\"ל ומהמדות נובעות המחשבה לחשוב באותיות המחשבה בהדבר ההוא שמתאוה באהבה או שירא ממנו כנ\"ל ומהמחשבה יסתעף הדבור.\n<b>כך</b> למעלה ממש בחי' סדר והדרגות ההשתלשלות שהחכמה דאצי' בלבד מאין תימצא שלא כדרך ההשתלשלות אבל מחכמה ואילך נמשך הכל בסדר ההשתלשלות עילה ועלול בכל הפרצופים דאצי' שבינה נמשכת מהחכמה והיא אם הבנים<sup data-n=\"233\">22</sup> מקור המדו' דאצי' המסתעפים ממנה ומהמדות דז\"א דאצי' יסתעף פרצוף לאה מחשבה דאצי'<sup data-n=\"234\">23</sup> כו' כנודע, וכן בכל סדרי ההשתלשלות דבי\"ע עולמות הנפרדים שנפרדים ונבדלי' מערך וסוג עולם האצי' שאינם נמשכים ממנו דרך סדר ההשתלשלות זולתי שלא כדרך ההשתלשלות היינו ע\"י המסך מבדיל שבין אצי' לבי\"ע שהוא הפרסא כנודע שנמשכי' זמ\"ז בסדר והדרגה מעילה לעלול כנ\"ל.\n&lt;כה&gt;\n<b>וזהו</b> מ\"ש אליהו ז\"ל אנת הוא חד<sup data-n=\"235\">24</sup> ולא בחשבן אנת חכים ולא בחכמה ידיעא מבין ולא בבינה ידיעא כו' פי' אנת הוא בחי' עצמו' המאציל ב\"ה חד ולא בחושבן",[["230","19","<b>והחכם עיניו בראשו</b>: קהלת ב, יד."],["231","20","<b>להבין דבר מתוך דבר</b>: חגיגה יד, א. ראה מאמרי אדה\"א דברים ח\"ד ע' א'שמה."],["232","21","<b>הפתי יאמן לכל דבר</b>: לשון הכתוב — משלי יד, טו."],["233","22","<b>שבינה. . אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שער (כג) ערכי הכינויים מערכת אם הבנים. לקו\"ת דרושים לשמ\"ע פח, ד."],["234","23","<b>לאה מחשבה דאצי'</b>: ראה סידור ס, ג. סט, א. קג, ג. תו\"א ויצא כב, ד. תו\"ח ויצא כז, ד. שער היחוד פל\"ז. קהלת יעקב מערכת לאה ט."],["235","24","<b>אנת הוא חד</b>: תקו\"ז בהקדמה יז, א."]]],[2100490095,"ומנין ע\"ס דאצי' זולתי מרומם לבדו עד שאין להם ערך ויחס אליו כלל שהוא בחי' אין סוף ב\"ה שאין לו תחלה ואין לו תכלה כלל הפשוט בתכלית הפשיטו' מושלל מגדר תוארי' אלו עד שאין נערכים אליו כלל, שמשתווי' בערך הביטול אליו ית' כמו בחי' הדומם דעשי' ממש בלי יתרון וחשיבות שלהם עליו כלל מאחר ששניהם אינן בערך אליו לזאת כולם שוין כלא חשיבי כחשכה כאורה השוה ומשוה קטן וגדול כנ\"ל. אנת הוא חכים ולא בחכמה ידיעא זהו התלבשות אור אין סוף ב\"ה בחכמה דאצי' ונקרא חכים ולא בחכמה ידיעא מפני שבכל ההשתלשלות עולמו' הנפרדי' דבי\"ע נקראת החכמה דבי\"ע בחי' חכמה ידיעא מצד שרש ויחס לחכמה דעשי' אל החכמה דבריאה עפ\"י סדר ההשתלשלות אף שהיא רחוקה ממנה משא\"כ החכמה דאצי' מצד שעולם האצי' נבדל מן הכלל דסדרי ההשתלשלות דבי\"ע שהוא בחי' אלקות ממש דאיהו וגרמוהי וחיוהי חד כו' משא\"כ בי\"ע הם נפרדים ממש אשר אין להם ערך לאצי' כנ\"ל.\n<b>ובאור</b> הענין תחלה נבאר סדר ההשתלשלות דבי\"ע מלמטה למעלה, דהנה מציאות השכל אנושי הנמצא בנפש המשכלת של האדם שיש בכח נפשו השכלית להתחכם בכל ז' חכמו' ולהמציא השכלות עמוקות חדשות הרבה מאד עד שירום ונשא וגבה מאד<sup data-n=\"236\">25</sup> במעלת החכמה ותרב חכמתו מכל בני אדם שבארץ, שאף המדרגה המעולה שבחכמה זו של שכל אנושי אשר לא יהי' למעלה ממנו נמצא עוד או כמוהו בארץ נשפע זאת הכל מבחי' שמרי האופנים דעשי' כמ\"ש<sup data-n=\"237\">26</sup> בע\"ח ע\"ש שהאופני' בעצמן הם בחי' העגולי' דעשי' שנמשכו בריבוי ההשתלשלות מחיצוני' הכלים דע\"ס דעשי' (כי המלאכי' נמשכי' מיחוד נשיקין שהוא יחוד חיצוני כנודע) ובחי' שמרי האופנים שהוא החצוניות שלהם נעשה מקור החכמה לכל מציאות השכליים שבאנשים דעשי' שנביעת חכמתם היא מאין תמצא היינו בחי' מקור השכלי שלהם שהוא בחי' שמרי האופנים דעשי' כנ\"ל משא\"כ שרשה של נפש האלקית שהוא מבחי' עצמו' הי\"ס דעשי' שהם בחי' אלקות ממש שמלובש בהן בחי' אור אין סוף ב\"ה וכמו הערך והחשיבות דאופנים דעשי' אל בחי' עצמו' י\"ס דעשי' שנמשכי' רק מחיצוניות הכלי' ואף גם זאת ברבוי ההשתלשלות כנ\"ל, כך הוא הערך והחשיבו' דנפש השכלית הבהמית אל נפש האלקית דכמו שרחוקי' זמ\"ז במקור שרשם כך הוא למטה ממש כנ\"ל. אך אפי' חכמה שבי\"ס דעשי' עצמן שהיא בחי' אלקות ממש כדכתיב כולם בחכמה עשי\"ת שהוא מקור החכמה דקדושה של נפשי\"ן האלקי' דעשי' כנ\"ל היא נמשכת רק מבחי' תחתונה דיצירה דהיינו שמל'<sup data-n=\"238\">27</sup> דיצירה נעשה עתיק לעשי' פי' מל' דיצירה הוא בחי' הדבור עליון דיצירה שהוא מדרגה התחתונה סוף כל דרגין דיצירה נעשה עתי\"ק לעשיה להיות מקור החכמה דעשי' שהחכמה מאי\"ן תמצא בחי' עתי\"ק דעשי' שנמשך ממל' דיצירה כנ\"ל. &lt;כו&gt;\nוהיינו כמו עד\"מ החכם הגדול שמלביש שכלו בצרופי אותיו' הכתב או הדבור שאף כמו שהוא מלובש בכתב ולשון",[["236","25","<b>שירום ונשא וגבה מאד</b>: לשון הכתוב — ישעי' נב, יג."],["237","26","<b>כמ\"ש בע\"ח ע\"ש שהאופני' בעצמן הם בחי' העגולים דעשי'</b>: ראה פרדס שער (אבי\"ע) שט\"ז פח."],["238","27","<b>שמל' דיצירה נעשה עתיק לעשי'</b>: ראה עץ חיים שער (ו) העקודים פ\"ב."]]],[2100490096,"הוא עמוק עמוק מצד מעלת השכל שהוא בעצם נפלא מאד לכך אפי' כמו שהוא מלובש בכתב ולשון שאינו מערך עצמו' השכלות הרב כו' ואעפ\"כ הוא עדיין עמוק מאד שמצטרך התלמיד להתייגע ביגיעו' הרבה עד דקאים אדעתי' דרביה כו' כמו סברת הר\"ן והרא\"ש וכל בעלי תוס' שהלבישו שכלם בכתב ולשון כו' כך למעלה ממש שבחי' החכמה עליונה דיצירה נתלבשה בצירופי אותיו' הדבור עליון דיצירה שנעוץ תחלה בסוף ומאחר שיצירה היא דרך כלל הגבה למעלה מעשי' לזאת אפי' מל' דיצירה שהוא בחי' הדיבור שנתלבש בו החכמה דיצירה נעשה עתיק לעשי' להיות בחי' אי\"ן מקור החכמה דעשי' וכן מל' דבריאה נעשה עתיק ליצירה להיות אפי' החכמה דיצירה נמשכת מאי\"ן מקורה בחי' מל' דבריאה בחי' הדבור העליון בחי' תחתונה שבבריאה שנעשה ראש ומקור לכל סדרי ההשתלשלות דיצירה עשי' להיות נמשך ממנו בחי' חכמה דיצירה ומחכמה נמשכו כל הנפעלי' דיצירה בחי' הרוחין שביצירה ומיחוד פנימי נמשכו הרוחין של נפשות ישראל ומיחוד חצוני נמשכו המלאכי' כו' וכידוע שיש מסך מבדיל בין כל עולם ועולם בין בריאה ליצירה ובין יצירה לעשי' שהאור דמל' דבריאה בוקע המסך להאיר ביצירה וכן דיצירה בעשי' כו' וד\"ל.\n<b>אך</b> בחי' עולם האצי' נבדל מכל ההשתלשלות אלו שהוא בחי' אלקות ממש דאיהו וחיוהי וגרמוהי חד ממש לכך אמר אליהו ז\"ל אנת חכים ולא בחכ' ידיעא שהחכ' דאצי' אינה מערך ההשתלשלות שאף החכ' דעשי' יש לה ערך אל החכ' דבריאה ע\"פ סדר ההשתלשלות שנסתעפה ממנה משא\"כ החכ' דאצי' שהיא לא ידיעא בערך ההשתל' כנ\"ל וד\"ל.\n<b>והנה</b> כ\"ז הוא סדר ההשתלשלות דאבי\"ע שאף עולם האצי' שאינו בכלל ההשתלשלות דבי\"ע אעפ\"כ לגבי המאציל ית' נחשב ג\"כ בסדר ההשתלשלות שאין ערוך אליו כלל ע\"ס הנאצלי' כערך ע\"ס דעשי' ויתר על כן אף בחי' הסוף והתכלית של כל ההשתלשלות שהוא בחי' ד' יסודות פשוטי' דארמ\"ע שבעשי' הם נערכים במשקל ופלס אחד עם הע\"ס דאצי' לגבי עצמות המאציל ששניהם שוים באין ערוך אליו דכמו שהד' יסודות פשוטים דעשי' אין להם ערך אליו כך ע\"ס דנאצלי' שאין להם יתרון כלל כנ\"ל דאל\"כ הי' נערכים בערך ויחס אליו מאחר שיש להם יתרון על התחתונים אבל כיון שאינן בערך כלל לכך משתוים עם פחות הערוך שבנפעלי' כנודע.\n<b>ולזאת</b> אחר הדברים והאמת האלה מצטרך האדם להתעורר באהבה רבה מנקודת הלב אלי\"ו ולא למדותיו להיות נכספה<sup data-n=\"239\">28</sup> וגם כלתה נפשו אל מהותו ועצמותו ית' המרומם לבדו ומתנשא מימות עולם כו' ועי\"ז מיחד &lt;כז&gt;\nהאדם יחודי' עליוני' שנתיחדו ט\"ס דז\"א ביחד בתכלית היחוד שזה נרמז במלת אח\"ד א\"ח דלי\"ת כנ\"ל דלכאורה הוא פלאי מה שייך האדם ליחודי' עליוני' שיהי' הוא מיחדן כו', אך",[["239","28","<b>נכספה וגם כלתה נפשו</b>: ע\"ד לשון הפסוק — תהלים פד, ג."]]],[2100490097,"הענין דכתיב לך<sup data-n=\"240\">29</sup> הוי\"ה הגדולה והגבורה והת\"ת וגו' שהם המדות דז\"א דאצי' דכאשר האורות מצמצמי' בתוך הכלי' רק כדי ספוק צרכיהם לצורך קיום העולמות שכבר נמדדו בשעור ומדה זה בתחלת האצלת עולם האצי' דכתיב כי אמרתי עולם חסד יבנה<sup data-n=\"241\">30</sup> עול\"ם סתם הוא ז\"א דאצי' שנבנה פרצוף ז\"א ע\"י החסד של המאציל ב\"ה כי חפץ חסד הוא<sup data-n=\"242\">31</sup> מצד עצמו בלתי העלאו' מ\"ן שלמטה כלל כנודע אזי מחולקים הם זמ\"ז בהתחלקות ופרוד שמדת החסד הוא מהות בפ\"ע ומדת הגבורה ההפכיי ומנגד' אליה בפ\"ע כו' אבל ע\"י ההעלא' מ\"ן של התחתונים באהבה רבה מנקודת הלב אל מהותו ועצמותו ית' המרומם לבדו אזי יומשך עי\"ז מ\"ד מבחי' אי\"ן האמתי של המאצי' ב\"ה לעשות שלום במרומיו להיות נכללי' כל המדו' דאצי' בהתכללות יחד מצד עוצם ביטולם באי\"ן האמיתי שנמשך מהמאציל ב\"ה ולהוסיף אורו' בכלים דז\"א שלא כפי ערך ההשתלשלות שאזי מתבטלי' לגמרי והיו לאחדים ממש בהתכללות יחד ועי\"ז נעשה היחוד למעלה בט\"ס דז\"א שזהו בחי' יחוד עליון דתיבת אח\"ד א\"ח דלי\"ת, כנ\"ל וכמ\"ש בע\"ח שלצורך קיום העולמות בלבד הוא יחוד תמידי שאין לו הפסק דאו\"א דאצי' שהם תרין רעין דלא מתפרשין דזיווגייהו תדירי<sup data-n=\"243\">32</sup> שזהו רק בשביל קיום העולמות להחיותם עפ\"י סדר ההשתלשלות כנ\"ל, אבל היחוד דזו\"ן הוא לפרקי' בכדי להוסיף אורו' כו' כנ\"ל וזהו ואהבת<sup data-n=\"244\">33</sup> א\"ת הוי\"ה אלקיך שיהי' האהבה והרצון שיהי' הוי\"ה אלקי\"ך דהיינו שיתאוה ויחפוץ בגילוי מהותו ועצמותו שלמעלה מן ההשתלשלות ולא יכנף מוריך בלבושי ההשתלשלות שעי\"ז מעורר למעלה המשכת תוספת אורות מהמאציל ית' בהכלי' דז\"א דאצי' שלמעלה מההשתלשלות שעי\"ז מתיחדים ט\"ס דז\"א בהתכללות אחת כנ\"ל.\n<b>וזהו</b> עבודת האדם שלמטה שעבודה היא צורך גבוה ולכאורה יפלא וכי לשרות הוא צריך שנאמר לעבד\"ו עבודה זו מה זה עשה הלא אם צדקת מה תתן לו<sup data-n=\"245\">34</sup> ורבו פשעיך מה תעשה לו כו', אך העבודה הוא להמשיך תוספת אורו' באצי' שלא כדרך ההשתלשלות ומשם יגיע בבי\"ע וד\"ל.\n<b>וזהו</b> כונת מארז\"ל באמרם בכונת אחד כיון דאמליכתיה לארבע רוחות<sup data-n=\"246\">35</sup> כו' תו לא צריכתיה שכל דבריהם דברי קבלה רק הלבשו בענינים שלמטה והכל אחד, והיינו כי ד' רוחו' השמי' מזרח ומערב צפון וימין אתה בראתם<sup data-n=\"247\">36</sup> שלא היו טרם הבריאה כו' ועתה לעת נעשה בחפצו כל נתהוו ד' רוחו' מע\"ס שלמעלה שמזרח מקבל מחכמה ומערב ממל' ודרום מחסד וצפון מגבורה ומעלה מנצח ומטה מהוד",[["240","29","<b>לך ה' הגדולה</b>: דברי הימים-א כט, יא."],["241","30","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["242","31","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["243","32","<b>דאו\"א. . דזיווגייהו תדירי</b>: ראה זהר (אדרא זוטא) האזינו רצ, ב. עץ חיים שער הכללים פי\"ג. שער (טו) הזיווגים פ\"א. לקו\"ת נצבים מז, א. שה\"ש כב, ג. מאמרי אדה\"א בראשית ע' שנו."],["244","33","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["245","34","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["246","35","<b>כיון דאמליכתיה לארבע רוחות</b>: ראה ברכות יג, ב."],["247","36","<b>צפון וימין אתה בראתם</b>: תהלים פט, יג."]]],[2100490098,"כו' הגם שנתחלקו זמ\"ז ברחוק מקום אעפ\"כ לגבי הקב\"ה כתיב הנה המקום אתי<sup data-n=\"248\">37</sup> שנכללי' ומתיחדי' בתכלית היחוד כי ברוח פיו כל צבאם<sup data-n=\"249\">38</sup> ובדבר ה' שמים נעשו שבבחי' הדבור עליון בחי' מלכותו ית' &lt;כח&gt;\nנכללים כאחד בלי התחלקות רק שמשם יפרדו והי' לארבע רוחו' כו' אך לגבי המאציל ב\"ה נכללי' כאחד בתכלית היחוד וההתכללות כביטול הדבור בנפש האדם בעודו בכח חכמתו, רק באדם שלמטה כשהדבור יוצא ממנו נעשה נפרד אבל לגבי המאציל לית אתר פנוי מיניה ולא יפרד ממנו לעולם כ\"א הוא תמיד בבחי' הביטול בו לכך המקום אתו כנ\"ל, וזהו הכל מצד שרשם של ד' רוחו' וז' רקיעי' כו' שהם הט\"ס דז\"א דאצי' שנכללו כאחד מצד גילוי תוספת אור א\"ס ב\"ה כנ\"ל, וזהו כיון דאמליכתי' לד' רוחו' כו' תו לא צריכתי' שהכונה אחת בזה וד\"ל.\n<b>ברוך</b> שם כבוד מלכותו לע\"ו, זהו יחודא תתאה<sup data-n=\"250\">39</sup> דהיינו שא\"א להתגלו' השפע עליונה דאור אין סוף ב\"ה זולתי ע\"י התלבשותו במדת מלכותו ית' דוקא שנקראת בחי' עלמא דאתגלי' שע\"י התלבשותה בה דוקא מתגלה למטה מה דלא סגי בלא\"ה שיתגלה אורו הגדול ב\"ה בלתי לבוש כלל שאף לע\"ל שלא יכנף עוד מוריך<sup data-n=\"251\">40</sup> וכתיב עין בעין יראו<sup data-n=\"252\">41</sup> וגו' יהי' הכל דרך לבוש מדת מל' כמ\"ש בתפילה גלה<sup data-n=\"253\">42</sup> כבוד מלכות\"ך עלינו מהרה והופע והנשא עלינו לעיני כל חי כו' שעיקר ההתגלות יהי' רק בחי' כבוד מלכותו ית' שהוא מדת ההתנשאות שינשא עלינו דוקא עי\"ז יוכל להתגלות אלינו מה דלא סגי בלא\"ה כנ\"ל.\n<b>וז\"ש</b> בתפלה ברוך אתה הוי' אלקינו מלך העולם שכל הברכות והמשכות עליוני' נמשכי' הכל בבחי' מדת מל' ית' כנ\"ל וד\"ל.\n<b>ודברת</b> בם<sup data-n=\"254\">43</sup> בשבתך בביתך ובלכתך בדרך וגו' כתיב עוטה אור כשלמה זו תורה<sup data-n=\"255\">44</sup> דכתיב ותורה אור<sup data-n=\"256\">45</sup> שהיא הוד מעטה לבושו של הקב\"ה המחבר אותו עם כל ההשתלשלות דאבי\"ע שהחכמה שבתורה הוא מקור החיים של כל הנפעלי' כדכתיב כולם בחכמה עשית<sup data-n=\"257\">46</sup> וגו' ולזאת כל החיים של הנפעלים הוא חכמת התורה שיש בהן שאין לך גרוע משרץ ונשנית במתניתין בח' שרצי' כו' שהחולד והעכבר טמא כו' והצפרדע טהור כו' כדתנן במס' כלים ע\"ש וכה\"ג כל הנפעלי' נאמרו ונשנו בתורה שהתורה שיש בהן הוא החיים שלהן וכמ\"ש במ\"א ולכך ודברת בם דייקא",[["248","37","<b>הנה המקום אתי</b>: תשא לג, כא."],["249","38","<b>כי ברוח פיו כל צבאם</b>: תהלים לג, ו — וברוח פיו."],["250","39","<b>ברוך שם. . יחודא תתאה</b>: נסמן לעיל ע' ל."],["251","40","<b>שלא יכנף עוד מוריך</b>: ישעי' ל, כ."],["252","41","<b>עין בעין יראו</b>: ישעי' נב, ח."],["253","42","<b>גלה כבוד מלכותך עלינו מהרה</b>: תפלת מוסף ליו\"ט וימים נוראים."],["254","43","<b>ודברת בם</b>: ואתחנן ו, ז."],["255","44","<b>עוטה אור כשלמה זו תורה</b>: תהלים קד, ב. וראה סידור שער הציצית ג, ג ואילך. ספר המאמרים תק\"ע ע' פג."],["256","45","<b>ותורה אור</b>: משלי ו, כג."],["257","46","<b>כולם בחכמה עשית</b>: תהלים קד, כד."]]],[2100490099,"מצד שחכמת התורה היא כלי הביטול כ\"ח מ\"ה וכידוע שאין אור אין סוף מתלבש רק בכלי הביטול דכ\"ח מ\"ה מפני שאין יכול להתלבש בכלי היש כמארז\"ל אין<sup data-n=\"258\">47</sup> אני והוא יכולי' לדור בעולם אחד כו' ולזאת אף המדת עליונות נחשבי' ליש נגדו שהם מהו' דבר מה מהו' חסדי' וגבורו' שמקבלי' השפע ממנו דרך התלבשותו בחכמה דוקא ששם עיקר התלבשותו ומשם יביע אליהם כו' ולכך נאמר והגית בו יומם ולילה<sup data-n=\"259\">48</sup> להיותו מתיחד ביחוד תמידיי באור אין סוף המלובש בתורה ולא מסתיר אורו ית' מלהתגלות למטה כדכתיב ולא תחללו את שם קדשי<sup data-n=\"260\">49</sup> וגו' כנודע.\n&lt;כט&gt;\n<b>וקשרתם</b> לאות על ידיך<sup data-n=\"261\">50</sup> וגו' זהו המשכת גילוי אור א\"ס במורד למטה יותר להתלבש בעשי' בקלף הגשמיי דתפילין כו' ואח\"כ נאמ' בפ' שניה ואספת<sup data-n=\"262\">51</sup> דגנ\"ך שזהו המשכתו במורד יותר ולאסף דגנך דהיינו בחי' הברורין דרפ\"ח ניצוצין שנתפזרו בבי\"ע שיאספו ויתלקטו כאחד, והוא למטה פזור נפשו שנתפזרה בעסקי עה\"ז וטרדו' פרנסה, שנאסף ונתקבץ להכלל בקדושה ע\"י הברורין שיברר מהמאכלים והמלבושין ודומיהן להתפלל אח\"כ בכונה למסור<sup data-n=\"263\">52</sup> נפשו באח\"ד כנ\"ל וד\"ל.",[["258","47","<b>אין אני והוא יכולים לדור</b>: סוטה ה, א."],["259","48","<b>והגית בו יומם ולילה</b>: יהושע א, ח."],["260","49","<b>ולא תחללו את שם קדשי</b>: אמור כב, לב."],["261","50","<b>וקשרתם לאות על ידיך</b>: ואתחנן ו, ח."],["262","51","<b>ואספת דגנך</b>: עקב יא, יד."],["263","52","<b>למסור נפשו באחד</b>: ראה זהר (רעיא מהימנא) משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. ראה שו\"ת הרשב\"א ח\"ה סנ\"ה. ב\"ח טור או\"ח ר\"ס ס\"א. פע\"ח ש' הק\"ש פי\"ב."]]],[2100490100,"<h3>להבין בתוספת ביאור מאמר אנת הוא חד</h3>\n<b>בעזר\"ה, שבת פ' וירא</b>\n<b>להבין</b><sup data-n=\"264\">1</sup> בתוספת ביאור מאמר אנת*<sup data-n=\"265\">*1</sup> הוא חד ולא בחושבן כו', אנת הוא דאפיקת עשר תיקונין וקרית לון י' ספירן כו' עד חד אריך וחד קציר וחד בינוני. הנה תחלה יש להבין שרש ענין המאמר שאמר לבושי' תקינת לון כו' וכמה גופין תקינת לון דאתקריאו גופין לגבי לבושי' דמכסיין עלייהו כו', בהיות ידוע<sup data-n=\"266\">2</sup> דהשכל והמדו' נק' בחי' עצמו' הנפש עדיין לגבי לבושי' דמחשבה דו\"מ שנק' לבושי' נפרדי' ולגבי עצמו' הנפש גם המדו' והשכל נק' לבושי' אך ההפרש שיש בין לבושי'",[["264","1","<b>להבין. . אנת הוא חד</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1194 פב, ב (וחסר הסיום). והסיום נעתק מכת\"י 1001 מ, ב. 1156 סד, א (עם הגהות מגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ). נמצא ג\"כ בכת\"י 957 רנז, א. הנחה אחרת נדפס בתו\"א וירא יג, ג. הנחת ר' משה בן אדה\"ז נדפס לקמן ע' מו. וראה בהנסמן שם הערה 1.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ע' צז."],["265","*1","<b>אנת הוא חד</b>: הקדמת ת\"ז (יז, א)."],["266","2","<b>בהיות ידוע</b>: ראה ג\"כ לקו\"ת ויקרא ד, ב. וראה מאמרי אדה\"ז פרשיות ע' קלא."]]],[2100490101,"דמחשבה דו\"מ ללבושי' דשכל ומדו' היינו שלבושי' דמחשבה דו\"מ נק' לבוש נפרד ולבוש דשכל ומדו' נק' לבוש המחובר כו'. וביאור הדברי' הנה אנו רואי' שיש לבוש שיוכל ללבוש אותו ולפושטו כמו לבוש הגשמי על גוף האדם ויש לבוש שאינו יכול לפושטו אלא מתאחד עמו בתמידות והוא הגוף עצמו שגם הוא נחשב כמו לבוש לנפש כי הרי הוא מעור ובשר גשמי ונא' בו עור ובשר תלבישני<sup data-n=\"267\">3</sup> כו' אמנם לבוש הגופני הוא לבוש מחובר שאינו נפרד לעולם והמופת לזה שכאשר ינקוף אצבעו ירגיש מיד הנפש וכן כאשר ירצה לילך תיכף יניע רגלו לילך בלי שום שהי' ועיכוב אפי' רגע ואילו הי' זה בדרך התלבשו' הי' צריך שהי' קצת כמו התלבשו' השכל לחשוב ולדבר שיש בו שהי' קצת אבל התנועה של הרגל עפ\"י רצון הנפש איז בה שום שהי' כלל וכלל אפי' רגע מזה מוכרח לומר שאין הנפש בגוף בבחי' התלבשו' נפרד אלא בבחי' התלבשו' מחוברת ומתאחדת בתכלית כאילו הם מתחלת הבריאה עצם א' ממש וע\"כ תתפעל הנפש ממאורעו' מקרי הגוף תיכף ומיד בלי שום שהי' כלל וכלל וכו' משא\"כ בחי' לבושי' דמחשבה דו\"מ הן נק' לבוש נפרד מן העצם שהרי גם אחרי התלבשו' השכל במחשב' ודיבור מ\"מ הן מפורדי' שהרי יכול לפשוט ולפסוק מלחשוב ולדבר כו' וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל בלבוש הגופני שהוא נק' לבוש המחובר כך יובן בשכל ומדות עצמן דגם הם נק' לבוש מחובר לגבי עצמו' הנפש ואינם מעצמו' הנפש ממש והמופת ע\"ז שאינם מבחי' עצמו' הנפש ממש אנו רואי' ממה שמצינו בחי' קטנו' וגדלו' בשכל ומדו' ולא מצינו שינויי' אלה בעצמו' הנפש שהרי הנפש תמיד במהו' א' מיום הולדו עד היותו בן ע' שנה אך בזמן משך ימי שניו הוא נגדל בחכמה וכשהי' קטן הי' קטן בשכל וקטן במדו' וכשנגדל נגדל השכל ונגדלו המדו' מעט מעט עד שאמרו כל זמן שמזקינין<sup data-n=\"268\">4</sup> דעתן מתיישבתן כו' וגם במדו' כתיב לפי שכלו יהולל איש<sup data-n=\"269\">5</sup> כידוע ומבואר בלק\"א<sup data-n=\"270\">6</sup> אבל הנפש עצמה איננה בעלת שינויי' כלל בקטנו' וגדלו' כי היא אור אחד פשוט<sup data-n=\"271\">7</sup> בלתי מתחלקת ובלתי הסתעפו' עדיין בהתפשטו' להיות בבחי' הקטנו' או בבחי' הגדלו' אלא התפשטות במהו' השכל והמדו' ומתחלקת בהן לי' כחו' הוא שלא מבחי' עצמותה ממש אלא הן לה כמו בחי' הכלי בלבד אך שהוא בחי' כלי מחובר מפני שמתאחדי' עמה בתכלית ויובן זה ע\"ד דוגמא מכלי הגרזן ביד החוצב בו שיפעול פעולתו ע\"י הגרזן שהגרזן הוא כלי מחבר את הפועל עם הפעולה כו' כך השכל והמדו' הן בחי' כלים לחבר את הנפש לדבר הנפרד זולתה כמו שהנפש תתחכם בחכמת הרפואה וכיוצא ע\"י כח השכלי שיש בה שהכח הזה הוא כמו בחי' כלי שעל ידו תפעול הנפש פעולתה כו' וכמו עד\"ז להחכים ע\"י החכמה נק' כח החכמה בחי' כלי כך המדו' נק' כלים להביא את הנפש לידי אהבת דבר נפרד זולת הנפש כמו לאהוב הכסף וכיוצא אותה כלי המדה של אהבה שקבועה בנפש היא המחברת את הנפש ומביאת' לפעולת אהבת אותו הכסף",[["267","3","<b>עור ובשר תלבישני</b>: איוב י, יא."],["268","4","<b>כל זמן שמזקינין</b>: ראה סוף קנים."],["269","5","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["270","6","<b>בלק\"א</b>: ראה פ\"ו."],["271","7","<b>אור אחד פשוט</b>: ראה לקו\"א פנ\"א."]]],[2100490102,"וא\"כ האהבה כמו בחי' כלי ממוצע בין הפועל לנפעל ועד\"ז בכל המדו' פרטיי' כולן הן כחו' ממוצעי' ונק' לבוש עד\"מ הלבוש שעל ידו יתחבר כו' כך תמצא הנפש המצאה של שכל ע\"י כח החכמה וכיוצא ומה שנק' לבוש מחובר הוא לפי שמ\"מ השכל והמדו' מחוברי' ומיוחדי' בעצמו' הנפש והיו לאחדי' עמה יותר מחיבור הגוף לנפש כנ\"ל ואינם לבוש נבדל מן הנפש כו' וזהו עיקר ההפרש בין לבושי' דמחשבה דו\"מ שנק' לבוש נפרדי' אבל שכל ומדו' נק' לבוש מחובר מפני שנמשכי' מעצמו' הנפש ממש רק שנעשי' לנפש כמו בחי' כלים איברי הגוף לנפש אבל יותר דבוקי' בנפש מדיבוק איברי הגוף באיברי הנפש כו' וע\"כ נק' המדו' בחי' מהו' ועצמו' לגבי לבושי' דמחשבה דו\"מ כו' וכמ\"ש בלק\"א<sup data-n=\"272\">8</sup> וד\"ל. ובכל זה יובן פי' התחלת המאמר אנת הוא דאפיק' עשר תקונין כו' דלכאורה אינו מובן למה קראן בשם תיקונין ולא קראם בשם לבושי' כו'. אך הענין הוא משום דמדבר באורו' דאצי' עצמן כמו שהן מלובשי' בכלים שהוא כדוגמת השכל והמדו' באדם כשמלובשי' באברי הגוף כנ\"ל שהן הנק' תיקוני\"ן משום שהן בחי' כלי תיקון לנפש שעל ידם תתחבר הנפש כנ\"ל כך למעלה על ידי הי\"ס שמלובשי' בכלים יומשך אור א\"ס ויפעול פעולותיו בכלל ע\"י הכלי דחכמה ישפיע שפע חכמה למטה בכל העולמו' עד חכמה דעולם העשי' וכן ע\"י כלי החסד יפעול פעולת המשכת אור החסד עד למטה מטה בחסד גשמי שלנו כו' וע\"כ נק' בשם תיקונין שהוא כמו שתרגם המתרגם לא ילבש<sup data-n=\"273\">9</sup> גבר בשמלת אשה לא יתקן גבר בתקוני' דאתתא כו' כמו כלי התכשיט לאשה שמתקנה כו' כך הי\"ס שבכלים נק' תקוני\"ן שעל ידם יתוקן אור השפע כו' אמנם לפי שהן בחי' לבוש מחובר ולא לבוש נפרד ע\"כ קראן בשם תקוני\"ן ולא בשם לבושי' ממש כו' כי הרי מתאחדי' עם המאציל בתכלית וכמאמר הידוע דבאצי' איהו וחיוהי וגרמוהי<sup data-n=\"274\">10</sup> חד כו' ור\"ל בזה ב' דברים הא' האורו' חב\"ד ומדו' שקבועי' באור המאציל בתכלית היחוד ע\"ד דוגמת שכל ומדו' באדם התחתון ועוד גם בחי' התלבשותן בכלי' ואיברי' ג\"כ עדיין הן מתייחדי' עם אור המאציל וז\"ש וגרמוהי שהן הכלים והוא משום שנק' גופין וכמו שהגוף מתאחד ג\"כ עם הנפש כנ\"ל וד\"ל. וזהו שאמר כמה גופין תקינת כו' כי בחי' לבושי' דמכסיי' כו' היינו בחי' לבושי' דמחשב' דו\"מ שבבי\"ע שנק' עלמי\"ן נפרדין כידוע אבל באצי' עצמו נק' גופין מטעם דאיהו וחיוהי וגרמוהי חד כו' אלא שנק' בשם לבוש מחובר משא\"כ לבושי' דמכסיין עלייהו נק' לבוש נפרד ממש שיוכל ללבוש ולפשוט וכנ\"ל וד\"ל (ומפני שבמלת תיקוני\"ן סובל ב' הדברי' לבוש ואינו לבוש כמשמעו' התרגום על לא ילב\"ש כו' לא יתקן בתקוני כו' ע\"כ קרא לי\"ס עצמן בשם תיקוני\"ן וכמו אתקריאו בתקונא דא חסד כו' משא\"כ בבי\"ע שלא נק' רק לבושי' כו' וד\"ל).\n<b>אנת</b> חכים ולא בחכמה ידיעא כו'. הנה אע\"פ שמתבאר מתוך משל הנ\"ל בשכל ומדו' שבאדם שהם נק' תקוני\"ן מפני שעל ידם יפעול כו' שגם למעלה הרי הי\"ס בכלים דאצי' הן הן בחי' המקוריי' והשרשיי' לכל פרטי ההשתלשלו' הנמצאי'",[["272","8","<b>וכמ\"ש בלק\"א</b>: פ\"ג. פי\"ב."],["273","9","<b>שתרגם. . לא ילבש</b>: ראה ת\"א תצא כב, ה."],["274","10","<b>איהו וחיוהי וגרמוהי</b>: ראה ת\"ז ג, ב."]]],[2100490103,"בעולמו' הנפרדי' מאחר שהן נק' תקוני\"ן עד\"מ הנ\"ל, מ\"מ אין שום ערך והשתוו' כלל וכלל בין חכמה הנמצא' בעולם הנפרד לבחי' החכמ\"ה שבי\"ס דאצי' וע\"ז אמר אנת חכי\"ם ולא בחכמ' ידיעא פי' אע\"פ שהושפל האור של המאציל להפעיל פעולת שפע החכמ\"ה למטה ע\"י כלי החכמ' דאצי' שבה נק' חכי\"ם כנ\"ל מ\"מ עדיין אין אותה חכמה שנק' בה חכי\"ם ענין חכמ\"ה ידיעא כמו החכמה הנמצא בעולם הנפרד אלא מובדלת בערך לגמרי אע\"פ שהיא בחי' המקור לכל חכמה הנמצא כנ\"ל ויובן ערך זה עפ\"י משל כח המצמיח התפוח או מזל המכה ומגדלו שיש מצמיח ומגדל תפוח מתוק או מצמיח ומגדל תפוח חמוץ וכיוצא ובודאי כל מזל מיוחד להגדלה הפרטי' של אותו התפוח הפרטי דוקא ולתפוח אחר נמצא מזל מיוחד אליו וא\"כ בהכרח שימצא מעין מתיקו' התפוח באותו המזל המיוחד להגדיל תפוח הזה כי מהיכן נמצא מציא' מתיקו' זאת בתפוח זה אם לא מאותו כח המכה ומגדלו במתיקו' זאת וזה בודאי א\"א לומר שמהו' מתיקו' גשמי' כזאת נמצאת במזל הרוחני אלא ודאי שמתיקו' במזל הוא מתיקו' רוחני כענין מתיקו' מניגון טוב או מתיקו' ועריבו' משכל וסברא וכידוע דכל בחי' מתיקו' הוא מסטרא דחסד אך שמתחלק לפי אופן המדרגה ברוחניו' וגשמיו' וערך מתיקו' התפוח נמצא ממציא' מתיקו' הרוחניו' שבמזל שהוא כמו ערך מתיקו' שכל וכיוצא ועד\"ז עד רום המעלו' יובן גם במציא' החכמה ממקור החכמה דהיינו בחי' חכמה דאצי' הנ\"ל וכן ערך מדת הרחמי' גשמיי' למטה לגבי בחי' מקור הרחמי' למעלה בי\"ס וזהו אנת חכי\"ם ולא בחכמ' ידיעא כשלנו ועד\"ז בשאר המדו' וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין התחלת המאמר אנת הוא חד ולא בחושבן כו'. והנה תחלה יש להבין בשרש ענין בחי' צמצום הראשון הנק' מקום פנוי וחלל ריקן<sup data-n=\"275\">11</sup> כו' ובענין בחי' הפרסא הידוע המפסיק ביו האצי' לבי\"ע<sup data-n=\"276\">12</sup>, ומהו ההפרש בין בחי' הפרסא לבחי' הצמצום הראשון הנק' מקום פנוי כו'. ויש להקדים תחלה להבין שרש ענין פי' האצי' מהו לשון אצילו' דוקא. הנה לשון אצי' הוא לשון הפרשה והבדלה כמו שנא' במשה ויאצל מן הרוח<sup data-n=\"277\">13</sup> כו' דר\"ל שהפריש והבדיל ההארה מקצת ממדרגתו העצמי כו'. והנה ע\"ד הפשוט הי' עיקר הטעם למה שנאצל מרוחו של משה על ע' הזקנים להיות כי מעלת ומדרגת משה הי' גבוה מאד נעלה עד שבשביל שפע גשמית כמו ליתן להם בשר לא הי' יכול משה להשפיל א\"ע כ\"כ ולכך אמר מאי\"ן<sup data-n=\"278\">14</sup> לי בשר כו' וע\"כ נאצל והופרש מרוחו בירידת המדרגה בע' הזקנים ואע\"פ שגם הם נתנבאו כמ\"ש ויתנבאו ולא יספו<sup data-n=\"279\">15</sup> כו' מ\"מ כבר הוקטן מדרגתם הרבה ממדרג' משה אחר שהופרש עליהם רק הארה בעלמא וגם זאת נבדלת היא מרוחו של משה הרבה כו' ולהיותם בקטנו' המדרגה יכלו להשפיע לכנ\"י גם השפעה גשמי' ולזה הטעם אמר למשה ואצלתי מן הרוח<sup data-n=\"280\">16</sup> כו' והדוגמא דדוגמא מזה יובן ג\"כ למשכיל למעלה שכדי שיהי' אור אלקי בחי' מקור למציא' נבראי' בעלי גבול כו' לא",[["275","11","<b>מקום פנוי וחלל ריקן</b>: ראה ע\"ח שער (א) עגולים ויושר ענף ב."],["276","12","<b>הפרסא. . לבי\"ע</b>: ראה ע\"ח שער (מז) סדר אבי\"ע. לקו\"ת שה\"ש מב, ב."],["277","13","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה."],["278","14","<b>מאין לי בשר</b>: שם שם, יג."],["279","15","<b>ויתנבאו ולא יספו</b>: שם שם, כה."],["280","16","<b>ואצלתי מן הרוח</b>: שם שם, יז."]]],[2100490104,"הי' צמצום שפע כזאת נמצאת מעצמו' המאציל מפני שהוא מרומם ומובדל גבוה מאד נעלה ע\"כ הוצרך להאציל ולהפריש בבחי' הבדלה אורו' הנאצלי' שמהן יושפע כל השפעה כו' להיות שהאצי' כבר הוא בערך קטנו' המדרגה וכדוגמת משל ע' הזקנים הנ\"ל וזהו הטעם שנק' בלשון אצילו' מלשון הפרשה דוקא וד\"ל. והנה באמת יותר אין ערוך בין אצי' לגבי המאציל משאין ערך בריא' לגבי האצי' כו' שהרי בין אצי' לבריא' אינו מפסיק רק בחי' פרסא בלבד ובין המאציל לנאצלי' הוצרך להיו' בחי' צמצום מקום פנוי לגמרי כו'.\n<b>וביאור</b> ענין ההפרש ביניהם יובן בהקדים תחלה שיש בחי' מאור ובחי' אור כידוע והמאור הוא עצמו' הדבר כמות שהוא והאור אינו אלא בחי' התפשטו' בעלמא ממנו כמו אור היום שהוא הזיו<sup data-n=\"281\">*16</sup>* שמאיר מזיו השמש וכמ\"ש ויקרא<sup data-n=\"282\">17</sup> אלקי' לאו\"ר יום כו' אבל גוף ומהו' השמש נק' מאור וכמ\"ש ויברא ה' שני המאורו'<sup data-n=\"283\">18</sup> כו' ועד\"ז גם נפש החיונית שבגוף האדם הוא ג\"כ בדרך אור ומאור כי הנה ידוע דמה שהגוף יחי' מחיו' הנפש אין חיו' זה מעצמו' ומהו' הנפש כ\"א רק מבחי' אורה וזיווה בלבד דהיינו רק מבחי' התפשטות ההארה ולא מעצמות' כו' כמ\"ש במ\"א ע\"פ כי עמך מקור חיים<sup data-n=\"284\">19</sup> באור\"ך כו' ועד\"ז יובן גם באבר פרטי בגוף שהוא ג\"כ בבחי' אור ומאור כמו כח הראי' בכלי העין הנה כח הראי' עצמו גם שיסגור כלי העין נמצא כחו הרי הוא הנק' בשם מאור כמו שנק' מאור עינים<sup data-n=\"285\">20</sup> כאשר הוא סומא מפני שלא נתגלה הזיו בעין ונשאר רק המאו\"ר של העיני\"ם כו' והתפשטו' הראי' מן העין הוא רק כמו בחי' הזיו והאור מן עצם המאור כו' וכידוע. והנה אנו רואי' שכאשר יסגור כלי העין ולא יביט בה כלל ונשאר כח הראי' בנפש כמו שהוא בעצמו ומהותו מבלתי התפשטו' אור וזיו כו' אין הענין שנתבטל מציא' האור וההתפשטו' של הראי' לגמרי כי דבר רוחני לא יתבטל לעולם והרי יש כח רוחני בהבטה והסתכלו' כידוע מבת היענה כו' אלא הענין הוא שנכלל האור הזה במאור העין ואין התכללו' זאת בבחי' ביטול האור אלא אדרבה נתחזקה במאור העין ביתר שאת ועכ\"פ ישנה שם במציאותה בודאי בלי תוספת או גרעון מכמו שהיתה שהרי חוזרת ומתפשטת כמבראשונה כשפותח כלי העין וא\"כ אין הענין אלא שנעשה מן הגילוי העלם דהיינו שגילוי הראי' נעשי' להיו' בבחי' העלם עצמו' המאור ואין זה שינוי כלל וכלל גם בעצם האור ואע\"פ שנעשה בבחי' העלם והוא העדר ההתגלו' אין העדר זה שינוי בעצמו כלל וכלל. ויובן זה בביאור יותר עפ\"י משל אחר בכחו' הנפש כמו השכל שהוא כח מכחו' הנפש ויש בו ג\"כ בחי' אור ומאור דהיינו כשישיגו החכם בלמדו איזה שכל וסברא אזי נגלה העלם כח השכלתו וכשמפסיק מלהבין ולהשיג את השכל וסברא הנה בחי' אור ההתגלו' נכלל בכח השכלתו ובודאי לא נתבטלה כלל אור ההשג' הנגלי' לו כי הרי ישיב לשואלו מיד אלא נכללת האור ונשארת בו בבחי' כח",[["281","*16","<b>שהוא הזיו</b>: תיבות אלו ניתוספו בכת\"י 1156 בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ."],["282","17","<b>ויקרא אלקי' לאור</b>: בראשית א, ה."],["283","18","<b>ויברא ה' שני המאורו'</b>: ראה בראשית א, טז."],["284","19","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["285","20","<b>מאור עינים</b>: ראה ג\"כ אוה\"ת בראשית תתרלח, ב."]]],[2100490105,"העלמי וא\"כ הרי מזה מובן יותר שאור וגילוי השכל לא ישתנה מפני העדר התגלותו בשעה שמפסיק מללמוד כו' וד\"ל. והנמשל מכל אלה המשלי' בבחי' אור ומאור ואיך שהעדר ההתגלו' איננו שינו\"י גם בעצם האור כו' יובן כמ\"כ למעלה מעלה בבחי' הצמצום הראשון הנק' מקום פנוי וחלל ריקן כו' שאין הענין שהוא מקו\"ם פנו\"י וריקן ממש ח\"ו אלא מפני ששם הוא העדר התגלו' האור שמאיר מעצמו' המאור הנק' א\"ס לכך קראו בשם חלל כו' לפי שבלשון המקובלי' נק' ענין ההתפשטו' וההתגלו' בשם או\"ר כמו י\"ס שנק' בשם אורו' כידוע והוא ענין מציא' יש ודבר מה ע\"כ קורא למה שהוא בחי' העדר ההתגלו' בשם מקו\"ם פנו\"י וחלל כו' אבל לא שהוא פנו\"י לגמרי אלא הוא עד\"מ הנ\"ל בכח הראי' שנתפשט' כשנכללת במאור העיני' או כמשל כח התגלו' שכל שנכלל בכח השכל העצמי כו' שאין זה שינוי כלל וכלל גם בעצם האור כו' ואיך נקרא אותו פנוי לגמרי מן האור כו' אלא הענין הוא רק בחי' התכללו' האור במאור שישנו במציאו' כמו שהי' ממש וכנ\"ל וד\"ל. והנה ידוע דאחר הצמצום הזה הנק' מקום פנו\"י כו' נשאר בחי' רשימ\"ו וממנו נמשך בצמצום קו וחוט דק בלבד כו' כמ\"ש בע\"ח<sup data-n=\"286\">21</sup> והוא ענין התגלו' מצומצמת מאד אחרי העדר ההתגלו' וה\"ז כמשל השפעה לתלמיד עמקו' שכל שלא יוכל לקבל שמוכרח המשפיע לצמצם ולהעלים הכל בתחילה ואח\"כ יאמר לו רק כמו תיבה אחת והוא שכל מעט מזעיר מאד שנשאר ממה שהניח מכל עומק השכל כו' ואז יוכל לקבל כמ\"ש במ\"א וד\"ל. וא\"כ נמצא מובן מכל זה שאין ערוך כלל וכלל בין אצי' עם עצמו' המאציל מאחר שהי' תחלה ענין העדר התגלו' לגמרי ולא נשאר רק אפס קצהו וגם אותו בחי' הקו כו' הוא בא אח\"כ בהתלבשו' בין א\"ק לנאצלי' והוא הנק' פרסא<sup data-n=\"287\">22</sup> שבין א\"ק לנאצלי' כידוע ועוד כמה צמצומי' היו עד שנעשה בחי' אורו' וכלים בנאצלי' כידוע מענין ההבלי' דאח\"פ דא\"ק<sup data-n=\"288\">23</sup> כו' ומענין עקודי'<sup data-n=\"289\">24</sup> שהוא עקוד בכלי א' ואח\"כ נקודי' כו' עד שנתהוו ריבוי הכלים באצי' כו', אבל מאצי' לבי\"ע אין שם רק בחי' פרסא בלבד ואין שם ענין צמצום מקום פנוי וחל\"ל הנ\"ל כו' והענין של הפרסא ידוע בשם הה\"מ ז\"ל שהוא עד\"מ התגשמו' השכל בצרופי' זרים שלא מערך דקו' השכל כלל כמו התלבשו' איזה שכל עמוק במשל וחידה כמו משלי שלמה בן חכם ישמח אב<sup data-n=\"290\">25</sup> כו' שהשומע משל זה ואינו מבין ומשיג סוד העמוק שמלובש בזה הרי הוא משיג הדברי' כפשוטן שבן החכם ישמח בו אביו כו' וזהו דברים שגם התינוקו' יודעי' והן דברי' בטילי' ממילין דהדיוטא כו' וכיוצא בזה אך שמלובש בזה סוד עמוק למעלה מעלה כמו שהוא בבחי' אב למעלה ובבחי' ב\"ן למעלה כו' וכיוצא וגם מי שיבין וישיג מזה המשל הסוד ההוא אינו משיג כמו שהוא הענין באמת למעלה רק מעין ודוגמא בלבד וגם זאת הוא מבין בדרך התלבשו' זר במשל וחידה בלבד והוא בתכלית ההגשמה כו' וכמ\"כ הוא ענין בחי' הפרס\"א למעלה שהוא ירידת",[["286","21","<b>כמ\"ש בע\"ח</b>: שער (א) עגולים ויושר ענף ב."],["287","22","<b>פרסא שבין א\"ק לנאצלים</b>: ראה לקוטי הש\"ס להאריז\"ל (חולין ס, ב ד\"ה) לכי ומעטי (כ, ב)."],["288","23","<b>ההבלי' דאח\"פ דא\"ק</b>: ראה ע\"ח שער (ד) אח\"פ."],["289","24","<b>עקודים. . בכלי א' ואח\"כ נקודי'</b>: ראה ע\"ח שער (ו) עקודים פ\"א."],["290","25","<b>בן חכם ישמח אב</b>: משלי י, א. טו, ב."]]],[2100490106,"אור העליון לבא בהגשמה בצרופי' אחרים וזרים שלא מערך עצם האור כלל וכלל בכדי שיוכל המקבל לקבל אחרי בקיעת האור דרך הפרסא שנק' אור של תולדה כידוע עד\"מ המסך העב שמעלים האור הגדול ואמנם עכ\"ז יסתכלו באור הגדול קצת גם דרך עובי המסך אך שאין ההארה מאירה כמו שהיא אלא בהגשמה גדולה כו' וכך ע\"י בקיעת הפרסא למעלה יבא אור השפע למקבלי' עד שיוכלו לקבל מפני שבא כבר בהגשמה כו' וד\"ל. והנה אע\"פ שבא האור דרך הפרסא בהגשמה מ\"מ כל האור כמו שהוא מאיר דרך בקיעת כל עובי שטח המסך וכך גם בענין המשל וחידה הרי כל השכל העמוק כמו שהוא כולו מתלבש במשל וחידה רק שמבינים ומשיגי' אותו בדרך גשמית אבל מ\"מ כולו מושג ונגלה לכל מבין אך שלא יבינו כמו שהוא בדרך הרוחני כו' והנמשל מזה יובן ג\"כ בבחי' פרסא למעלה דכל האור כולו מתלבש במסך הפרסא רק שבא בהתלבשו' כו' והענין הוא שכל מה שלמעלה באצי' הרי נמצא מעין ודוגמא גם למטה בבי\"ע כמו חכמ' דאצי' הרי נמצא החכמה גם בעולם הבריא' אלא שהיא מעין ודוגמא בלבד מפני התלבשו' והתגשמו' אור החכמ' דאצי' בבחי' הפרסא כו' ועד\"ז בכל פרטי שפע הי\"ס דאצי' שמאירי' בבי\"ע דרך בקיעת הפרסא הרי כולן כמו שהן מאירי' רק שבאין למטה בבי\"ע אחרי ההתלבשו' ובחי' ההגשמ' דפרסא כו' משא\"כ בחי' הצמצום הראשון שלפני האצי' הנק' מקו\"ם פנוי וחל\"ל כו' שבין עצמו' המאציל לנאצלי' כנ\"ל הרי הוא ענין העדר ההתגלו' והוא בחי' התכללו' האור במאור לגמרי כנ\"ל ולא נשאר רק אפס קצהו הנק' רשימ\"ו בלבד וממנה שרש הארת השפע באה לנאצלי' כנ\"ל א\"כ מזה מוכרח הענין לומר שאור האצי' אין ערוך לגבי המאציל יותר משאין ערך הבריא' עם האצי' שהרי בין אצי' לבריאה איז שם בחי' העדר התגלו' לגמרי אלא רק ענין התלבשו' בפרסא אבל כל האור מתלבש בו כנ\"ל וד\"ל, ועיקר סיבת התגשמו' הפרסא עצמה נעשית מבחי' מל'<sup data-n=\"291\">26</sup> דאצי' עצמה כי הנה ידוע דבחי' מל' דאצי' נעשה עתי\"ק לבריא' ובחי' מל' דאצי' היא מלאה אותיו' וצרופי' הרבה כמ\"ש בס\"י וההתגשמו' הוא שינוי הצרופי' במה שמשנה מצירוף דאצי' לצירוף זר ע\"ד החידה ומשל לגבי השכל כנ\"ל והוא הנק' פרסא ואח\"כ בוקעת הפרסא הזאת ומאיר בעולם הבריא' בבחי' כת\"ר והוא הנק' עתי\"ק דבריא' כמ\"ש בע\"ח<sup data-n=\"292\">27</sup> וד\"ל.\n<b>וזהו</b> פי' התחלת המאמר אנת הוא חד ולא בחושבן, פי' ולא בחושבן י\"ס אלא בלא שיעור ומספר כו' כי הרי מבואר למעלה דדוקא מאצי' לבריא' כל האור כולו מתגלה אך שהוא בא דרך התלבשו' בפרסא אבל מן המאציל לנאצלי' הי' ע\"י צמצום והעדר האור כו' הנק' מקום פנו\"י כו' וא\"כ בעצמו' אור המאציל א\"א לומר שיש בו ענין מספר הי\"ס הללו דוקא מאחר שרק אפס קצהו בלבד נתגלה וממנו שרש הי\"ס כנ\"ל ואין להם ערוך כלל וכלל עם העצמו' כנ\"ל וזהו שאמר אנ\"ת דוקא שהוא עצמו' המאציל הוא ח\"ד ולא בחושב\"ן י\"ס אלא ח\"ד כו' כלומר או שהוא מאצי' בלי שיעור ומספר או כשאינו מאצי' הוא חד אור א' פשוט כו' ושניהם אמת כמ\"ש במ\"א וד\"ל.",[["291","26","<b>הפרסא. . מל'</b>: ראה הגהות לד\"ה פתח אלי' תרנ\"ח ע' סח."],["292","27","<b>כמ\"ש בע\"ח</b>: ראה שער (מז) סדר אבי\"ע רפ\"ו. שער (מב) דרושי אבי\"ע פ\"א."]]],[2100490107,"<b>אנת</b> הוא דאפיק' י' תיקונין וקרית לון י' ספירן כו'. הנה מה שאמר אנת הוא דאפיק' כו' בא לפרש בזה שלא יטעה הטועה לומר מאחר שיותר אין ערוך מאצילו' לגבי המאציל משאין ערוך לבריא' עם הבורא מטעם הנ\"ל א\"כ יש לחשוב ח\"ו שהאצי' בבחי' נפרד מן המאציל ע\"כ אמר אנת הוא דאפיקת י' תקונין כלומר אעפ\"כ אינם מובדלי' ומופרדי' כלל וכלל, מעצמותך כי אנת הוא דאפיק' לון כו' ע\"ד במקום גדולתו<sup data-n=\"293\">28</sup> שם אתה מוצא ענוותנותו כו' וגם כאן הגם שהיתה בחי' שפלו' וירידה להיו' נשפל מעצמו' ולהקרות בשם חכים או מבין וכיוצא כי מצד עצמותו לאו דאית לי' מכל אינון מדו' כלל וכלל מ\"מ הרי הי\"ס מיוחדי' במאציל אחר שירד ונתלבש בהן משום דאיהו וחיוהי וגרמוהי חד כו' וכמשל התלבשו' כחו' האדם בכלי גופו כמו כח הראי' בכלי העין וכח השכל במוחו וכח השמיעה באזן וכיוצא הגם שאיברים הללו עין ואזן נבדלי' בבחי' דבר נפרד חוץ מעצמו' הנפש וכחותי' מ\"מ מתאחדי' עמה בתכלית וכמ\"ש למעלה וגם בחי' הכחו' הרוחניים הללו כמו כח השכל וכח הראי' וכח השמיעה אע\"פ שאינן מעצמו' הנפש ממש כנ\"ל מ\"מ הנפש מתלבשת בהן ועל ידן תפעול כל פעולתה כמו ע\"י כח הראי' יביט למרחוק וע\"י כח השכל ישכיל בכל דבר חכמה כו' וכיוצא בזה יובן למשכיל למעלה די\"ס נק' י' תקונין של המאציל ופי' שעל ידם יפעול פעולותי' כמו ע\"י אור ספי' החכמה ישפיע חכמה למטה וע\"י בחי' כח הראי' יביט למטה בבחי' השגחה פרטי' וכמ\"ש משמים הביט ה'<sup data-n=\"294\">29</sup> ראה את כו' וכמו ענין ארדה נא ואראה<sup data-n=\"295\">30</sup> הכצעקת\"ה כו' כי עיני ה' משוטטו'<sup data-n=\"296\">31</sup> בכל הארץ כידוע ומבואר במ\"א וע\"ד פרט ג\"כ אמרו דע מה מלמעלה<sup data-n=\"297\">32</sup> ממך עין רואה ואזן שומעת כו' וכמ\"ש במ\"א וד\"ל ומאחר שע\"י בחי' כח הראי' רואה ומשגיח בכל ההשתלשלו' וע\"י בחי' כח השמיעה שומע וכמ\"ש ויקשב ה' וישמע<sup data-n=\"298\">33</sup> כו' א\"כ הרי בחי' כחות הללו הם בחי' אלקו' ממש אלא שאינם רק כחו' מסתעפי' מעצמו' השלימו' דמאציל עצמו אבל מ\"מ כחו' אלקים הם ובאמת פי' אלקו' אין זה שסוברי' העולם שהוא בחי' אלוה עצמו אלא הוא ענין כח אלקי מסתעף מו העצמות (ובל\"א געטליך) והוא מפני שהוא רק כח מסתעף ונק' חכמה של המאציל או כח הראי' שלו וכיוצא בזה שהוא הבחי' שלו ומ\"מ הוא בחי' אלקו' ממש<sup data-n=\"e4\">*</sup> משום דאיהו",[["293","28","<b>במקום גדולתו</b>: ראה מגילה לא, א. סה\"מ ה'ש\"ת ע' 40 הערת כ\"ק אדמו\"ר זי\"ע. ובלקוטי הגהות לתניא פ\"ד (ע' יב)."],["294","29","<b>משמים הביט ה'</b>: תהלים לג, יג."],["295","30","<b>ארדה נא ואראה</b>: וירא יח, כא."],["296","31","<b>עיני ה' משוטטו'</b>: ראה זכרי' ד, י. דברי הימים-ב טז, ט."],["297","32","<b>דע מה מלמעלה</b>: אבות פ\"ב מ\"א."],["298","33","<b>ויקשב ה' וישמע</b>: מלאכי ג, טז."],["e4","*","<b>ממש</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: והמשל בזה הוא מכחות הנפש ראי' ושמיעה ואפי' שכל ומדות כי נת\"ל שהן ג\"כ אינן עצמיו' הנפש ממש רק שהן בחי' כלים שעל ידם פועלת הנפש ע\"י השכל משכלת כו' (ומ\"ש בלק\"א שעשר בחי' הנפש הן עצמיותה היינו לגבי מו\"ד שהמו\"ד הן נפרדי' מבחי' לבושים, משא\"כ השכל ומדות הן כחות הנפש והתפשטות') ונק' בל\"א מענשלי\"ך אבל לא שהן הנפש עצמ'. ועד\"ז הי\"ס הן הארת והתפשטו' הא\"ס ולא מהו\"ע ממש ולכן נק' אלקות פי' געטליק כו' כי מ\"מ הוא ית' מיוחד בהן בתכלית: משום דאיהו."]]],[2100490108,"וחיוהי וגרמוה\"י חד כו' וזהו שאמר אנ\"ת דאפיק' כלומר אתה שהוצאתם להיו' כחו' נבדלי' מעצמותך אבל מ\"מ עדיין מיוחדי' במאציל ולכך אנת דמייחד לון ומקשר לון כו' מטעם הנ\"ל וד\"ל. לאנהגא בהון עלמין סתימין כו', הנה מבואר בזוהר בכמה דוכתי שיש רבוא רבבו' עלמין סתימין באצי' ולמעלה מן האצי' וכמו בפי' ד' מאו' שקל כסף<sup data-n=\"299\">34</sup> שהן ת' עלמין דכסופין<sup data-n=\"300\">35</sup> אמר שמתחלק לד' מאו' אלף<sup data-n=\"301\">36</sup> עלמין כו' ובתליסר נימין<sup data-n=\"302\">37</sup> אמר שמתחלק לתליסר אלף עלמין וכיוצא ויש להבין לכאורה מהיכן יהי' ריבוי ההתחלקו' כזאת, אך הענין יובן ע\"ד דוגמא ממה שאנו רואין כאן באדם התחתון בכח החכמה שיש בו שיוכל להתחכם בכמה חכמו' שונות ובכל חכמה יש כמה שכליים פרטיים ובכל שכל יש כמה מחשבו' פרטיו' ובכל מחשבה יש כמה דמיונו' פרטיי' ובכל דמיון ג\"כ יש כמה מדרגו' שונות יש שידמה בחי' דומם במחשבה ויש שנדמה בחי' צומח כו' וגם בדמיון במהו' דבר א' אם צומח או דומם יש באופן הדמיון כמה מדרגו' שונות לפעמי' כך ולפעמי' כך כו' הרי אנו רואי' בחוש שבכח חכמה א' שנמצאת באדם יסתעפו ריבוי ההתחלקו' למדרגו' שונו' כ\"כ ממש עד אין קץ ושיעור כנ\"ל ומכ\"ש וק\"ו כו' למעלה הגם שבאמת אין המשל דומה לנמשל שלמעלה יוכל להיות התחלקו' רבוא רבבו' פעמי' יותר מזה מ\"מ אפס קצהו נוכל להבין שיוכל למצוא מציא' ריבוי התחלקו' ת' אלף עלמין או תליסר אלף עלמין רק מכח ואור ספי' א' מן הספירו' שבאצי' או למעלה מן האצי' והוא אשר קוראם בשם נימי\"ן וכיוצא ע\"ש כח ההמשכה הפרטי' המסתעפת מהכללי' וכנ\"ל במשל וד\"ל. וזהו פי' לאנהגא בהון עלמין סתימין שר\"ל עולמו' עד אין שיעור כנ\"ל מפני שנמשכו' מי' ספיראן עד אין קץ ושיעור מטעם הנ\"ל וד\"ל.\n<b>ואלין</b> י' ספיראן כו' עד חד אריך חד קציר וחד בינוני. הנה פי' חד אריך הוא מדת החסד שאור שפעו מתפשט בא למטה עד אין שיעור כי מצד טבע החסד יאיר אור הטוב והחסד גם לשאינו ראוי ואינו צריך כמו גמילו' חסדי' שהוא בין לעניי' בין לעשירי'<sup data-n=\"303\">38</sup> כידוע ומדת הגבורה הוא הקצר להיותו בחי' דוקא הדין והמשפט אם הוא ראוי לחסד וכו' כידוע ומדת הת\"ת הוא הרחמי' שכלול משניהם חו\"ג כי הרחמנו' היא אחרי מדת הדין והגבורו' מ\"מ יאמר שראוי לחסד מצד הרחמי' דמ\"מ יש רחמנו' עליו כו' כידוע והוא מדת הצדק\"ה שאינה אלא לעניי' מצד הרחמי' ולא לעשירי' משא\"כ גמ\"ח כנ\"ל והוא מה שאמר וחד בינונ\"י שהוא מדת הרחמי' שאין שפעו כמו החסד בבלתי הגבלה כלל וגם אינו מצומצם מאד כמדת הגבורה כנ\"ל אלא הוא בחי' בינוני מטעם הנ\"ל וד\"ל. והנה ג' מדו' הללו הן בכלל בכל הי\"ס וגם בפרט בכל ספי' ובכל מקום עיקר גילוי אור א\"ס הוא במדת הבינונ\"י והוא מדת הת\"ת מפני שכולל הכל והוא בחי' שלימו' כידוע בפי' ישראל<sup data-n=\"304\">39</sup> אשר בך",[["299","34","<b>ד' מאו' שקל כסף</b>: חיי שרה כג, טו."],["300","35","<b>ת' עלמין דכסופין</b>: ראה זח\"ג רפח, א. קכח, ב."],["301","36","<b>לד' מאו' אלף</b>: זח\"ג קכח, ב."],["302","37","<b>ובתליסר נימין</b>: זח\"ג קכט, א."],["303","38","<b>גמילו' חסדי' שהוא בין. . לעשירי'</b>: סוכה מט, ב."],["304","39","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג. סידור מב, סע\"ג."]]],[2100490109,"אתפא\"ר שהוא בחי' ת\"ת שכלול מכל הגווני\"ן אדו\"ם ולבן כו' במדה נכונה ע\"כ הוא בבחי' השלימו' כו' וד\"ל.\n<b>ובכל</b> זה מובן מ\"ש ארדה נא ואראה הכצעקתה הבאה אלי עשו כו', דלכאורה אינו מובן ספיקו' זאת אם כצעקתה הבאה כו' ומי איכא ספיקא<sup data-n=\"305\">40</sup> קמי' שמיא כו'. אך הענין הוא כידוע דיש בחי' אור ישר שמצד מדת החסד הנ\"ל ובחי' אור חוזר שהוא מצד בחי' הגבורו' וההסתלקו' והוא מדת הדין והצמצום כנ\"ל והם ב' הפכי' שזה מתפשט בלי שיעור וזה מתצמצם בלי שיעור כנ\"ל ותמיד המה מנגדיים גדולי' ולהיות כי בהכרח שיהי' רק כפי א' משניהם והיינו לפעמים כמו מדה\"ד ולפעמים כמו מדת החסד ואין א' מושל בשל מנגדו כלל כי אין החסד מצוי כלל בשעת הדין ואין הדין מצוי כלל בשעת החסדי' כנראה בחוש אצל אדם התחתון אך זהו דוקא כשנשלמה מדתו של א' מהם כמו שהיא המדה בשלימותה אם לחסד או לדין אזי או כולו חסד או כולו דין כו' אך כשלא נשלמה המדה על שלימותה שאז יש כח למדה המנגדת לשלוט ג\"כ ולהפוך מן הקצה כו' לזאת צריך שירד אור השכל ממקורו לעיין ולפקח בזה ואם לא נשלמה מדה\"ד ע\"י שלימותה עד\"מ יעשה פשר דבר ביניהם דהיינו שישפוט במדת הבינוני והוא מדה\"ר כנ\"ל שהוא לא כמדה\"ד ולא כמדת החסד אלא בחי' הכרעה אבל היא נטיי' לחסד יותר מן הדין מצד הרחמים כנ\"ל וד\"ל. וזהו ארדה נא ואראה פי' ממקור החכ' ירד לראותה ולעיין למטה בהעלא' מעשה התחתוני' הכצעקתה הבאה אלי עשו פי' אם נשלם מדה\"ד ע\"י צעקתם הרעה שהעלו למעלה לעורר ממדת הצמצום כו' עד שנעשו למדה\"ד למעלה בשלימותו ואז כלה ואין לרחמים בזה חלק כלל ואם עדיין לא עשוהו בשלימותו במעשיהם אזי אדעה במדה\"ר שבאה ע\"י הדעת דוקא כידוע שדת\"י הוא הכל קו א' האמצעי והוא במדת בינוני הנ\"ל וזהו אדעה להמתיק גבורות דמדה\"ד בדעת דהיינו ברחמים כנ\"ל וד\"ל<sup data-n=\"e5\">*</sup>.\n&lt;כט&gt;",[["305","40","<b>ומי איכא ספיקא</b>: ברכות ג, ב."],["e5","*","<b>וד\"ל</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: ועיקר הפי' בזה כך הוא ארדה נא בבחי' אור ישר שיורד מלמלעה למעלה שהוא מבחי' החסדים ואראה שהראי' היא מבחי' חכמה שהוא מקור החסדים, ור\"ל שיראה ענין מעשה סדום עפ\"י החסד דאו\"י הכצעקת' הבא' אלי עשו פי' הבא' אלי ממטה למעלה שהוא מדת אור חוזר ובחי' גבורות שעפ'י מדת הגבו' כבר נפסק הדין עליהם לעשות בהם כלי' כי גדל עונם וזוהי החסד שעשה עמהם שירד לראות מעשיהם עפ\"י מדת החסד דאו\"י ואם גם עפ\"י מדה זו לא ימצא להם זכות לפי שהוא כמו הכצעקתה הבאה ממטה למעלה בשוה ממש אזי כלה ואם לאו שעפ\"י החסד ימצא זכות ואזי ואדעה כנ\"ל."]]],[2100490110,"<h3>נוסח שני: פתח ואמר אנת הוא חד</h3>\n<b></b><b>בעזרה\"י וית', ביום השבת ק' פ' וירא (שנת תקסואו לפ\"ק)</b>\n<b>פתח</b><sup data-n=\"306\">1</sup> ואמר אנת* הוא חד<sup data-n=\"307\">*1</sup> ולא בחושבן אנת הוא דאפיקת עשר תיקונין וקרינן לון עשר ספירן כו' יע\"ש.\n<b>הנה</b> מבשרי אחזה אלוה<sup data-n=\"308\">2</sup> דכמו עד\"מ בנפש האדם שלמטה שנמצאי' בה עשר כחות משונות וחלוקות זמ\"ז והם עשר בחי' שבנפש שנחלקים דרך כלל לב' חלקים כוללים והם שכל ומדות שהשכל כולל ג' בחי' חב\"ד והמדות נחלקים לז' חלקים כו' וג' לבושיה הם בחי' מחשבה דבור ומעשה שהמחשבה הוא לבוש הפנימיי והדבור לבוש החיצון כו' כמ\"ש בלק\"א<sup data-n=\"309\">3</sup> ע\"ש.\n<b>אך</b> עשר בחי' הנפש מכונים בלק\"א בשם מהותו ועצמותו של הנפש, הנה באמת לגבי הלבושים הנפרדים דמדו\"מ מתוארי' ומתייחסי' למהותו ועצמותו של הנפש מצד היחוד וההתחברות שלהן עם עצמו' הנפש בתכלית היחוד עד שלא יתוארו מצד זה בשם לבוש נפרד כמו ג' לבושיה הנ\"ל אבל באמת לגבי עצמות הנפש אף הם נחשבי' ומתוארי' לכלי' ולבושי' שלה שאינם הם בעצמם בחי' מהות ועצמו' הנפש כ\"א כחותי' וענפיה המסתעפי' הימנה כי עצמו' הנפש מושללת מגדר ההתחלקות שלא יתכן שהיא בעצמה מחולקת לעשר בחי' שונות כ\"א היא מהות עצם א' פשוט בתכלית הפשיטות בחי' ההיולי וממנה יסתעפו עשר כחות שונות ההם עד שהם נחשבים לגבי עצמותה ג\"כ לבחי' כלי' ולבושי' רק שמשונים הם מלבושים הנפרדים דמדו\"מ שהם לבושים המחוברי' עם עצמו' הנפש ומיוחדת עמה בתכלית היחוד כמשי\"ת אבל אינם בחי' מהותה ועצמותה ממש כנראה בעליל שימצא בעשר כחותיה בחי' שינויים והתפעלות משינויי הזמן שיש בהן בחי' קטנות וגדלות שכאשר הוא רך בשנים אזי השכל שלו בקטנות וכן המדות וכשהוא זקן מאד אזי דעתו מתיישבת עליו בבחי' מוחין דגדלות, כענין מארז\"ל כל<sup data-n=\"310\">4</sup> &lt;ל&gt;\nמה שמזקינין דעתן מתיישבת עליהן ואם השכל והמדות עצמן הם הם מהותה ועצמותה של הנפש איך יתכן בהם שינויי' אלו ברבוי ומיעוט דקטנות וגדלות עד שימצא בהם המאורעות האלו שיתפעלו משינויי הזמן דכשיזקין יתוסף בו רוח בינה יתירה שיהי' דעתו מתיישבת עליו וקודם לכן לא היתה דעתו מתיישבת שהזמן גרמא בזה, שזה פליאה דעת שהרי א\"א להיתוסף בה יותר מכמות שהיא בעצם כמו שנמשכה מלמעלה ולא אפשר להימצא בה התפעלות ושינויי' כאלו ברבוי ומיעוט שכמו שהיא היא לא פחות ולא יותר ומאין יסתעף סבת השנוי בה בתוספת ורבוי מאריכו' ימים ע\"פ האדמה",[["306","1","<b>פתח ואמר אנת הוא חד</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קסב, א). נמצא ג\"כ בכת\"י 207 טו, א. ובסוף המאמר רשום: נכתב י\"ב תמוז שנת תרט\"ו. 1382 עח, ב (וחסר הסיום).\nהנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' לו.\nהנחה אחרת נדפס בתו\"א וירא יג, ג.\nהגהות על נוסח התו\"א נדפס באוה\"ת בראשית כרך ד תשלח, א. [נדפס ג\"כ בביאוה\"ז לכ\"ק הצ\"צ ח\"ב ע' תתרלט]. וראה בהנסמן שם בתו\"א בהמ\"מ."],["307","*1","<b>אנת הוא חד</b>: ראה הקדמת תקו\"ז (יז, א)."],["308","2","<b>מבשרי אחזה אלוה</b>: לשון הפסוק איוב יט, כו."],["309","3","<b>בלק\"א</b>: פ\"ג, פי\"ב."],["310","4","<b>כל מה שמזקינין</b>: ראה סוף קנים."]]],[2100490111,"שיהי' הזמן גרמא בזה הלא כ\"ז הוא מהנמנע בעצמו' הנפש כמ\"ש במ\"א כו', שכ\"ז לא יתכן בעצמו' הנפש זולתי בכחותיה וענפיה המסתעפי' הימנה דהיינו שעשר מדרגות הנ\"ל הם כחותיה המסתעפים ממנה לכך ימצא שינויי' אלו ברבוי ומיעוט לפי אופן ההשפעה של עצמו' הנפש מקורן שכאשר הוא רך בשנים אזי אין מתפשט השפע של השכל ממקורו דעצמו' הנפש ברבוי ותוספת כ\"כ וכשיזקין יהי' דעתו מתישבת בתוך הכלי ע\"י המשכתו בתוספת גילוי מעצמו' הנפש כנ\"ל (וא\"צ להאריך בראיות לזה כי האמת יורה דרכו).\n<b>אך</b> משונים הם הכוחות האלו מג' לבושיה דמדו\"מ מפני שהם נק' לבושי' המחוברי' ומיוחדים עם מהות' ועצמותה הגם שהם ג\"כ כחותיה ולא עצם עצמותה, אעפ\"כ נתחברו ונתייחדו עמה בתכלית היחוד (ולכך נק' בלק\"א על שם העצם שלה בשם מהותה ועצמותה מצד החבור והיחוד שלהן עמה) משא\"כ ג' לבושיה דמדו\"מ שהם לבושים הנפרדים ממש.\n<b>והענין</b> דכמו המלבושים גשמיים שהם נפרדים מן האדם הלובשן שברצותו לובשן וברצותו פושטן, מצד שהם נפרדים ממש ממנו, רק ברצותו מתלבש בהן אבל אין להן קירוב ויחוד אמתי שהם מהו' זר ונפרד ממנו מאחר שיכול להחליף כמה לבושי' להיותו פושט לבוש זה ולובש לבוש אחר כו', משא\"כ הגוף שהנפש מלובשת בתוכו הגם שהוא ג\"כ בחי' לבוש של הנפש שהיא מתלבשת בתוכו שאינו מערך וסוג הנפש הרוחניי, ששוה במזגו שמורכב מד' יסודו' פשוטי' דעשי' למזג הד' יסודות המורכבי' בהמלבוש גשמיי בלי מציאת יתרון בו כלל, אך מעלה יתירה נודעת לנו בלבוש הגוף דאינו מערך לבוש הגשמיי והיינו הגם שהוא לבוש גשמיי מורכב מד' יסודו' גשמיי' אעפ\"כ נתחבר עם הנפש ונתייחד עמה בתכלית היחוד עד שמעורבי' כל כחו' נפשיו' בהגוף והגוף מחובר עמם בתכלית היחוד והיו לאחדים עמה ממש, דכאשר יכאב לו באבר א' מאברי הגוף ירגיש הנפש מכאובו ויצר לה מאד וכדומה לזה תתפעל בהתפעלות הנפש מכל מאורע הגוף, וכן כאשר יחפוץ באיזה פעולה מפעולת אברי הגוף יתפעלו תיכף אברי הגוף בקיום רצונו בלי שיהוי זמן מ\"ה אפי' רגע אחת כגון כשרוצה להלוך למחוז חפצו נשמעים הרגלים תיכף לרצונו לזוז ממקומן לילך וכן הידים נשמעים לרצונו במעשה ומישוש ודומיהן שכ\"ז מצד התפשטו' המחשבה והרצון בכל אברי &lt;לא&gt;\nהגוף דאל\"כ הי' מצטרך להתמהמה זמן מה רגע או חצי רגע עד יעבור השפע של המחשבה מן המוח לאבר פרטיי ההוא כו', ולזאת נק' הגוף לבוש המחובר שמחובר ומיוחד עם הנפש בתכלית היחוד עד שא\"א לה להתפשט ממנו ולהפרד ממנו עד עת פקודתה כו' כמ\"כ ממש הוא ההבדל בין המלבושים הנפרדים של הנפש שהם בחי' מדו\"מ ובין עשר כחותיה שהם מיוחדים במהותה ועצמותה בתכלית היחוד שנקראו לבושי' המחוברי' שאין בהם קיצוץ ופירוד עולמית משא\"כ דמדו\"מ הם לבושים הנפרדים ממש כמ\"ש במ\"א ע\"ש.\n<b>וכך</b> עד\"מ למעלה שאמר אליהו ז\"ל אנת הוא דאפיקת עשר תיקונין כו' שהם עשר ספירות דאצי' שנקראו בשם תיקוני\"ן שהם בחי' לבושי' וכלי' של המאציל ולא"],[2100490112,"מהותו ועצמותו ממש כי מהותו ועצמותו ממש מרומם לבדו ומתנשא מימות עולם פשוט בתכלית הפשיטות מושלל מגדר תוארים אלו כמאמ' אליהו ז\"ל בסוף המאמר ולאו ביה מאינון מדות כלל ואין ערוך אליו והם ע\"ס דאצי' הם בחי' הכלי' ולבושי' שלו אך הם מיוחדי' עמו בתכלית היחוד כי אצילו' הוא בחי' אלקות ממש דאיהו וגרמוהי וחיוהי חד כו' לכך נקראו בשם תיקוני\"ן דתרגומו דלא<sup data-n=\"311\">5</sup> ילבש גבר שמלת אשה דלא תתלבש גבר בתיקוני אתתא כו' (שהתרגום של שמלה הוא תיקון) והיינו שתיקוני אתתא הם תכשיטיה שהלבושי' התכשיטי' המקשטי' אותו נקראו בשם תיקונין בלשון ארמית והיינו שהתיקוני\"ן הם הלבושי' המחוברי' אל העצם שתועלתן והתיקון שנסתעף מהם שעל ידם תתחבר העצם בזולתו ומבשרי אחזה שעשר ספי' שבנפש נק' בשם תיקונין שלה שהם הכלי' שלה המחוברי' עמה בתכלית היחוד כנ\"ל שיסתעף מהם תועלת ותיקון לעצמות הנפש דהיינו שע\"י הכלי' הללו היא פועלת פעולתה והוא ע\"י התחברותה עמהם דוקא כמו כשחפץ להשכיל איזה השכלה נפלאה ולהתחכם בה אזי א\"א להוציא הדבר מכח אל הפועל זולתי ע\"י כלי השכל שבנפש, שהשכל שבנפש הוא בחי' הכלים שלה שנק' בשם תיקו\"ן שלה דהיינו שעל ידו יהי' תועלת ותיקו\"ן להנפש שתתחבר עם המושכל ההוא שחפץ בו שהכלי של השכל ישכילנו מה דלא סגי בלא\"ה שא\"א להנפש עצמה להוציא הדבר הזה מכח אל הפועל זולתי על ידו (כי עצמות הנפש פשוטה בתכלית הפשיטו' לזאת א\"א לה להתחבר במושכל זולתי בכלי השכל) שמאחר שמיוחדת עם כלי השכל ומלובשי' בו ביחוד וחבור אמתי לזאת פועלת פעולתה עמו להיותה משכלת המושכל ההוא בכלי השכל שלה כנ\"ל וכן המדו\"ת הם התיקוני\"ם של עצמו' הנפש שפועלת פעולתה על ידן דוקא כמו מדת האהבה היא לבוש המחובר לעצמו' הנפש והתיקו\"ן שלה שיצא ממנה תועלת שע\"י האהבה תתחבר הנפש עם הדבר הנחמד והאהוב ההוא שכשמצטרך שיתקרב הדבר ההוא ויהי' מתחבר עם הנפש אזי נפעל זאת ע\"י כלי האהבה שמלובשת בה &lt;לב&gt;\nהנפש ומחוברת עמה בתכלית היחוד להיותה מתאהבה לדבר ההוא שזהו פעולת הנפש שמצטרכה לפעול הקירוב של הדבר ההוא אליה שפועלת זאת ע\"י כלי האהבה המחברין יחד וכן הגבורה היא הכלי לפעולת הריחוק של הנפש להשונא וכדומה לזה מדת הנצח היא הכלי לפעולת הנפש שתפעול הנצוח במלחמה ודומיהן, נמצא כל עשר ספי' של הנפש שהם מיוחדי' עמה בתכלית היחוד הם תיקונין שלה שנתתקנו לצורך פעולתה כנ\"ל וכמו התכשיט של האדם הוא התיקו\"ן שלו כך הם בחי' תיקוניה ותכשיטה שיהי' מהם תועלת ותיקו\"ן להיות הנפש מוציא פעלותיה על ידיהן דוקא (וכמו עד\"מ כלי הראי' שהיא העין הוא התיקו\"ן לאור וכח הראי' שיפעול פעולתה על ידה לראות הנראה כו' ועוד יש תיקון שני לכלי הראי' שהוא כלי ההבטה לראות דבר מרחוק מ\"ה שא\"א להעין בעצמה לראותו שלזאת צריך תיקון שני הוא כלי ההבטה כו' כמ\"ש במ\"א ועד\"ז כל התיקוני\"ן הם הכלי' שנעשה מהם תועלת לחבר הנפש עם הדבר ההוא כו' כנ\"ל וד\"ל).\n<b>וכמ\"כ</b> למעלה ממש שעשר כלים דע\"ס הנאצלי' שמיוחדי' במאצילן ב\"ה בתכלית היחוד דאיהו וגרמוהי חד כנ\"ל אעפ\"י שהם בחי' לבושי' של המאציל ב\"ה",[["311","5","<b>דלא ילבש גבר שמלת אשה</b>: תצא כב, ה."]]],[2100490113,"ולא ממהותו ועצמותו ממש שאין ערוך אליו כלל אעפ\"כ הם מחוברים לעצמותו ית' ומיוחדי' עמו בתכלית היחוד כהתחברות והתקשרות הגוף עם הנפש אף שאינו מערך וסוג הנפש הרוחניי כנ\"ל וכמאמ' אליהו להלן כמה גופין תקינת לון דאתקריאו גופא לגבי לבושי' דמכסי' עליהון כו' דהיינו שלבושי' הנפרדי' הם בחי' מחשבה<sup data-n=\"312\">6</sup> דבור ומעשה שלמעלה שהמה ג' עולמות בי\"ע עולמות הנפרדי' ממש כדכתיב ומשם יפרד<sup data-n=\"313\">7</sup> וגו' לזאת נק' בחי' לבושי\"ן סתם שהם לבושי' הנפרדים כנ\"ל משא\"כ עשר כלי' דע\"ס הנאצלי' שהם לבושי' המחוברי' להעצם עצמותו ית' כהתקשרו' הגוף בנפש, נקרא בשם גופא דוקא כמ\"ש להלן חסד דרועא ימינא גבורה דרועא שמאלא כו' וד\"ל. ולזאת נקראו בשם תיקונין דוקא ולא בשם לבושין דאפשר למטעי לומר שהם הלבושי' הנפרדי' ממש לזאת אמר אליהו ז\"ל אנת הוא דאפיקת עשר תיקונין שהכונה בזה הלשון למעט הלבושין הנפרדי' ממש שלא נקראי' בשם תיקונין כ\"א בשם לבושין, אף בלשון ארמית כמ\"ש להלן לבושי\"ן תקינת להון כו' ותיקונין הם בלשון ארמית לבושי התכשיטי' דוקא והם למעלה לבושי' המחוברי' שהם התיקוני\"ן עליונים כנ\"ל וד\"ל.\n<b>אנ\"ת</b> הוא חכי\"ם ולא בחכמה ידיעא כו', הנה כונתו בזה להודיע לבני האדם גבורתו<sup data-n=\"314\">8</sup> ית' שלא יהי' טועין לומר שהחכמה הזאת הנמצאת בעולמו' בי\"ע שנרגשת בתפיסא והשגה ממש להיקרא בשם חכמה, היא בערך החכמה דאצי' שאף היא מהו' חכמה הנרגשת ממש ונערכת אליה בערך ממש, לזאת קמל\"ן אליהו ז\"ל שהיא חכמה ולא בחכמה ידיע\"א, פי' כלי &lt;לג&gt;\nהחכמה דאצי' שמתלבש בה המאציל ב\"ה להיקרא בשם חכי\"ם, הוא לא בחכמה ידיעא אלינו ולא ממהותה וערכה כלל כ\"א החכמה דאצי' היא מקור החכמה דבי\"ע שממנה יסתעף בחי' מהו' חכמה דבי\"ע עפ\"י רבוי הצמצומים בהשתלשלות רבות ולזאת נקראת בשם חכמה בשם הפעולה שממנה נפעלת מהו' החכמה דבי\"ע אבל היא בעצמה למעלה מערך ומהות החכמה ידיעא זולתי הוא מקור החכמה ידיעא ולזאת מצד פעולתה נק' לגבי המאציל בשם חכמה ג\"כ מאחר שהוא נעשה המקור להחכמה דבי\"ע שיומשך ממנה ברבוי ההשתלשלות כנ\"ל. וזהו אנ\"ת הוא עצמות אין סוף ב\"ה המתלבש בכלי החכמה דאצי' להיות נק' בשם חכי\"ם אבל הוא לא בחכמה ידיע כ\"א הוא המקור החכמה ידיע\"א דבי\"ע כנ\"ל. וה\"ז כמו עד\"מ במיני פירות חמוצים ומתוקים הגשמיים כמו התפוחים המתוקים והחמוצי' דכמו שנבדלי' זמ\"ז בטעמן הגשמיי שזה חמוץ וזה מתוק כך נבדלי' הם בשרשן ממקורן שנתהוו ונמשכו כי אין לך עשב<sup data-n=\"315\">9</sup> מלמטה שאין לו מזל מלמעלה שמכה ואמר לו גדל כו' שהתפוחי' המתוקי' מוכרח להיות שנמשכי' ממזל\"ן ששרשו מבחי' המתיקו\"ת שלמעלה כי גבוה מעל גבוה שומר<sup data-n=\"316\">10</sup> ומקבלי' השפע דין מן דין עד",[["312","6","<b>מחשבה. . בי\"ע</b>: ראה בהנסמן במאמרי אדה\"א הנחות תקע\"ז ע' רב. וש\"נ."],["313","7","<b>ומשם יפרד</b>: בראשית ב, י."],["314","8","<b>להודיע לבני האדם גבורתו</b>: ע\"ד לשון הפסוק — תהלים קמה, יב."],["315","9","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. השמטות לזח\"א רנא, א. זהר תרומה קעא, ב. קדושים פו, א. מורה נבוכים ח\"ב, פ\"י."],["316","10","<b>כי גבוה מעל גבוה שומר</b>: קהלת ה, ז."]]],[2100490114,"ששרש שרשם הם בחי' החסדי' שלמעלה שמהם יסתעפו בחי' המתיקות בתפוחים, והתפוחי' החמוצי' יש להם מזל אחר ששרשו ממקור אחר מבחי' הגבורו' עליונו' עד שלא אפשר למז\"ל זה לגדל המין ההפכי ממנו שלעולם לא ימשכו התפוחים מתוקי' מהמז\"ל ששרשו מהגבורו' עליונו' וכן להיפך, כ\"א זיני' בתר זיני' אזלא שהמזל ששרשו מבחי' החסדי' יוגדלו התפוחי' המתוקי' כו' וכן להיפך, אבל אין סברא לומר שזה הטעם מתיקות הגשמיי הנרגש בתפוחים הגשמי' הוא נמצא במקורן הכוכב והמזל שלהן, שיהי' הכוכב שלהן מתוק כו' כ\"א הכוכב הוא מקור המתיקות הגשמיי שבתפוח הגשמי מאחר שהוא נפעל ממנו אבל מציאות המתיקו' שבכוכב הוא רוחניי באופן אחר ממש לא מיניה ולא מערכו כלל וכמו המתיקות הנמצאת בשכל שכשישכיל האדם איזה השכלה חדשה שימצא המצאה חדשה באיזה חכמה בתחלת נביעו' המושכל המחודש ההוא פתאום בשכלו יתפעל בשעשועים ותענוג גדול ממתיקות וערבות המושכל ההוא שזה המתיקות והערבות שבמושכל הוא רוחניי ולא מערך המהות המתיקות הגשמיי שבתפוח שערב לחיך גשמיי הטועם וזה יערב לחי\"ך רוחניי בחי' כח השכלי שלו שטועם טעם מתיקות החכמה כו' אך אעפ\"כ נק' כולם בשם דבר כוללי אחד שם מתיקות, רק זה מתיקות רוחניי מטעם רוחניי וזה מתיקות גשמיי מטעם גשמיי אף שרחוקים זמ\"ז במעלה ומדרגה, וכן במדות ימצא בחי' המתיקות והערבות משמיעת הנגונים מכלי שיר שערב להשומע מאד בהרגשת טעם מתיקות בהניגון המופלא ההוא שיתפעל לבבו ממנו בשמחה ותענוג שזהו המתיקות שבמדו' שהוא ג\"כ רוחניי ואינו ממהות המתיקו' גשמיי שבטעמים גשמים, רק כולם נערכים בערך אחד עפ\"י רבוי ההשתלשלות שממתיקות הרוחניי יסתעף ברבוי ההשתלשלות בחי' המתיקות הגשמי שבטעמי' גשמיי' ששם הכוללי של כולם הוא מתיקו\"ת כנ\"ל כך המתיקות שבמזל המגדל &lt;לד&gt;\nתפוחים מתוקים הוא רוחניי וממנו יסתעף המתיקו\"ת הגשמיי שבתפוחי' גשמיי' כו' וד\"ל.\n<b>כך</b> עד\"מ למעלה ממש, בבחי' מהות החכמה דאצי' שמתוארת בשם הכוללי של החכמה הנמצאת בבי\"ע אבל באמת היא לא מערכם ומהו' כלל, כ\"א היא מקורן שממנה יסתעפו מהו' החכמות דבי\"ע שמאחר שממנה יסתעפו ברבוי ההשתלשלות והצמצומי' רבים (שמתגשם השפע ע\"י רבוי הצמצומים להשתנו' למהו' אחר ממש כנודע) והיא מקורן, לכך מתוארת ג\"כ בשם התואר להיקרא בשם חכמה אבל באמת היא לא ממהותם וערכם כלל וז\"ש אליהו אנ\"ת חכי\"ם ולא בחכמה ידיעא כנ\"ל וד\"ל. והנה כמו שהחכמה דאצי' היא לא ידיע\"א כך כל הע\"ס דאצי' הם אינם ידועים בערך הע\"ס דבי\"ע שאף המדות דאצי' אינם ידועים בערך המדו' הידועי' דבי\"ע כמו מציאת מדת הרחמים שלמטה שמורגשי' אצלינו דכאשר יראה האדם את חבירו מדוכא ביסורין או שמכין אותו מכת אכזרי אזי יכמרו רחמיו עליו ויחם לבבו בהתפעלות הנפש עד שירע לבבו מאד מזה שלא יתכן כלל במדת הרחמים דאצי' דאיהו וגרמוהי חד<sup data-n=\"317\">11</sup> וכתיב אני הוי' לא שניתי<sup data-n=\"318\">12</sup> שלא ימצא בו בחי' השינויים והתפעלות ח\"ו כלל ורחמנות זאת המורגשת אצלינו הוא בחי' התפעלות ונעשה",[["317","11","<b>דאיהו וגרמוהי חד</b>: תקו\"ז בהקדמה ג, ב."],["318","12","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."]]],[2100490115,"שינוי בנפש האדם שירע לבבו כו', אך באמת אף המדו\"ת דאצי' לא ידועי\"ם בערך המדות דבי\"ע המסתעף מהם לא מערכם ומהותם כלל זולתי הם מקורן בלבד שלאחר רבוי הצמצומי' בריבוי ההשתלשלות ומסכי\"ם רבים המה הפרסות המבדילות בין עולם לעולם כו' יסתעפו המדו' הידועי' ומורגשי' ממש, וה\"ז כמשל המתיקות שבכוכב המגדל תפוחי' מתוקי' שאינו בדמיון המתיקות גשמיי כו' כו' כנ\"ל. ולכך לא פירש אליהו ז\"ל בפירוש שאף המדו' אינן ידועו', מאחר שאמר חכים ולא בחכמה ידיע\"א מבין ולא בבינה ידיע\"א ממילא יובן בפשיטו' שאף המדו' אין ידועי\"ם ולא חש לפרשן וד\"ל.\n<b>וזהו</b> לשון אצילו\"ת, מלשון ויאצ\"ל<sup data-n=\"319\">13</sup> מרוחו אשר עליו ויתן על ע' איש הזקני' וגו', שהוא לשון<sup data-n=\"320\">14</sup> הפרש\"ה שהפריש מרוחו של משה ויתן על הזקני' כו' מפני שמשה רבע\"ה טען האנכי הריתי את כל העם הזה<sup data-n=\"321\">15</sup> כו' מאי\"ן<sup data-n=\"322\">16</sup> לי בשר לתת לכל העם הזה כי יבכו עלי כו' והיינו מפני שמעלת משה<sup data-n=\"323\">17</sup> רבע\"ה הי' הגבה למעלה מאד נעלה מערכם של ישראל עד שלא היה יכול לשמוע טענת הבשר שהי' הגבה למעלה משרש הבש\"ר כמ\"ש במ\"א ולכך אמר מאי\"ן לי בשר כו' ע\"ש. ולזאת השיב לו הקב\"ה אספה לי שבעים איש<sup data-n=\"324\">18</sup> כו' ויאצל מן הרוח אשר עליו ויתן על ע' איש הזקני' ויהי כנוח עליהם הרוח ויתנבאו ולא יספו והיינו שהאצי' הרוח ממשה עליהם גרם להם להיות מתנבאי' אך אעפ\"כ הי' למטה מאד מערכו של משה עד שהי' יכולין לשמוע טענת הבשר וכדומה &lt;לה&gt;\nמן העם מצד שלא נאצל רק הארה בעלמא ממשה שאין לה ערך אל מהותו ועצמותו, אך בלעדי זאת הי' משתווים לכל העם ומה יהי' בכך שיהי' יכולי' לשמוע טענת הבשר בלבד, לזאת נאצל הארה בעלמא מרוחו של משה עליהם להיותם נביאי' אבל למטה ממשה להיותם ממוצעי' בינו ובין בני ישראל כנ\"ל. כך עד\"מ למעלה ענין עולם האצילו\"ת <sup data-n=\"325\">19</sup> שהיא ממוצע בין המאציל ב\"ה לעולמו' בי\"ע הנפרדי' לחברו עמהם שנאצל ע\"ס דאצי' ממנו אשר אין להם ערוך אליו כו' ואעפ\"כ מיוחדי' ומחוברי' הם עמו בתכלית היחוד דאיהו וגרמוהי חד שעי\"ז מתחבר המאציל בעולמו' הנפרדי' ולזאת נקר' בשם תיקוני\"ן, כענין ע\"ס שבנפש שהם תיקוני' דילה לחברה בזולתה שכל פעולותיה נפעלי' על ידם כנ\"ל וד\"ל.\n<b>אנת</b> הוא חד ולא בחושבן, כונתו בזה לבאר דלא תימא שאופן התהוות הנאצלי' מן המאציל ב\"ה הוא כאופן התהוות הנפעלי' דבי\"ע מע\"ס הנאצלי' שאעפ\"י שהנפעלי' דעשי' רחוקי' מאד ממעלות הע\"ס דאצילות כנ\"ל וד\"ל אעפ\"כ נערכים",[["319","13","<b>ויאצל מרוחו אשר עליו</b>: בהעלותך יא, כה."],["320","14","<b>לשון הפרשה</b>: ראה פרדס שער (טז) אבי\"ע רפ\"א. תו\"א ג, א. יד, א. סה\"מ תקס\"ז ע' כג. לב. תקס\"ט ע' ריט."],["321","15","<b>האנכי הריתי את כל העם הזה</b>: בהעלותך יא, יב."],["322","16","<b>מאין לי בשר</b>: שם יא, יג."],["323","17","<b>משה. . למעלה משרש הבשר</b>: ראה תו\"א יד, א. לקו\"ת במדבר יז, ד. בהעלותך לא, ד. לג, ב. ואתחנן יב, א."],["324","18","<b>אספה לי שבעים איש</b>: בהעלותך יא, טז."],["325","19","<b>האצילות שהיא ממוצע</b>: ראה ע\"ח שמ\"א פ\"ד."]]],[2100490116,"אליהם בערך ויחס עפ\"י רבוי ההשתלשלות שמסתעפי' מהם כנ\"ל. אבל אנת הוא חד ולא בחושבן ומנין הע\"ס דאצי' כ\"א מרומם לבדו בבחי' אין ערוך כו' שאין להע\"ס הנאצלי' ערך ויחס כלל אל המאציל ית' יותר מערך הדומם דעשי' לגבי חכמה דאצי' שיש לו ערך עפ\"י רבוי ההשתלשלות שנסתעף ממנה רק שרחוק מאד ממנה אבל ע\"ס הנאצלי' לגבי עצמו' המאצי' אין להם ערך ויחס כלל שישתוו בבחי' חשיבו' הביטול כמדרגה התחתונה שבכל ההשתלשלות הוא הדומם דעשי' שאין להם יתרון וחשיבות עליו נגדו כלל דקמיה כחשיכה כאורה כו' השוה ומשוה קטן וגדול בערך הביטול דכלא קמיה כלא חשיב בשוה כנ\"ל ולזאת המשכת ע\"ס הנאצלי' מהמאציל ב\"ה הי' בלתי אפשר להתמשך עפ\"י סדר והדרגות ההשתלשלות כאופן המשכת ע\"ס דעשי' מהנאצלי' ברבוי הצמצומים של סדרי ההשתלשלות מפני שע\"ס דעשי' נערכי' אליהם ומתיחסיי' אליהם עפ\"י ההשתלשלות כנ\"ל משא\"כ ע\"ס הנאצלי' שאין להם ערך ויחס כלל כנ\"ל.\n<b>אך</b> הענין שבאמת בלתי אפשר היה להמשכת ע\"ס הנאצלי' מהמאציל ב\"ה זולתי הצמצום שהי' באור אין סוף ב\"ה כמ\"ש בע\"ח<sup data-n=\"326\">20</sup> שתחלה היה האור מלא כו' ואח\"כ נתצמצם האור להיות נעשה חלל ומקום פנוי כו' ואח\"כ נמשך קו וחוט דק מאור א\"ס כו' ע\"ש שזה הצימצום הגדול גרם לסבת יכולת המשכת ע\"ס הנאצלי' מן המאציל ב\"ה מצד שצמצום גדול ועצום כזאת לא הי' בכל סדרי ההשתלשלות דבי\"ע כמשי\"ת בע\"ה לקמן.\nאך תחלה נבאר מלת או\"ר אין סוף.\n<b>הנה</b> כתיב ויעש<sup data-n=\"327\">21</sup> גו' לשני המאורו' הגדולי' כו' וכתיב ויקרא [אלקים] לאור יום כו' שמאור הוא בלה\"ק עצמות הדבר מקור האו\"ר המתפשט הימנו דהיינו &lt;לו&gt;\nגלגל העצמי של השמש וירח נק' מאורו\"ת שהם מקור העצמי של האור המתפשט מהם ואור נק' הזיו המתפשט על הארץ ולדרים ממאור השמש וזהו ויקרא לאור יום<sup data-n=\"328\">22</sup> שמה שביום יאיר האור והזיו השמש נק' בשם או\"ר שהוא ההתפשטות והגילוי שלה שמתגלה הארת עצמו' המאור ההיולי כו', וכן מבשרי אחזה בנפש האדם שהוא בעצם היולי בחי' המאור העצמיי והאור הוא החיות והזיו המתפשט ממנה דהיינו כשמתלבש בהגוף יחי' הגוף ממנה, שהכח והחיו\"ת המתפשט ממנה להחיות הגוף אף טרם בואה לגוף שהי' עדיין בהעלם ובכח בלבד נק' בשם אור שהוא כח ההתפשטו' שלה שיש בה בכח להחיות הגוף כשתתלבש בו (אבל אין זה כח החיוני בחי' מהותה ועצמותה כי הרי יכולה להחיות כמה גופי\"ם ע\"י הגלגולי' שהיא נצחי כו') נק' אור וזיו שלה וכן כח הראיי' המתפשט מהשכל להתלבש בכלי העין לראות הנראה שהכח הזה הוא האו\"ר המתפשט מן השכל והשכל עצמו הוא המאור העצמי כו' וזהו הכלל",[["326","20","<b>כמ\"ש בע\"ח</b>: ראה ע\"ח שער (א) דרוש עגולים ויושר ענף ב. וראה מאמרי אדה\"א קונטרסים ע' קצט ואילך. ע' תכג ואילך."],["327","21","<b>ויעש גו' לשני המאורות הגדולי'</b>: בראשית א, טז."],["328","22","<b>ויקרא [אלקים] לאור יום</b>: בראשית א, ה."]]],[2100490117,"שאור נק' הגילוי וההתפשטות של עצמות ההיולי, וההיולי הוא המאור העצמי כנ\"ל (ולזאת נז' בלק\"א אור וזיו וחיות לפעמי' כוללם הכל יחד ולפעמי' שניהם אור וחיות כו' לרמז בזה שהכל אחד ולקרב אל השכל ענין או\"ר וד\"ל).\n<b>כך</b> עד\"מ למעלה ממש שעצמות המאציל ב\"ה המרומם לבדו וא\"א להתמשך ממנו כלל ולא יתכן בו בחי' הצמצום וההתפשטות כי אני הוי' לא שנית\"י כתיב בין קודם האצי' ובין לאח\"כ בשוה כנודע וזהו נק' בחי' עצמו' המאו\"ר שהוא מהותו ועצמותו ית', רק או\"ר אין סוף ב\"ה הוא בחי' הזיו וההתפשטו' ממנו ית' שהוא מקור החיים של כל ההשתלשלות כולן וכביטול זיו השמש במאור השמש כך ביטול האור א\"ס במאור עצמותו ית' כדכתי' כי עמך מקור חיים<sup data-n=\"329\">23</sup> וגו' כנודע, אך מאור א\"ס ב\"ה בלתי אפשר הי' להתמשך סדרי ההשתלשלות זולתי ע\"י הצמצומים שהי' בו, שנעשה חלל ומקום פנוי ונמשך רק קו א' דק כו' כמ\"ש בע\"ח.\n<b>והנה</b> ענין החלל כו' הוא בהיות בע\"ח הלביש הכל במשלי' גשמי' שאור הוא גשמיי לזאת מוכרח לתאר החלל בשם חלל ומקום פנוי מאור שאינו מאיר שם כו' אבל באמת כמו שבארנו ענין אור לזאת גם החלל הוא באופן אחר ממש והיינו שלא כדמיון העולם שנעשה חלל ומקום פנוי ממנו ית' הלא לית אתר פנוי מיני'<sup data-n=\"330\">23</sup> כלל אך זהו ההלבשה בגשמיות כנ\"ל ובאמת הענין הוא שהחלל ומקום פנוי הוא שמופנה ורקני מגילוי אור אין סוף שנכלל במאור הנעלם דלית מחשבה תפיסא בי' כלל ולזאת יקרא בשם חלל ומקום פנוי מצד העדר האור והגילוי כו' אבל בבחי' המאור הנעלם ממילא אף החלל דלית אתר פנוי מיני' כו'.\n&lt;לז&gt;\n<b>וביאור</b> הענין הנה מבשרי אחזה כמו עד\"מ בנפש האדם שכח הראיה מתפשט מהשכל שבנפש להתלבש בכלי העין ולפעול פעולתה בה לראות הנראה כו' וכשהסתם העין או סימא עינו נעדר האור פי' הגילוי של כח הראי' שאין מתגלה בכלי העין לפעול פעולתה מצד קילקול הכלי אבל ישנו שם במציאותו בשלימות בתוך הכלי עין כמקודם ממש בלי שינוי שאין השינוי רק לגבי הכלי, שתחלה האיר הארתו בה ועתה נעדר אורו אבל לגבי האו\"ר אין שינוי כלל, שכאשר הי' קודם שם הוא עתה ואף פישוט וכיווץ לא יתכן בו לומר שעתה לאחר קלקול הכלי נתכווץ ונסתלק לחזור מכלי הראי' למקורו עצמו' השכל, כ\"א ישנו פה בהכלי רק שנעדר אור\"ו פי' גילויו בהכלי כנ\"ל. כך עד\"מ למעלה ענין הצמצום שהיה באור א\"ס ב\"ה שבאמת אין שינוי והתפעלות כלל לגבי האור אין סוף ב\"ה בין קודם הצימצום ובין לאח\"כ כי אני הוי' לא שניתי כתיב זולתי השינוי הוא אל המקבלים, שקודם הצמצום הי' האור מלא כו' שהי' ממלא אף מקום החלל בבחי' הגילוי של השפע שלו אך המאציל ב\"ה ראה שלא יוכל להתקיים מזה המשכות סדרי ההשתלשלו' מרוב אורו ית' שלא יכילנו אותו כלל, וא\"א להתהוות ממנו אף הנאצלי' מצד שהם תוארי' מהות דבר מה מהו' חכמה ומהות חסד כו' ואור א\"ס פשוט בתכלית הפשיטות עד שאין",[["329","23","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["330","23","<b>לית אתר פנוי מיני'</b>: ת\"ז תנ\"ז (צא, ב). ת\"ע (קכב, ב). וראה לקו\"ת ויקרא הוספות נב, ג."]]],[2100490118,"להם ערך אליו כלל כנ\"ל, לזאת הי' הצמצום באור א\"ס ב\"ה להיות נעשה חלל ומקום פנוי ריקני מגילוי אור א\"ס ב\"ה שנעדר האו\"ר והגילו\"י משם כ\"א נכלל האו\"ר ההוא שהי' ממולא בתוך החלל בעצמו' המאציל המאור הנעלם כו' אבל במאור הנעלם ממולא אף החלל דלית אתר פנוי מיני' ולא נק' חלל ומקום פנוי רק לגבי הגילוי של האו\"ר שנעדר ממנו כנ\"ל.\n<b>והמשל</b> בזה כמו הרב המשפיע השכל הנפלא לתלמידו ובאמצע ההשפעה בעת שמשפיע לו ומרחיב לו הדבור עלה ברצונו של הרב להעדיר השפע, ונמנע מלהשפיע לו שלגבי הרב אין שינוי בין קודם ההעדר ובין לאח\"כ זולתי לגבי התלמיד הוא השינוי וד\"ל. כך עד\"מ למעלה ענין הצמצום באור א\"ס שתחלה הי' ממלא אף החלל ואח\"כ נעדר אורו וגילוי' להיותו נכלל במאור הנעלם שלא יתכן בזה אף בחי' כיווץ והסתלקות וכנ\"ל במשל בכח הראי' הנעלם בתוך כלי העין שנסתמא כו' כי המאור הנעלם נעדר האור הוא הגילוי שלו אבל ישנו פה בהחלל כמקודם רק החלל פנוי ורקני מגילויי בלבד כנ\"ל.\n<b>אך</b> המשל אינו דומה לנמשל שהנמשל הוא הצמצום בעצמותו בינו לבין עצמו ית' שאף הגילוי והעדרו שניהם הם במהותו ועצמותו ית' משא\"כ במשל בהרב המשפיע לתלמידו לזולתו שהגילוי והעדרו שניהם בזולתו כנ\"ל. אך המשל האמתי הדומה לנמשל הוא כשמייגע הרב בעצמו שכלו בעיון רב בשכל הנפלא ההוא שאז מתגלה שכלו מעצמו' כח חכמתו הנעלם להשכיל המושכל ההוא וכשמעדיר שפע הגילוי של השכל כגון שאינו חפץ להתייגע &lt;לח&gt;\nבלימוד ההוא כ\"א לישב במנוחה והשקט בלי שום מחשבה ושכל כלל שאז נעדר אור השכלי שלו להתעלם בעצמו' המאור הוא כח חכמתו הנעלמה כח המשכיל שלו שהגילוי והעדרו הוא מיני' ובי' בינו לבין עצמו ובעצמותו אין שינוי בין הגילוי להעדרו שבכח עצמו' חכמתו הנעלמה אין שינוי בין קודם הלימוד ובין לאח\"כ ובין כשחזר ונח מן הלימוד שהכח המשכיל שוה בלי שינוי שיש בכחו ללמוד הרבה ולהמציא המצאות חדשות הרבה כנ\"ל, רק השינוי הוא בכלי המוח שהגילו\"י של השכל בהחכמה ההיא שורה בכלי המוח בבחי' גילוי משא\"כ כשנעדר אורו וד\"ל, ומזה תבין למעלה הטיב ענין הצמצום שהי' באור א\"ס ב\"ה שנעשה חלל ומקום פנוי רקני מגילוי אור א\"ס שנעדר אורו ממנו ונכלל במאור הנעלם שנמצא אף בהחלל דלית אתר פנוי מיני' כנ\"ל ואח\"כ נמשך קו א' דק והוא שרש כל ההשתלשלות והיינו כמו בהרב כשמעדיר השפע אזי אח\"כ מצמצם שכלו בצמצום גדול ועצום להיות נמשך מעט מזעיר ממנו בהתגלות כלי המוח שלו, או לתלמידו כו' וכך למעלה הקו וחוט הנמשך לאחר הצמצום מאור א\"ס ב\"ה שהוא בחי' תחתונה שבו בחי' מלכות שבמלכות דא\"ס ב\"ה שהוא נעשה מקור לכל ההשתלשלות ואף גם זאת ע\"י צמצומים רבים עוד, עד שנתהווה עולם העקודי' שהי' האורו' עקודי' בכלי אחד, שלא הי' עדיין בחי' כלים ובנקודי' הי' רק בחי' נקודי' בלבד כנודע זולתי מהאורות היוצאים מאח\"פ (היוצאים דייקא שהוא הארה בעלמא כו') נתהוו בחי' הכלי' דע\"ס הנאצלי' להיותו נק' חכים ולא בחכמה ידיעא מבין ולא בבינה ידיעא שהוא מהו' דבר מ\"ה מהו' חכמה מהות בינה כו' כנ\"ל וד\"ל."],[2100490119,"<b>והנה</b> בזאת נבדל ומשונה המשכת ע\"ס הנאצלי' מן המאציל ב\"ה מכל המשכות סדרי ההשתלשלות כולן דבי\"ע מע\"ס הנאצלי', והיינו בבחי' הצמצום הגדול ועצום של החלל ומקום פנוי כו' מה שאין כמוהו בכל ההשתלשלות מאצי' ועד עשי' והיינו מצד שע\"ס הנאצלי' אין להם ערך כלל אל המאציל, לזאת הוצרך להיות צמצום גדול ועצום כזאת אשר לא נמצא כמוהו עוד בבי\"ע מצד שהם נערכים לאצי' ואין מצטרכים לצמצום גדול ועצום כזאת.\n<b>והגם</b> שיש מיני צמצומי' בבי\"ע הנמשכי' מאצי' דרך סבת הפרסא והמסך הוא הפרגוד המפסיק בינם לבין אצי' וכן מבריאה ליצירה ומיצירה לעשי'. הנה אין להצמצום של הפרסא ערך כלל לצמצום חלל ומקום פנוי לא מיני' ולא מקצתי' כלל, והיינו כי בצמצום הפרסא האור ישנו פה בבחי' גילוי ממש בשלימותו רק שמאיר אורו דרך הפרסא המפסקת בין אצי' לבריאה כדומה שע\"י שעובר האור דרך הפרסא נתעבה ונתגשם ומשתנה לגריעותא, שזהו ענין ההתחדשות מאין לי\"ש, שהוא אור התולדה (כמ\"ש בע\"ח בסוף הספר ע\"ש כמשי\"ת) משא\"כ צמצום החלל שהאור נתעלם במאור הנעלם ומסתלק לגמרי כו'.\n&lt;לט&gt;\n<b>ביאור</b> הענין מבשרי אחזה עד\"מ הרב כשמצטרך להשפיע שכלו הנפלא לתלמידו הקטן שהכלי של התלמיד קטן מהכיל אותו בעצמו כמו שהוא במוחו הרב אזי מלביש שכלו במשל וחידה שמתוך המשל גשמיי יבין התלמיד דקות הנמשל אשר הוא נתלבש בלבוש זר נפרד באותיו' אחרים ממש שהצרופי אותיו' של עצמו' ההשכלה הם אחרי' ממש וצרופי אותיו' של המשל שנתלבש בו הם דברים אחרים ממש ולזאת מאחר שנתלבש הנמשל בצרופי אותיו' אחרי' של המשל, אזי נשתנה לגריעותא לגבי התלמיד המבין ומאזין ומקשיב המשל ומתוכו יכיר הנמשל, להיות אף מה שהבין דבר מתוך דבר הוא הנמשל אצלו בהגשמה יותר ואינו מערך כמו שהי' בשכל הרב טרם התלבשותו בהמשל, והיינו שהעברתו ממוח הרב אל מוח התלמיד דרך לבוש צרופי אותיו' נשתנה לגריעותא להתגשם בהגשמה ממש הגם שהרב לא העלים דבר א' מדבריו כלל שהשפיע כל המושכל בשלימותו זולתי נסתנן וירד שפע הרב אל התלמיד דרך מעביר המשל כו', וזהו למעלה ענין הפרסא (כך שמע ממורו ה\"ה ע\"ה) המבדלת בין אצי' לבריאה בכדי שיוכל להתהוות המחודשי' הנפרדי' שמחודשים מאי\"ן ליש ממש, שזה גורם להם הסתרת המסך המבדיל שאף שכל עצמו' השפע דאצי' מגיע אליהם אך מאחר שעוברת דרך הפרגוד ומסך נתעבה ונתגשמה להשתנות למהות אחר בהגשמה מחודשת ממש אשר לא הי' כך מעולם קודם העברתה דרך פרגוד. וזהו ענין התחדשות הנברא מאי\"ן לי\"ש שעיקר החדוש הוא הי\"ש שמאי\"ן תימצא שלא הי' כמוהו באי\"ן מקורו שעיקר התחדשותו הוא מהעברת האור והשפע דאי\"ן דאצי' דרך פרסא ומסך המבדיל שזה גרם החדוש של הי\"ש שנעשה לאחר העברתה דרך הפרסא מה שלא הי' כן באצי' ולכך נק' זה חדוש גמור וד\"ל וכנ\"ל בהרב המלביש שכלו במשל, שהתחדשו' היש וההגשמה של המושכל נעשה בכלי התלמיד לאחר הבנתו מבין צרופי אותיו' אחרים של המשל, מה שלא הי' ההגשמה זו אף במוח הרב נמצא זהו מחודש אף לגבי הרב וד\"ל, וזהו"],[2100490120,"בחי' אור התולדה שהוא הארה הנולדת מהארה, כענין הארת הירח על הארץ שמקבלת מאור השמש כו' וכמ\"ש במ\"א. וזהו כמ\"ש בע\"ח שמל'<sup data-n=\"331\">24</sup> דאצי' נעשה עתי\"ק דבריא\"ה ומל' דבריא\"ה עתיק דיצירה ומל' דיציר\"ה עתי\"ק דעשי' כו' שבה עצמה הוא המסך והפרגוד שמבדיל בין עולם העליון לתחתון כמו מל' דאצי' שהוא דבר ה' העליון ית' נעשה עתי\"ק לבריאה להתהוות התחדשות הנבראי' מאי\"ן ליש מחוד\"ש כנ\"ל והוא ע\"י השתנות הצרופי אותיו' שבמל' דאצי' כענין השתנות המושכל של הרב בצרופי אותיו' אחרי' של המשל כענין משלי שלמה כו' בן חכם ישמח<sup data-n=\"332\">25</sup> ובן כסיל תוגת אמו כו' או לשמרך מאשה זרה<sup data-n=\"333\">26</sup> ונכרי' אמריה החליקה כו' שהם דברים מוסר פשוטים ממלי דעלמא מדברי משל ומליצה שהלביש בהן סודות התורה רזין דאורייתא למי שמבין פנימיות דבריו סתרי תורה מה שמלובש במשלי' ההם, כמ\"ש בו וידבר שלשת אלפי' משל<sup data-n=\"334\">27</sup> וגו' שאף כשמובן הנמשל מתוך המשל אינו בערך ומהו' עצמו' המושכל שהי' בחכמת שלמה כו' שנתחדש המושכל מאין ליש ע\"י השתנות הצרופי' בלבד &lt;מ&gt;\nכך למעלה ע\"י השתנו' הצרופי' דמל' דאצי' זה גורם לסבת התחדשו' היש מאי\"ן להיותה עתי\"ק לבריאה המחודש וזהו בעצמו המסך וד\"ל וכן בבי\"ע מעולם ועד עולם שמל' דבריאה נעשה עתיק ליצירה כו' כנ\"ל וד\"ל.\n<b>אך</b> כ\"ז ענין צמצום הפרסות דאבי\"ע שמובדל ומופרש מהם סיבת הצמצום של החלל שאין כמוהו בכל סדרי ההשתלשלות דאבי\"ע שהוא צמצום גדול ועצום יותר ואין ערך ביניהם כלל והיינו שהצמצום של הפרסא הוא שכל עצמות האור והשפע עליונה דאצי' מתגלה ומתלבש בו רק מצד עביותו של המסך והפרסא נשתנה לגריעותא בהגשמה ליש אצל המקבלים שזהו ההתחדשו' מאי\"ן לי\"ש כנ\"ל משא\"כ הצמצום של החלל ומקום פנוי שהאור והגילוי נסתלק ונתעלם ממנו ליכלל במאור הנעלם שזהו מיעוט וחסרון לגבי החלל שהוא פנוי מגילויו שנסתלק ונעלם במקורו כנ\"ל וה\"ז כמשל הרב המעלים עצמו' המושכל מהתלמיד ואינו חפץ להשפיע לו כלל רק אפס קציהו ושמץ מנהו מגלה לו. אך זהו בענין ההשפעה לזולתו ועיקר המשל הדומה לנמשל הוא כשמצמצם הרב גילוי שכלו בינו לבין עצמו שאינו רוצה להתייגע בכל שכלו בעומק החכמה זולתי מעט מזעיר משכלו מתגלה בענין הלימוד בנקל בדבר שא\"צ להתייגע בכל שכלו זולתי אפס קציהו ושמץ מנהו כו' כנ\"ל שזהו למעלה ענין הצמצום באור א\"ס שנעשה חלל ומקום פנוי ונמשך רק קו א' דק בחי' מל' דמל' דא\"ס שצמצום גדול כזה לא נמצא עוד בכל ההשתלשלות כולן וכנ\"ל וזהו אנת הוא חד ולא בחושבן וד\"ל.\n<b>לאנהגא</b> בהון עלמין סתימין דלא אתגליין כו', והנה ידוע זה הכלל שכל הבחי' ומדרגו' שונות שנמצאו בעולם האצי' אף בחי' העולמות שנסתעפו",[["331","24","<b>שמל' דאצי' נעשה עתיק דבריאה</b>: ראה עץ חיים שער (ו) העקודים פ\"ב."],["332","25","<b>בן חכם ישמח</b>: משלי י, יא."],["333","26","<b>לשמרך מאשה זרה</b>: שם ז, ה."],["334","27","<b>וידבר שלשת אלפי' משל</b>: מלכים-א י, יז."]]],[2100490121,"מחיצוניות הכלי' דאצי' נק' הכל בשם עצמותו דאיהו וגרמוהי והעלמין דילי' חד ממש בתכלית היחוד, ומבשרי אחזה שכל הענפים והכחות המסתעפים מהנפש אף בחי' כחות חיצוניות שלה הם הכל מיוחדים עמה בתכלית היחוד שנקראו על שמה ששייכים אליה ולא לזולתה כמו כח הראי' הנמשך מהשכל בכלי העין שאף שהשכל הוא כלי העצם של הנפש וכמ\"כ הכח הראי' וכלי העין כולם שייכי' לה וכן כל אברי הגוף כולן או כמו כשהאדם מצייר בדעתו מין תפוח שהתפוח המצוייר בדמיון מחשבתו אין לו ערך אל התפוח הגשמי שזהו מחשבתו של האדם המיוחד עמו ושייך אליו ולא לזולתו אך למעלה באצילות ימצא ענפים כהנה רבות ותולדותיהן כיוצא בהן שכולם מיוחדים במאצילן ב\"ה שאף העולמות המסתעפים מחצוניות הכלי' מיוחדים עמו דהיינו כמ\"ש באדר\"ק כל נימא ונימא<sup data-n=\"335\">28</sup> להיט בתליסר אלפי עולמות כו' דהיינו שמחצוניות כלי החכמה דאצי' יסתעפו הנימין והשערות ומכל נימא ונימא יתהוו עלמין אין מספר שכולם כאחד מיוחדי' במאצילן ב\"ה שהם בחי' אלקות ממש דאיהו וחיוהי וגרמוהי חד כנודע שיש אף בחי' דומם באצי' וכנ\"ל במשל ציור האדם בכל הנפעלים דעשי' שהמחשבה של כל הנפעלים דבי\"ע הוא באצילות וזהו ממש מקור חיותן &lt;מא&gt;\nכמ\"ש במ\"א וכולן אף הדומם דאצי' מיוחדות עמו בתכלית היחוד וד\"ל וזהו אנת הוא דאפיקת כו' דה\"א מאחר שעצמות המאציל מרומם לבדו עד שאין ערוך אליו הם בחי' נפרדים ממנו ממש, לזאת קמל\"ן אליהו ז\"ל שבמקום גדולתו<sup data-n=\"336\">29</sup> שם אתה מוצא ענוותנותו שאנת הוא דאפיקת כו' ומיוחד עמהם בתכלית היחוד דאיהו וגרמוהי חד כנ\"ל וד\"ל.\n<b>חד</b> אריך וחד קציר וחד בינוני, פי' מדת החסד<sup data-n=\"337\">30</sup> עליון דרועא ימינא היא ארי\"ך שמתפשט במורד מאד למטה, שנמשך באורך משך השפע למטה מטה שזהו טבע מדת החסד הפשוט להתפשט בלי די אף למי שאינו הגון כמ\"ש אברהם אע\"ה לו<sup data-n=\"338\">31</sup> ישמעאל יחיה לפניך כו' ולכך נק' בשם ארי\"ך מצד התפשטות באורך משך השפע מאד למטה מטה אף למי שאינו הגון וכדאי אליו כנ\"ל. וחד קצי\"ר, היא מדת הגבורה והדין צדק שלמעלה שהיא היפך החסד שטבעה לקצר ולצמצם השפע ולמנוע שלא יתפשט באורך משך כ\"כ למטה אף למי שאינו כדאי והגון שזה הדין צדק שלמעלה שמדת הדין מונע החסד שלא יגיע לזה שאינו הגון ונתחייב עפ\"י דין שלמעלה כו'. וחד בינוני, זהו מדת הת\"ת הממוצע המכריע ביניהם שכוללם שניהם יחד, דהיינו שמטה כלפי גבורה בזה שלא תתפשט החסד יותר מדאי אף למי שאינו הגון מצד טבע החסד בלבד מאחר שאינו כדאי לו עפ\"י מדת הדין עליון, אך אעפ\"כ מטה כלפי חסד בזה שלא יהי' מדת הגבורה מקצר השפע ומונעה לגמרי כ\"א תתפשט אליו מצד מדת הרחמנות שאמת שאינו כדאי אבל אעפ\"כ גדלה הרחמנות עליו כו' ולכך נק' בשם בינונ\"י שכולל שניהם יחד ומכריע ביניהם להעמיד על מזג השוה שלא יתפשט יותר מדאי מצד החסד גרידא ולא יתקצר יותר מדאי מצד",[["335","28","<b>באדר\"ק כל נימא ונימא</b>: ראה תו\"א מקץ לב, א. תו\"ח מקץ רכה, א ובהנסמן שם בהמ\"מ."],["336","29","<b>שבמקום גדולתו</b>: ראה מגילה לא, א."],["337","30","<b>החסד. . אריך. . קציר. . הגבורה</b>: ראה תו\"א וירא יד, ג באריכות."],["338","31","<b>לו ישמעאל יחי' לפניך</b>: לך לך יז, יח."]]],[2100490122,"הגבורה גרידא זולתי שיתמזגו שניהם במזג השוה והיינו במדת הרחמים* שכלולה מחו\"ג<sup data-n=\"339\">*31</sup> ההפכיי' יחד לעשות שלום ביניהם כנ\"ל וד\"ל.\n<b>ועםכ\"ז</b> יובן מ\"ש בפרשה זו ארדה נא<sup data-n=\"340\">32</sup> ואראה הכצעקתה הבאה אלי עשו כלה וגו'.\n<b>הענין</b> כמשנת\"ל שיש למעלה באצי' בחי' עלמי\"ן שנמשכו ונסתעפו מחיצונית הכלי' דע\"ס דאצי' שהמה ענפים כמו מכלי החכמה יסתעף בחי' כלי הראי' עיינין דלעילא דכתיב עיני ה' משוטטות בכל הארץ<sup data-n=\"341\">33</sup> וגו' דהיינו שהמה כלי הראי' של המאצי' ב\"ה שתתלבש בהם בחי' החכמה עליונה דאצי' שבה מלובש אור א\"ס ב\"ה להסתכל ולראות בשמים ובארץ כו' כמו עד\"מ בנפש האדם שכח הראיה נסתעף מהשכל להתלבש בכלי העי\"ן לראות הנראה שאם יתקלקל הכלי שלו לא יביט מצד קלקול הכלי שא\"א לכח הראי' להתגלות בו, כך למעלה הכלי' של הראי' הם מצמצם השפע עליונה דאור א\"ס ב\"ה שעל ידם יסתכל בשמים ובארץ מצד שהם מגבילי' ומצמצם השפע עליונה בהכלי' שלהם שהם התיקונין שלו לצורך פעולתיו מה שא\"א בלעדן, &lt;מב&gt;\nכמו שא\"א להשכל לראות הגשם ממש בלתי כלי העין וד\"ל, וזהו עיני ה' משוטטות בכל, ויש כלים אחרים באצי' ונק' אזני ה'<sup data-n=\"342\">34</sup> שע\"י יפעול פעולת השמיעה עליונה כדכתי' ויקשב ה' וישמע<sup data-n=\"343\">35</sup> כו' וכולם כאחד מיוחדים במאצילן ב\"ה שנק' על שם עצמותו דאיהו וגרמוהי חד כנ\"ל. והנה ידוע שיש למעלה ב' בחי' ומדרגות שונות, והוא בחי' אור ישר ואור חוזר שא\"י הוא מצד החסד שנק' ארי\"ך שמתפשט מלמעלה במורד למטה יותר בלי די אף למי שאינו הגון כו' כנ\"ל וא\"ח הוא בחי' ההעלא' מ\"ן מלמטה למעלה בבחי' א\"ח בגבורו' רשפי אש כו' שהוא מצד הגבורה שנק' קצי\"ר שטבעה לצמצם ולמנוע השפע מהחייבי' עפ\"י מדת הדין.\n<b>והנה</b> אנשי סדום הי' רעים וחטאים<sup data-n=\"344\">36</sup> לה' מאד, והי' אפשר לדונם באחת מב' פנים אלו או עפ\"י מדת הדי\"ן שהוא בחי' א\"ח שעולה מלמטה למעלה והיינו שהדין שלהם יהי' כאופן הצעק\"ה שעלה מלמטה למעלה ממעשיהם הרעים לפני ה' כי זכר כל היצור בא לפניו שתעל שועתם וצעקתם כי רבה מכל העולות ומעשיהם הרעים מלמטה למעלה לפניו שעפ\"י הצעקה העולה מלמטה למעלה בבחי' א\"ח שמצד הגבורה שנק' קציר יתחייבו כלייה ביותר מצד מדת הדי\"ן, אבל אפשר שיזכה אותם מדת החסד שלמעלה שנק' ארי\"ך כנ\"ל, וזהו אופן השני שיושפ\"ל השפע עליונה של המאצי' ב\"ה מלמעלה למטה בבחי' א\"י להתלבש בכלי הראי' ולראות",[["339","*31","<b>הרחמים שכלולה מחו\"ג</b>: ראה ג\"כ אוה\"ת ויקרא (כרך ד) דרושים לפסח ע' תתקצא הערה כי\"ה."],["340","32","<b>ארדה נא</b>: וירא יח, כא."],["341","33","<b>עיני ה' משוטטות בכל הארץ</b>: ראה זכרי' ד, י. דברי הימים-ב טז, ט."],["342","34","<b>אזני ה'</b>: בהעלותך יא, א. יח. וראה ת\"ז ת\"ע (קלא, א)."],["343","35","<b>ויקשב ה' וישמע</b>: מלאכי ג, טז."],["344","36","<b>אנשי סדום הי' רעים וחטאים</b>: לך לך יג, יג."]]],[2100490123,"מעשיהם הרעים, שאפשר מצד התגברו' מדת החסד שבחי' המתלבש בכלי הראי' לא יתחייבו כלייה מצד שלא ישתוו הא\"י והא\"ח בזה כנ\"ל, לז\"א המאציל ית' ארדה נא ואראה פי' ארדה בחי' ירידת השפע דא\"י מלמעלה למטה להתלבש בכלי הראי' כדכתיב המשפילי<sup data-n=\"345\">37</sup> לראו\"ת בשמים ובארץ וגו', הכצעקתה באה אלי, פי' אם ישתווה בזה הא\"י עם הא\"ח שהי' מן צעקתה הבאה אלי, להיותם מתחייבי' כלייה אף עפ\"י הא\"י היורד להתלבש בכלי הראי' שישתווה בזה עם הא\"ח אז עשו כלה ואם לאו שלא ישתוו הא\"י והא\"ח שהא\"י מטה כלפי חסד אז אדע\"ה וד\"ל.",[["345","37","<b>המשפילי לראות בשמים ובארץ</b>: תהלים קיג, י."]]],[2100490124,"<h3>שמע ישראל</h3>\n<b></b><b>בעזר\"ה, ליל ה' פ' חיי שרה</b>\nליל ה' פ' חיי שרה\n<b>שמ\"ע</b> <sup data-n=\"346\">1</sup>ישראל הוי' אלקי\"נו הוי' אח\"ד*<sup data-n=\"347\">*1</sup>, בשכמל\"ו, ואהבת וגו' והיו הדברים האלה אשר אנכי מצוך היום וגו', הנה תחלה צריך להקדים הקדמה זו, שלמעלה הוא למעלה מהזמן הכולל וסוקר הכל יחד שצופה ומביט עד סוף כל הדורות<sup data-n=\"348\">2</sup> בכל שית אלפי שני<sup data-n=\"349\">3</sup> דקיים עלמא בעדנין אלו דחלפי' עלן &lt;מג&gt;\nומה שעתיד להיות בסקירה אחת, והתהוות הזמן הוא למטה בעולם הבריאה ולא באצי' מפני שזמן הוא נברא<sup data-n=\"350\">4</sup> ומחודש מאי\"ן לי\"ש כמו עולם נפש כו' והוא נמשך ג\"כ עפ\"י סדר ההשתלשלות עילה ועלול כמו עולם נפש כו' והיינו שבאצי' הוא סדר הזמן שורש התהוות הזמן הנברא דבי\"ע (וכנודע ששרש התהוות הזמן הוא מבחי' רו\"ש ומטו\"מ כו').\n<b>והענין</b> דבזה יש פלוגתא בין חכמי המחקר בשכל אנושי והוא הרב אב\"ע עם חביריו<sup data-n=\"351\">5</sup> שדעת הראב\"ע הוא שזמן הוא נברא כו' ואחרים אומרים שאינו נברא כו' והאמת שזולת זה שעפ\"י קבלה זמן היא נברא כנ\"ל שא\"צ לראי' בשכל אנושי אלא אפי' עפ\"י שכל אנושי יש ראיות לסתור דעתם וסברתם הבדוי מלבם, וזו אחת מהנה, דהנה אין הזמן שוה בעוה\"ז בכל המקומו' שהכל תלוי לפי אופן הילוך גלגל השמש והמקום ההוא אם הוא בקוטב הצפוני או הדרומי, או בקו השוה, שיש",[["346","1","<b>שמע ישראל הוי' אלקינו</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קעד, ב). נמצא ג\"כ בכת\"י 207 קצב, א."],["347","*1","<b>שמע ישראל. . אחד</b>: ואתחנן ו, ד."],["348","2","<b>שצופה ומביט עד סוף כל הדורות</b>: ברכת זכרונות. ראה ר\"ה יח, א (וע\"ש בחדא\"ג מהרש\"א). וראה לקו\"ת שה\"ש יח, ד."],["349","3","<b>שית אלפי שני</b>: ראה ר\"ה לא, א."],["350","4","<b>שזמן הוא נברא</b>: ראה סידור שער הק\"ש עה, סע\"ד בשם הה\"מ. לקו\"ת בלק ע, ג. מאמרי אדה\"ז תקס\"ה ע' שא. נביאים ע' רסו. אמרי בינה שער הק\"ש פל\"ז. לקו\"ש ח\"י ע' 176."],["351","5","<b>פלוגתא. . הרב אב\"ע עם חביריו</b>: ראה לקו\"ש שם, ובהנסמן שם. לקמן ע' פח."]]],[2100490125,"מקומו' שהיום קצר מאד והלילה גדולה מאד, ויש מקומות שהיום גדול מאד והלילה קצר מאד הכל לפי המקום והזמן ההוא אם השמש זורח שם במוקדם או במאוחר וכן בשקיעתה כו' כידוע לחכמי התכונה.\n<b>ואעפ\"כ</b> זמן ק\"ש שתיקנו חז\"ל הוא בכל מקום בשוה דהיינו ברביע היום כו' ואע\"פ שבזמן ק\"ש של מקום ההוא הוא במקום זה עדיין לילה ואפילה כו' וכנודע שבזמן הבוקר בעלות השחר זמן ק\"ש אתער בוקר דלעילא בוקר דאברהם<sup data-n=\"352\">6</sup> שאז מתגלה מדת החסד עליון למטה. וא\"כ אם זמן אינו נברא איך יתחלק החסד עליון בשינוי הזמן במקום זה מתגלה קודם ובמקום זה באיחור זמן מה מאחר שהזמן הנה ישנו למעלה ג\"כ הרי עת וזמן א' הוא להתגלות הח\"ע והי' מצטרך להיות בכל המקומות בשוה בזמן א' קריא' שמע כו', וכן בענין קידוש השבת שא' רבי יוסי יהי' חלקי ממכניסי שבת בטברי'<sup data-n=\"353\">7</sup> וממוציאי שבת בציפורי שבטברי' מכניסין השבת קודם לצפורי ששם עדיין חול וכן בציפורי מוציאי' השבת באיחור זמן שאז שבטברי' נעשה חול ובצפורי חל עדיין קדושת שבת כו' ואיך יתכן למעלה בקדושת השבת שיהי' תלוי בשינויי הזמן שלמטה של המקומות המשונים, ואיך יתחלק לחלקים של הזמן המשונה בהמקומות שלמטה שממ\"נ איך שהוא למעלה בזמן א' כך הי' צ\"ל למטה בכל המקומות בשוה בטברי' שאז יתחייב מיתה בעשיית מלאכה מאבות מלאכות ובציפורי יהי' מותר וכן להיפך כו'. אך הענין שבאמת עיקר התהוות הזמן הוא למטה שמשתנה לפי אופן שינוי המקומות בשינוי סדר זריחות השמש ושקיעתה במקום ההוא, אבל למעלה באצי' הוא למעלה מהזמן הצופה ומביט עד סוף כל הדורות בסקירה אחת, רק שינויי הזמן שלמטה בחול ושבת וי\"ט לילה ויום קיץ וחורף הוא למעלה השינוי בהספירות עליונות ששרש השבת שלמטה הוא למעלה ספי' &lt;מד&gt;\nמלכות כי בו שבת וינפש<sup data-n=\"354\">8</sup>, ושיתא יומין דחול הם ו' מדות<sup data-n=\"355\">9</sup> שהם ו' ימי המעשה כו' והם הם מקוריים לסבת התהוות שינויי הזמן שלמטה בו' ימי המעשה ואח\"כ בא שבת בא מנוחה<sup data-n=\"356\">10</sup> כו' אך למעלה השינוי הזה אינו בבחי' הזמן זולתי בספירות שיו\"ט מקבל מספי' א' ושבת מספי' אחרת וששת ימי המעשה מספירות אחרי', והספירו' האלו המשוני' נכללי' ונסקרי' בסקירת החכמה עליונה דאצי' בסקירה אחת שהחכמה איננה בגדר זמן כלל שלא יתכן לומר עליה סבת הזמן כ\"א הכל נכללי' כאחד בסקירה א' בלי שיהוי זמן מה ואין מוקדם ומאוחר שזהו צופה ומביט עד סוף כל הדורות (כענין הראי' הגשמיו' על גוש גשמיי שההבטה בהעין תופס כל עצם הדבר ההוא בלי קדימת ראש וסוף כלל ואין בו מוקדם ומאוחר כמשנ\"ת במ\"א).",[["352","6","<b>אתער בוקר דלעילא בוקר דאברהם</b>: ראה זהר (רעיא מהימנא) משפטים קיט, ב. תקו\"ז תכ\"ב (סז, א). וראה תו\"א יב, א."],["353","7","<b>שא' רבי יוסי יהי' חלקי ממכניסי שבת בטברי'</b>: שבת קיח, ב."],["354","8","<b>כי בו שבת וינפש</b>: ראה בראשית ב, ג. תשא לא, יז."],["355","9","<b>ושיתא יומין דחול הם ו' מדות</b>: ראה גם תו\"ח נח סא, ב ואילך. שמות תריט, ב."],["356","10","<b>בא שבת בא מנוחה</b>: פרש\"י עה\"פ בראשית ב, ב. פרש\"י ד\"ה ויכל — מגילה ט, א. (וראה ב\"ר פ\"י, ט). תוד\"ה חצבה — סנהדרין לח, א."]]],[2100490126,"<b>אך</b> לאחר שיוצאים ונמשכים המדות מהשכל עליון שאז מתחלקי' בבחי' התחלקות ממש ענפין מתפרדין שמדת החסד הוא מהות דבר בפ\"ע היפך הגבורה כו' אזי הם נעשים מקור לסבת הזמן שלמטה שנק' בשם סדר הזמן<sup data-n=\"357\">11</sup> כמ\"ש במ\"א (שהם בבחי' רו\"ש שזהו סדר הזמן שמזה יסתעף סיבת הזמן בחי' השיהוי המשתהה מהרו\"ש שהוא כענין דפיקא דלבא<sup data-n=\"358\">12</sup> שתנועת רו\"ש שמאחר שיש חיוב ושלילו' החיוב זה גורם לסבת השיהוי של זמן מ\"ה דהיינו השוב ואח\"כ הרצוא שהוא הגילוי השפע וההעדרו כו' וכמו במורה השעו' התנועה אנה ואנה גורם השיהוי זמן הרגע (שזהו מה<sup data-n=\"359\">13</sup> שקוראי' אומרי\"א בזייגער) שהוא כעין דפיקא דלבא כו' וכמשנ\"ת במ\"א בענין תתרף רגעי' של רב אדא בר אהבה שלמעלה מעלה מה שיותר קרוב אל המקור הזמן בקיצור יותר כמ\"ש כי אלף שנים בעיניך כיום אתמול<sup data-n=\"360\">14</sup> שזהו באצי' שו' מדות דאצי' הם ו' יומין הכוללי' ו' אלפי שני ולמעלה מאצי' הוא בקיצור יותר, מצד שבהמדו' דאצי' הוא בבחי' רו\"ש<sup data-n=\"361\">15</sup> כמראה הבז\"ק כעין דפק הלב שבין הרצוא ובין השוב משתהה זמן מה יותר שיש הפסק יותר בינתיים מצד הריחוק מן המקור יותר שמצטרך להיות הפסק גדול עד שיעלה הרצוא למקורו<sup data-n=\"362\">16</sup> ואח\"כ ישוב אל הכלי מקורו כו' משא\"כ למעלה מאצי' שהוא בחי' מטי ולא מטי<sup data-n=\"363\">17</sup> שמצד ההתאחדו' בהמקור הוא רק בחי' מול\"מ כו' (וכמשל הנר<sup data-n=\"364\">18</sup> שבשעת שהלהב עולה מתנונע בתנוע' רו\"ש כו' כמ\"ש במ\"א דכתיב בהילו נרו על ראשי<sup data-n=\"365\">19</sup> ובה' תתהלל נפשי וכמ\"ש רשב\"י בי' אחידא בי' להיטא<sup data-n=\"366\">20</sup> כו' ע\"ש) ששם קיצור הזמן יותר וזהו שרש התהוות הזמן וכמשנ\"ת במ\"א ע\"ש ודוק היטב.\n<b>ולזאת</b> הזמן של ק\"ש וכן של שבת שוה כאופן המקום והזמן ההוא ולא יהי' זמן ק\"ש ושבת בכל המקומות בשוה בזמן אחד זולתי הכל לפי המקום והזמן ההוא שזמן ק\"ש מצטרך להיות ברביע היום כו' וכפי המקום ההוא ברביע היום שלו צריך לקרות ק\"ש אף שבמקום אחר הוא עדיין לילה &lt;מה&gt;\nואינו זמן ק\"ש, וכן בענין השבת שבטברי' מכניסי' שבת קודם ובצפורי באיחור זמן כו', והיינו מפני שלמעלה באצי' הוא למעלה מהזמן רק מקור וסדר הזמן שלמטה דהיינו מה שלמטה הוא בשינוי הזמן הוא למעלה במקורם שינוי הספי' שלילה מקבל ממהו' ספי' אחר ויום מספי' אחר וכן בחול ושבת כנ\"ל, ולזאת כשהאיר פני המזרח במקום הזה קודם אזי נמשך",[["357","11","<b>סדר הזמן</b>: ראה ג\"כ דרך מצותיך נז, ב."],["358","12","<b>דפיקא דלבא</b>: ראה תו\"א ב, ג-ד — ונק' בזוהר. וראה מאמרי אדה\"א שמות ח\"ב ע' תמג. וש\"נ."],["359","13","<b>מה שקוראי' אומרו\"א בזייגער</b>: ראה ג\"כ לקו\"ת דרושים לר\"ה סא, א."],["360","14","<b>כי אלף שנים בעיניך כיום אתמול</b>: תהלים צ, ד."],["361","15","<b>רו\"ש כמראה הבזק</b>: יחזקאל א, יד."],["362","16","<b>מקורו</b>: אוצ\"ל: ממקורו."],["363","17","<b>מטי ולא מטי</b>: ראה זהר בראשית טז, ב. נח סה, א."],["364","18","<b>וכמשל הנר</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תמג. וש\"נ."],["365","19","<b>בהילו נרו על ראשי</b>: איוב כט, ג."],["366","20","<b>בי' אחידא בי' להיטא</b>: ראה זהר (אדרא זוטא) האזינו רפח, א. רצב, א. סידור ערב שבת קסג, א. מאמרי אדה\"א קונטרסים ע' נד. וש\"נ. מאמרי אדה\"א שמות ח\"ב ע' שכט. וש\"נ. תו\"ח לך צו, א."]]],[2100490127,"למקום ההוא קודם בחי' החסד דבוקר דאברהם ולכך צריך לקרות ק\"ש קודם משא\"כ במקום השני שעדיין לילה שלא נמשך לו עדיין ספי' החסד כדומה לכך אין הזמן דק\"ש הגיע, וכן לענין שבת.\n<b>והענין</b> כי באמת למעלה באצי' הוא למעלה מהזמן שנכללי' כל הספי' שונות כאחד בסקירת הח\"ע כנ\"ל ואחר התחלקותן נמשך כדומה מדת החסד מלמעלה כוללי בלי התחלקות ואח\"כ בהגיעתו למטה מתחלק בהתחלקות פרטיים כאופן שינוי התחלקות הזמן שלמטה, שלמקום ההוא שהאיר פני מזרח קודם שמגיע התחלקות החסד פרטיי דבוקר עלאה לשם קודם ובמ\"א באיחור קצת אבל מלמעלה נשפע החסד כוללי לכולם בשוה מצד שעיקר התהוות הזמן הוא למטה ולזאת מתחלק החסד דרך פרט למטה להיות מגיע לכל מקום במועדו ובזמנו כנ\"ל וד\"ל.\n<b>וזהו</b> ענין היחוד דק\"ש להמשיך גילוי אור אין סוף ב\"ה שלמעלה מסדר ההשתלשלות ולמעלה מהזמן הצופה ומביט עד סוף כל הדורות בסקירה אחת לתוך סדרי ההשתלשלות שעי\"ז יתאחדו הט\"ס דז\"א כאחד וזהו נרמז במלת אחד א\"ח<sup data-n=\"367\">21</sup> הם ט\"ס דז\"א וד' הוא מחשבה עילאה פרצוף לאה כנודע, ותחלה נבאר סדר ההשתלשלות, מבשרי אחזה בנפש האדם השכל הוא מקור המדות שבעודן כלולי' בהשכל אזי נסקרים כאחד בהתכללות אחת דהיינו שיוכל להיות בהשכל סברת הזכות והחוב בנושא אחד בהתכללות אחד דהיינו כשבא אליו אזי עלה במוסכם שכלו לקרבו אף שהוא שונאו להפריז ולהיותו מטה כלפי חסד כו' וכשנולדי' מן השכל להיותם יוצאי' מההעלם לגילוי הלב אזי מתחלקי' זמ\"ז חסדי' בפ\"ע וגבורו' בפ\"ע שזהו בחי' יראה ואהבה הנולדים בלב מהתבוננות השכל עד\"מ כשמתבונן בשכלו שסחורה זו יקרה במקום פלוני ובמקומו יוכל לסחור אותה בזול וכשיעמידנה למקום פלוני ירוח ממון רב אזי תתפעל לבבו מאד באהבה וחשק וחפץ לקנות הסחורה ההיא וכן להיפך בבחי' היראה משונאו שלא יעשה לו רעות ששומר נפשו ממנו כנ\"ל כמ\"ש במ\"א, ומהמדו' נובעת המחשבה וממחשבה דו\"מ, זהו ענין ההשתלשלות למעלה ג\"כ שנערכים זל\"ז בערך ההשתלשלות דהיינו המדות יש להם ערך אל השכל מקורן וכמ\"כ ערך המחשבה אליהן, והם קרובי' יותר בערכן אל השכל מן המחשבה ודו\"מ תולדותיהן כו' משא\"כ החכמה<sup data-n=\"368\">22</sup> שמאי\"ן תימצא שלא כדרך ההשתלשלות זולתי היא נמשכה מבחי' אי\"ן עצמות אור אין סוף שלמעלה מההשתלשלות כנודע אבל מחכמה ואילך &lt;מו&gt;\nהוא סדר הדרגת ההשתלשלות כו', וזהו שמע ישראל הוי' אלוקינו זהו היחוד דאו\"א תרין ריעין דלא מתפרשין<sup data-n=\"369\">23</sup> לעלמין דזיווגיהו תדיר כו' וכמ\"ש בע\"ח שיחוד זה דאו\"א הוא לצורך קיום העולמות כפי סדר ההשתלשלות להחיותן ולקיימם ולכך הוא בלי הפסק כמ\"ש ובטובו מחדש בכל יום תמיד מע\"ב<sup data-n=\"370\">24</sup> דהיינו בחי' יחוד חו\"ב",[["367","21","<b>אחד א\"ח</b>: ראה פרע\"ח (שער הק\"ש) ש\"ח, פי\"ב."],["368","22","<b>החכמה שמאין תמצא</b>: איוב כח, יב."],["369","23","<b>דאו\"א תרין ריעין דלא מתפרשין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א בראשית ע' א. וש\"נ."],["370","24","<b>ובטובו מחדש בכל יום תמיד מע\"ב</b>: ברכת יוצר."]]],[2100490128,"תרין ריעין דלא מתפרשי' שהוא התחדשו' מאין לי\"ש בתמידיות כי החכמה מאי\"ן תמצ\"א ובינה היא רחובות הנהר<sup data-n=\"371\">25</sup> עליון שנק' בחי'<sup data-n=\"372\">26</sup> י\"ש כמ\"ש להנחיל<sup data-n=\"373\">27</sup> אהבי י\"ש כנודע, ודרך כלל נק' עולם האצי' <sup data-n=\"374\">28</sup> בחי' חכמה ובריאה בינה כי אימא מקננא בבריאה<sup data-n=\"375\">29</sup> וז\"א ביצירה כו' כנודע וזהו ההתחדשות מאין ליש של הנבראי' המחודשי' ממל' דאצי' והכל עולה בסגנון א' וד\"ל.\n<b>הוי\"ה</b> אחד זהו יחוד זו\"ן דאצי' ע\"י עבודת האדם להוסיף אור א\"ס ב\"ה בז\"א שלא כדרך הדרגת ההשתלשלות אזי עי\"ז מתיחדים ט\"ס דז\"א ביחד כו' שמאחר שמתגלה עליהם אין האמתי שלמעלה מההשתלשלות דקמי' כחשיכה כאורה שוי' באין ערוך אליו ולא ימצא נגדו יתרון העליון על התחתון כו' לזאת מתבטלי' המדות דז\"א דאצי' לגמרי ומתאחדים ביחוד והתכללות אמיתי כאחד וזהו א\"ח ד' כמארז\"ל תמליכהו בד' רוחות וז' רקיעים<sup data-n=\"376\">30</sup> כו' וכמו ששמע ממורו (ה\"ה דמעזיריטיש ע\"ה) ביאור מלת אין ערך<sup data-n=\"377\">31</sup> שדקמי' כל אפי שוין כחשיכה כאורה<sup data-n=\"378\">32</sup> דאל\"כ הרי יש לו ערך שהעליון מתייחס אליו בקירוב יותר מן התחתון, והמשל בזה מגדר מספר הגשמיי ואין מספר שהוא בחי' אין סוף שאין לו תכלה כלל שמוכרחי' לומר שבא\"ס שאינו בגדר מספר כלל שם הרבבות והיחידות שוין בערך אחד דאל\"כ שנאמר שהרבבות ימצאו מעטי' מיחידות הרי הוא בגדר מספר ויש לו גבול ותכלה מאחר שהרבבות מעטי' מן היחידות, עד\"מ באלף אלפים (מילי ן) ימצאו הרבבות מאה והיחידות אלף אלפים ועד\"מ אף במספר גדול שלא ימנה ולא יספר מרוב מאחר שהוא בגדר מספר גבוליי אזי ימצאו הרבבות בערך מעטי' מהיחידו' כנ\"ל משא\"כ באין סוף שאין לו תכלה כלל ואינו בגדר מספר הרבבו' ישתוו בערך אחד עם היחידו' מה דלא סגי בלא\"ה כנ\"ל. וכמ\"כ למעלה בעצמו' א\"ס ב\"ה שאין ערוך אליו מוכרח להיות תכלית העילוי שבנאצלי' שוה בערך א' קמי' כלא חשיב כמו הפחות שבעשי' דאל\"כ הרי יש לו ערך שזה קרוב יותר מזה כנ\"ל וכדכתיב כחשיכה כאורה שמשתווים האור והחושך בערך א' במשקל ופלס א' בבחי' הביטול דכלא חשיבי ואין ערוך אליו כלל כדכתיב ישת<sup data-n=\"379\">33</sup> חשך סתרו שאפילו אור צח ומצוחצח אתחשך קמי' כו' וכתיב גם חשך לא יחשיך<sup data-n=\"380\">34</sup>",[["371","25","<b>ובינה היא רחובות הנהר</b>: בראשית לו, לז. וראה זהר (אדרא רבא) נשא קמב, א. לעיל ע' ד."],["372","26","<b>בחי' יש</b>: ראה מאמרי אדה\"א בראשית ע' א ואילך. וש\"נ."],["373","27","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["374","28","<b>האצילות בחי' חכמה ובריאה בינה</b>: בלקו\"ת במדבר טז, א מציין לע\"ח [דפוס שקלאוו] שמ\"ז [שער סדר אבי\"ע] פ\"ג [ובכמה דפוסים פ\"ב].\nוראה שער (מב) דרושי אבי\"ע רפ\"א. פי\"ג. שער ההקדמות דרושי אבי\"ע דרוש וא\"ו."],["375","29","<b>אימא מקננא בבריאה</b>: ת\"ז ת\"ו (כג, א). עץ חיים שער (מז) סדר אבי\"ע פ\"ג. שער (מב) דרושי (כללות) אבי\"ע פי\"ג. תניא פל\"ט."],["376","30","<b>תמליכהו בד' רוחות וז' רקיעים</b>: ראה ברכות יג, ב. וראה זהר (רעיא מהימנא) פינחס רכג, סע\"ב ואילך. עקב ערב, א. הנסמן במאמרי אדה\"א בראשית ע' לד."],["377","31","<b>וכמו ששמע ממורו. . ביאור מלת אין ערך</b>: ראה סה\"מ הנחת הר\"פ ע' לח (בשם הה\"מ: ומרגלא הי' בפומי' דהרב המגיד נ\"ע). מאמרי אדה\"ז ענינים ע' נה. ביאוה\"ז להצ\"צ ע' תצט. וראה תניא פמ\"ח."],["378","32","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["379","33","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["380","34","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."]]],[2100490129,"ממך כענין שנאמר ועברתי בארץ מצרים ודרשו רז\"ל אני ולא מלאך<sup data-n=\"381\">35</sup> כו' מפני שמצרים היתה ערות הארץ<sup data-n=\"382\">36</sup> שהיו שטופי זימה כו' לזאת מצד רבוי וגדלות הטומאה<sup data-n=\"383\">37</sup> לא הי' להמלאך הקדושה באפשרי לירד לשם זולתי הקב\"ה בכבודו ובעצמו דכחשיכה כאורה שוי' דגם חשך לא יחשיך כו' ואפי' אור צח אתחשך קמי' וכמ\"ש במ\"א.\n&lt;מז&gt;\n<b>והיו</b> הדברים האלה<sup data-n=\"384\">38</sup> אשר אנכ\"י מצוך היו\"ם על לבב\"ך כו' פי' שמזה שאנכ\"י מצוך היו\"ם דייקא יהי' על לבב\"ך להיות נולד מזה בך בחי' האהבה לה' בכל לבב\"ך כו'.\n<b>והענין</b> דהנה כתיב אנכי<sup data-n=\"385\">39</sup> הוי' אלקי\"ך וגו' פי' הוי\"ה הוא כולל כל סדרי ההשתלשלות מריש כל דרגין היינו מבחי' מל' דא\"ס שרש הקו והחוט שלאחר הצמצום של אור אין סוף ב\"ה ועולמות העקודים נקודים וברודי' ואבי\"ע כו' משא\"כ אנכ\"י מי שאנכי<sup data-n=\"386\">40</sup> הוא בחי' עצמות אור אין סוף ב\"ה שלמעלה מכל ההשתלשלות שלמעלה מש' הוי' שהוא לפני הצמצום כו' דקמי כחשיכה כאורה שוי' באין ערוך אליו כנ\"ל וזהו אשר אנכ\"י מצוך היו\"ם דוקא וכמארז\"ל היום לעשותם ולא למחר לעשותם, היום לעשותם ולמחר לקבל שכרן<sup data-n=\"387\">41</sup> כו' והיינו כי בעה\"ב אין מתגלה רק בחי' ממכ\"ע זיו השכינה ב\"ה וכמארז\"ל מה הנשמה ממלא את כל הגוף<sup data-n=\"388\">42</sup> אף הקב\"ה ממלא כל העולם והיינו כמו הנשמה הממלא את הגוף שמתחלקי' כחותי' לפי מזג תכונת הכלי' אברי הגוף שבראש שורה השכל והחושי' המעולי' ראי' שמיעה ריח ודיבור כו' וברגלים כח ההילוך ובידים המישוש והמעשה כו' שאף מצד הנפש הי' יכולה להאיר בכלי הרגליים הארת השכל רק המניעה הוא מצד הכלי' כנודע שכל כלי מקבל כח ואור הנפש הראוי לפי מזגו כו' ולזאת לאחר התחלקותה באברי הגוף אזי בלתי אפשרי להיות נעשה מהרגל ראש כדומה שהרגל יהי' לו שכל כדומה כי אין לך דבר שאין לו מקום כנ\"ל וזהו למעלה בעה\"ב שמתגלה בחי' ממכ\"ע בחי' התלבשות מדת מלכותו ית' בתוך כ\"ע ממש בכלי' מכלים שונים לפי מזגם ותכונתם בהתחלקות פרטיית, ולזאת אין לך דבר שאין לו מקום שא\"א להתהפך שם ממהות למהות שבאשר הוא שם יהי' ולא יצא ממקומו בשום אופן ולזאת ארז\"ל רשעים אפי' ע\"פ של גהינם אינן חוזרים<sup data-n=\"389\">43</sup> דלכאורה פלא מאחר שהם מכירי' שם האמת מפני מה אינם חוזרים, אך האמת שאינן יכולי' לחזור שם בתשובה",[["381","35","<b>ועברתי בארץ מצרים. . אני ולא מלאך</b>: בא יב, יב. ספרי תבוא כו, ח. זהר (מהנ\"ע) וירא קיז, א. הגש\"פ."],["382","36","<b>שמצרים. . ערות הארץ</b>: ראה מקץ מב, ט. וראה קה\"ר פ\"א, ד."],["383","37","<b>וגדלות הטומאה</b>: ראה זהר חדש יתרו לא, א."],["384","38","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["385","39","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."],["386","40","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט (ע' תו). אב\"ע תולדות כז, יט. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד."],["387","41","<b>היום לעשותם. . ולמחר לקבל שכרן</b>: ואתחנן ז, יא. עירובין כב, א. לקו\"ש חכ\"ט ע' 43."],["388","42","<b>מה הנשמה ממלא את כל הגוף</b>: ברכות י, א. ויק\"ר פד, ח. מדרש תהלים (קג, א) הובא בלקו\"ת אמור לא, ב. נשא כג, ד."],["389","43","<b>רשעים אפי' ע\"פ של גהינם אינן חוזרים</b>: עירובין יט, א."]]],[2100490130,"מאחר שלא עשו תשובה בעה\"ז וטינפו מוחם בהרהורי עבירה ניאוף ודומיהן שלבושי' צואי' ילבש אותם ויהי' אסורי' בהם שם כאדם האסור בזיקים וכבלי ברזל ובלתי אפשר להם להפרד מהם שזהו מקומן שם ולכך אין חוזרים שמקומם הוא הגהינם זה וד\"ל (וכן אפי' לעלי' מג\"ע התחתון לעליון א\"א ע\"י התשובה זולתי בעת וזמן גרמא לזה מדי חדש ושבת כנודע).\n<b>משא\"כ</b> היו\"ם לעשות\"ם שהוא זמן המעשה, לאתבא בתיובתא<sup data-n=\"390\">44</sup> ולאהפכא <sup data-n=\"391\">45</sup> מחשוכא לנהורא וממרירו למיתקא מצד שלמטה בעה\"ז מתגלה בחי' סוכ\"ע בחי' אנכי מי שאנכי דקמי' כחשכה כאורה<sup data-n=\"392\">46</sup> שוי' שגם חשך לא יחשיך<sup data-n=\"393\">47</sup> וכו' ויוכל להיות קונה עולמו בשעה א' להתהפך ממהו' למהו' מן הקצה אל הקצה ברגע א' ע\"י התשובה כי אין מעצור לה' בחי' סכ\"ע להושיע כנ\"ל וכענין תשובת ר\"א ב\"ד<sup data-n=\"394\">48</sup> שהי' תחלה רועה זונות ואח\"כ קנה עולמו בשעה [אחת] עד שיצאת ב\"ק ואמרה ר\"א ב\"ד מזומן לחיי עה\"ב ור' בכה עליו כו'. רק רחמנא* לבא בעי<sup data-n=\"395\">*48</sup> כדכתיב אם ישים אליו לבו<sup data-n=\"396\">49</sup> רוחו ונשמתו אליו &lt;מח&gt;\nיאסף, כי רוח אייתי רוח<sup data-n=\"397\">50</sup> ואמשיך רוח כנ\"ל. וזהו והיו הדברים האלה אשר אנכ\"י מי שאנכי מצו\"ך<sup data-n=\"398\">51</sup> הוא לשון התקשרו' היום דייקא על לבב\"ך שיהי' מזה התעוררו' האהבה בכל לבבך ונפשך ומאדך שזה התשובה שמצטרך להיות היום דייקא מצד שעתה מתגלה אנכ\"י מי שאנכ\"י ולא למחר כו' כנ\"ל וד\"ל.\n<b>ודברת</b> בם בשבתך<sup data-n=\"399\">52</sup> וגו' כתיב עוטה אור כשלמה זו תורה<sup data-n=\"400\">53</sup> אור שהיא מעטה לבושו שמחברת אותו ית' עם כל סדרי ההשתלשלות כי אין אור א\"ס ב\"ה שורה זולתי בכלי הביטול הוא כלי החכמה<sup data-n=\"401\">54</sup> כ\"ח מ\"ה וכתיב כולם בחכמה עשית<sup data-n=\"402\">55</sup> וכמ\"ש בזוהר באורייתא ברא עלמא<sup data-n=\"403\">56</sup>, שהחיות של כל הנפעלים הוא חכמת התורה שיש בהן כמ\"ש במתניתין שמונה שרצים ודומיהן<sup data-n=\"404\">57</sup> כמשנ\"ת במ\"א, ולזאת",[["390","44","<b>לאתבא בתיובתא</b>: ראה זהר (רעיא מהימנא) בהעלותך קנג, ב."],["391","45","<b>ולאתהפכא מחשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["392","46","<b>דקמי' כחשכה כאורה</b>: תהלים קלט, יב. וראה עטרת ראש לעשי\"ת ע' נא."],["393","47","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."],["394","48","<b>תשובת ר\"א ב\"ד</b>: ראה ע\"ז יז, א. מאמרי אדה\"א בראשית ע' קפב."],["395","*48","<b>רחמנא לבא בעי</b>: ראה סנהדרין קו, ב וברש\"י שם. ספר חסידים סתק\"ל (ובהנסמן במקור חסד שם) וסתק\"צ. חובת הלבבות בהקדמה ד\"ה וכאשר התברר לי (ווארשא תרל\"ה ט, א)."],["396","49","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["397","50","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב."],["398","51","<b>מצו\"ך הוא לשון התקשרות</b>: ראה ג\"כ תו\"א מקץ מ, ג. לקו\"ת דברים א, ב. האזינו עד, א. שה\"ש מב, ג."],["399","52","<b>ודברת בם בשבתך</b>: ואתחנן ו, ז."],["400","53","<b>עוטה אור כשלמה זו תורה</b>: תהלים קד, ב. וראה תו\"א מט, ב."],["401","54","<b>החכמה כח מה</b>: זהר (רעיא מהימנא) צו כח, א. לד, א."],["402","55","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["403","56","<b>באורייתא ברא עלמא</b>: ראה זהר תולדות קלד, א. תרומה קסא, א-ב."],["404","57","<b>שמונה שרצים ודומיהן</b>: ראה שבת פי\"ד מ\"א."]]],[2100490131,"צריך האדם לעסוק בתורה יומם ולילה לקיים מצות והגית בו יומם ולילה<sup data-n=\"405\">58</sup> בכדי לקשר חב\"ד שבנפשו לחב\"ד של הקב\"ה היושב ושונה כנגדו<sup data-n=\"406\">59</sup> ועי\"ז ימשיך גילוי אור איך סוף למטה וכידוע שיש ע\"ס כלולי' בחכמה וזהו ו' סדרי משנה זרעים הם חסד שבחכמה<sup data-n=\"407\">60</sup> כו' כנודע אך לאו כל אפי' שוי' בענין הלימוד שמי שהוא יכול ללמוד בעיון גמ' ופוסקי' ראשוני' ואחרוני' לברר ההלכה פסוקה אזי אינו יוצא בלימוד קל דמקרא ואגדה שמצטרך לשים כל חב\"ד שבנפשו אליו ית' וכנ\"ל וד\"ל.",[["405","58","<b>והגית בו יומם ולילה</b>: יהושע א, ח."],["406","59","<b>הקב\"ה היושב ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ."],["407","60","<b>ו' סדרי משנה. . חסד שבחכמה</b>: ראה תקו\"ז בהקדמה ה, א. סה\"מ תקס\"ה ח\"א ע' עג (נוסח שני) ובהנסמן לשם."]]],[2100490132,"<h3>להבין מאמר הזוהר פ' חיי שרה אר\"ש</h3>\n<b></b><b>בעזר\"ה, שבת פ' חיי שרה</b>\nליל ש\"ק פ' חיי שרה\n<b>להבין</b><sup data-n=\"e6\">*</sup> מאמר הזוהר<sup data-n=\"408\">1</sup> פ' חיי שרה (דקכ\"ג ע\"א<sup data-n=\"409\">2</sup>), אר\"ש מ\"ש בכולהו דאמר שנה שנה ובאינון שבע דאמר שנים כו' אלא כולא חד מאה שנה כללא דכולא קוב\"ה דאתכלל מאתר עילאה סתימאה דכ\"ס במאה כו' וכן עשרים שנה כתיב שנה רזא דיחודא דלא אתפרש מחשבה ויובלא לעלמין ז' שנים אילין אתפרשאן ונפקאן<sup data-n=\"410\">**</sup>** מכללא סתימאה דלעילא ואע\"ג דכולהו יחודא חד אבל מתפרשין בדינא ורחמי כו'<sup data-n=\"e7\">*</sup> וכולהו איקרין חיי ויהיו חיי שרה דהוו ממש דאתבריאו ואתקיימו<sup data-n=\"411\">**</sup>** לעילא ע\"כ המאמר.",[["408","1","<b>להבין מאמר הזוהר</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 סו, ב (עם הגהות מכ\"ק אדמו\"ר הצ\"צ). 1052 קי, א. נמצא ג\"כ בכת\"י 70 ד, א (עם הגהות אחרות וקיצור). ובלי הגהות כ\"ק אדמו\"ר הצמח צדק בכת\"י 957 רסה, א. 1001 מב, א.\nהמאמר ((והביאור) עפ\"י כת\"י 1001 — ראה בסה\"מ תקס\"ה ע' א'קכג) הוא משנת תקס\"ו.\nהנחת ר' משה בן אדה\"ז נדפס לקמן ע' צה.\nהנחה אחרת באוה\"ת חיי שרה קו, ב. ביאוה\"ז מכ\"ק אדמו\"ר הצ\"צ ע' ע.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ע' קלא, בהתחלה: ויהיו חיי שרה."],["409","2","<b>דקכ\"ג ע\"א</b>: קכב, סע\"ב."],["410","**","<b>ונפקאן</b>: תיבה זו ניתוסף מכ\"ק אדמו\"ר הצ\"צ בגוכתי\"ק 1052."],["411","**","<b>ואתקיימו</b>: תיבה זו ניתוסף מכ\"ק אדמו\"ר הצ\"צ בגוכתי\"ק 1052."],["e6","*","<b>להבין</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: ויהיו חיי שרה <sup data-n=\"5791\">3</sup> מאה שנה ועשרים שנה ושבע שנים שני חיי שרה. להבין ענין הכפל שכפל לומר ב' פעמים חיי שרה. יש להקדים."],["e7","*","<b>בדינא ורחמי כו'</b>: בכת\"י 70 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: וכן בפסוק ויחי יעקב נאמר שבע שנים וארבעים ומאת שנה, ועיין בספר עבודת ישראל כאן ושם."],["5791","3","<b>ויהיו חיי שרה</b>: חיי שרה כג, א."]]],[2100490133,"<b>והנה</b> להבין כללות ענין המאמר ובפרט בעיקר כוונות המאמר במה שפי' ענין מאה שנה כנ\"ל, יש להקדי' תחלה פי' ענין המאמר הידוע אנת<sup data-n=\"412\">4</sup> הוא חד ולא בחושבן כו' אפיקת עשר תיקונין וקרית לון י\"ס כו' וי\"ל תחלה למה נקראו בלשון ספיר<sup data-n=\"413\">5</sup>ה דוקא כי לשון ספירה הוא ענין בהירות כמו מראה שנראין בה מפני בהירת הזכוכית כו' והוא מלשון ספיר כידוע<sup data-n=\"e8\">*</sup> הנה** אע\"פ<sup data-n=\"414\">**</sup> שמבואר בלק\"א <sup data-n=\"415\">6</sup> שהמדות והשכל שהן נחשבים בחי' עצמות הנפש היינו לגבי לבושין דהיינו מחדו\"מ כו' אבל לגבי עצמות הנפש גם הן נחשבים רק בחי' לבוש לבד ועכ\"ז יש ביניהם הפרש. וביאור הדבר הנה אנו רואים שהשכל באדם אינה אלא כמו בחי' כלי בלבד לגבי עצמות הנפש כי כשירצה איזה דבר יפעול הדבר ע\"י השכל שישכיל איך לעשות הדבר א\"כ אין השכל רק כמו ענין ממוצע לבד לחבר הנפש ולהביא לידי פעולת סוף המעשה כו' וה\"ז כמו שיתלבש האדם בלבוש כן תתלבש הנפש בחכ' בשביל איזה פעולה כו' והשכל נחלק לג' חלקים חב\"ד וגם הן ע\"ד הזה ומן השכל נחלק עוד לג' חלקים אחרים והן המדות חג\"ת שנמשכים מן השכל כידוע וגם הן ע\"ד הנ\"ל דהיינו שהשכל מתלבש במדות כו' והמדות מתלבשי' במחדו\"מ כנראה בחוש שכל מה שיעלה בלבו מיד יהרהר במח' כו' והמחדו\"מ נק' לבושים הנפרדים לגמרי כו' כמ\"ש כלבוש תחליפם<sup data-n=\"416\">7</sup> משא\"כ המדות והשכל נק' גופא<sup data-n=\"417\">**</sup>** אעפ\"י שהן כמו בחי' לבוש לגבי עצמות הנפש מ\"מ הן מתאחדי' עם הנפש והן נחשבים מ\"מ לעצם א' יותר כהתאחדות** הגוף עם חיות הנפש המלובש בו<sup data-n=\"418\">**</sup> וכמ\"ש במ\"א<sup data-n=\"e9\">*</sup>. והנמשל מכ\"ז יובן למשכיל למעלה בי\"ס העליונות חב\"ד ומדות כו' שנק' יו\"ד תיקונין הטעם שנק' תיקונין<sup data-n=\"e10\">*</sup> לפי שלגבי עצמות אור הא\"ס שמלובש בהן אינם אלא כמו ענין בחי' כלי הממוצע שעל ידו יפעול הפועל את הפעולה כנ\"ל במשל השכל לגבי נפש וזהו פי' תיקונין מפני שעל ידם יפעול פעולת שפע ההמשכה לכל העולמות וזהו פי' אפיק'",[["412","4","<b>אנת הוא חד</b>: ראה הקדמת ת\"ז (יז, א)."],["413","5","<b>ספירה. . בהירות. . ספיר</b>: ראה לקו\"ת אמור לה, ב."],["414","**","<b>הנה אע\"פ</b>: בכת\"י 115 רשם: ידוע, וכ\"ק אדמו\"ר העביר קו ע\"ז למחיקה."],["415","6","<b>שמבואר בלקו\"א</b>: פ\"ג. פי\"ב."],["416","7","<b>כלבוש תחליפם</b>: תהלים קכ, כז."],["417","**","<b>נק' גופא</b>: תיבות אלו ניתוספו מכ\"ק אדמו\"ר הצ\"צ בגוכתי\"ק 1052."],["418","**","<b>כהתאחדות. . בו</b>: תיבות אלו ניתוספו מכ\"ק אדמו\"ר הצ\"צ בגוכתי\"ק 1052."],["e8","*","<b>כידוע</b>: בכת\"י 70 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: ועמ\"ש בלק\"ת פ' אמור בד\"ה וספרתם לכם ועיין בת\"א פ' מקץ ד\"ה ת\"ר ב\"ש אומרים נר חנוכה בענין הלבושים הנעשים ממעשה המצות הם ע\"ד אספקלריא המאירה."],["e9","*","<b>במ\"א</b>: בכת\"י 70 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: והוא בת\"א ר\"פ וירא בד\"ה פתח אליהו דכ\"ג ע\"ב [בהוצאת קה\"ת ע' יג, ג]."],["e10","*","<b>תיקונין</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: תיקונין הוא ל' לבושי' כדאיתא בתרגום אונקלוס ע\"פ <sup data-n=\"5792\">8</sup>ולא ילבש גבר שמלת אשה ולא יתקן גבר בתיקוני איתתא. והענין."],["5792","8","<b>ע\"פ</b>: תצא כה, ב."]]],[2100490134,"יו\"ד תיקונין כו' לאנהגא בהון עלמין כו'<sup data-n=\"e11\">*</sup> ולזה הטעם נקראו ג\"כ בלשון ספירות כמו עד\"מ ענין הבטת האדם במראה שמפני בהירותה יביט למרחוק וכדומה כך עד\"מ הרי ע\"י היו\"ד תיקונין יצא אור השפע למטה בג' עולמות הנפרדי' שהן בחי' לבושים נפרדי' ממחדו\"מ והן עלמין סתימין ועלמין דאתגליין כו' אבל היו\"ד תיקונין עצמן הן עדיין בבחי' אלקות ביחוד גדול במאצילן כנ\"ל שהשכל והמדות נחשבים עדיין בחי' עצמיו' א' עם עצמו' הנפש אעפ\"י שעל ידם יפעול פעולה הנפרדת כו' וע\"כ נק' ספירות מלשון ספיר כלומר מפני שבחי' אא\"ס עדיין מאיר בהן בבחי' אור בהיר כדוגמת המראה כנ\"ל לפי שהן מתאחדי' עמו כו' דאיהו וגרמוהי**<sup data-n=\"419\">**</sup> כו' משא\"כ בג' לבושים מחדו\"מ שהן לבושים לבד<sup data-n=\"420\">**</sup>** כידוע וכנ\"ל ועליהם אמר לאנהגא בהון עלמין כנ\"ל וד\"ל. ונמצא מובן מכ\"ז שיש כאן ג' מדריגות בכלל הא' בחי' ג' לבושין דמחדו\"מ והב' המדות והשכל שהן בחי' גופא* שנק' תיקונין כנ\"ל והג' בחי' עצמות אור המאציל דאפיק יוד תיקונין הנ\"ל שהוא מובדל ומרומם בערך גם מי' הספירות וזהו מאמר אנת חד ולא בחושבן פי' ולא בחושבן י\"ס כו' כידוע וד\"ל. וביאור ענין ולא בחושבן י\"ס יובן בהקדי' תחלה דהספירות הן עשר ולא תשע ולא י\"א כו' כמ\"ש בס\"י<sup data-n=\"421\">10</sup> והנה זה המספר עשר הוא דוקא כשאור המאציל כבר ירד למטה ואפיק יוד תיקונין אז שייך לומר דאפיק יו\"ד ולא ט' כו' אבל בבחי' עצמו' הארת<sup data-n=\"422\">11</sup> המאציל לא שייך לומר כלל ענין מנין ומספר לספירות אלא הא' מב' אופנים<sup data-n=\"e12\">*</sup> אלא בא' מב' אופני' הנ\"ל ולא יתכן בו אותן ענינים שהמה הדברי' המנגדי' לזה והוא שיהא בגדר ספי' ושיהא במספר קצוב יו\"ד דוקא וכו' אלא בודאי מושלל הוא מב' דברים הללו והוא שאינו בגדר ספי' ואם גם הוא מתחלק יתחלק לריבוא רבבו' מדריגות עד אין שיעור כו' ואמנם הנה באמת אעפ\"י שבהכרח לומר שהאור המאיר מן המאציל עצמו",[["419","**","<b>וגרמוהי</b>: תיבה זו ניתוסף מכ\"ק אדמו\"ר הצ\"צ בגוכתי\"ק 1052."],["420","**","<b>לבושים לבד</b>: תיבות אלו ניתוספו מכ\"ק אדמו\"ר הצ\"צ בגוכתי\"ק 1052."],["421","10","<b>בס\"י</b>: פ\"א, מ\"ד."],["422","11","<b>הארת</b>: בכת\"י 1156 רשום: אור, וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחיקה."],["e11","*","<b>לאנהגא. . כו'</b>: בכת\"י 70 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: כמש\"ש בת\"א דכ\"ג עמוד ג' [בהוצאת קה\"ת ע' יג, ד]."],["e12","*","<b>אופנים</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: דהיינו או שלא תתחלק הארה זו לחלקים כלל אלא הוא אור א' פשוט בתכלית הפשיטות כי הרי האור מעין המאור שהוא ית' מובדל ומרומם לגמרי מערך ומהות ספירה כנ\"ל וא\"כ גם הארתו ית' שהיא ג\"כ מעין המאור היא ג\"כ פשוט בתכלי' כו' ולמעלה מגדר ההתחלקות כו' או שאם הייתה מאירה בבחי' התחלקות ומדריגו' שונות אז הי' ההתחלקות לריבוא רבבות מדריגות עד אין קץ ושיעור ממש ולא כמו שהוא עכשיו רק י\"ס לבד שהם עשר מדריגות לבד וריבוי התחלקות שבנבראי' הוא רק ממזיגת הכחות כידוע וסיבת התהוות י\"ס במספר קצוב הוא ע\"י צמצום הידוע אבל אלו הי' הארות א\"ס ב\"ה מאיר כמו שהיא שלא ע\"י צמצום רב ועצום כ\"כ לא הי' כלל מספר י\"ס"]]],[2100490135,"הוא בא' מב' פנים הנ\"ל או שהוא מתחלק לאין שיעור או שאינו אלא אור א' פשוט כו' והרי לפי הנראה ב' פנים הללו הפכיי' מ\"מ כאשר ישכיל המשכיל בזה יבין שאינם הפכיי' כלל ואדרבא היא הנותנת דלפי שהוא מתחלק לאין שיעור מזה מוכרח לומר שגם הוא אינו אלא אור א' פשוט והכל ענין א' והא בהא תלי' דלפי שהוא אור א' פשוט ע\"כ מתחלק לאין שיעור כו' ואעפ\"י שלכאורה תרתי דסתרי המה באמת אינם סותרים כלל ודבר זה מפורש ומבואר היטב במא'<sup data-n=\"423\">12</sup> הזהר הידוע דהמשיל ענין זה האור דכתר עליון כהאי בוצינא דאתפשטת מיני' נהורא לכל סטר כו' וכד תסתכל לא תשכח אלא בוצינא חדא כו'<sup data-n=\"e13\">*</sup>, ביאור ענין המאמר שהמשיל לאור הנר המבהיק ויוצאים ונמשכים ממנו לכל צד כמה וכמה ניצוצות אור שאעפ\"י שיתחלקו לכמה ניצוצו' כולן כלולין ומיוחדין בנר היחידי ונחשבי' רק על שמו וזהו באמרו וכד תסתכל לא תשכח אלא בוצינא חדא כו' והטעם הוא לפי שטבע האור להתחלק לכמה חלקים ניצוצות עד אין שיעור לריבוי אורות המדליקים ממנו ומ\"מ אור הנר עצמו עדיין נשאר בפשיטותו כמו שהוא ואין התחלקות הזאת גרם לו התחלקות והוא מפני שהוא פשוט בטבעו וע\"כ גם מזה הטעם יתחלק לאין שיעור כו' והמשל הזה אעפ\"י שהוא גשמי ג\"כ<sup data-n=\"424\">13</sup> להבין בדוגמא דדוגמא מזה למשכיל למעלה בעצמות אור המאציל אעפ\"י שהוא באמת אור א' פשוט כו' אבל מטעם זה הנה זאת היא הסיבה דוקא לריבוי ההתחלקות עד אין שיעור כו' וא\"כ ממילא מובן שגם מה\"ט אעפ\"י שכ\"כ נתחלקו לרבבו' מדריגות מ\"מ עדיין אור א' פשוט וכולן בטלין ומבוטלין בפשיטו' האור כאלו לא נתחלקו עדיין כו' והרי א\"כ מזה מובן שאין ב' הפכים הנ\"ל סותרים זא\"ז כלל אלא אדרבא שניהם ענין א' ממש והא בהא תלי' כנ\"ל וד\"ל והיינו פי' אנת חד ולא בחושבן י\"ס מטעם הנ\"ל<sup data-n=\"e14\">*</sup> וד\"ל,",[["423","12","<b>במא' הזהר</b>: ראה זח\"ג רפח, א."],["424","13","<b>ג\"כ</b>: בבוך 1001 נוכל."],["e13","*","<b>בוצינא חדא כו'</b>: בכת\"י 70 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: (ז\"ל באדר\"ז דף רפט ע\"א כבוצינא דאתפשטן מיניה נהורין לכל עבר ואינון נהורין דמתפשטין כד יקרבון למנדע לון לא שכיח אלא בוצינא בלחודו עכ\"ל)."],["e14","*","<b>הנ\"ל וד\"ל</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: ועתה יובן מ\"ש הזהר מאה שנה קוב\"ה דאתכליל מאתר עילאה סדכ\"ס במאה פי' קוב\"ה הוא בחי' אור הכתר שהוא ממוצע בין המאציל לנאצלים (ועל היות בו מבחי' תחתונה שבמאציל נק' קדוש ל' הבדלה שמובדל בערך מהעולמות ועל היות בו מבחי' שרש הנאצלים נק' ברוך ר\"ת<sup data-n=\"5793\">14</sup> ראש ומקור כל ברכה ר\"ל מקור ההמשכה לנאצלים) וזהו דאתכליל מאתר עילאה פי' א\"ס ב\"ה שהוא סתימ' דכ\"ס ולכן הוא ברזא דמאה שהוא למעלה מבחי' המספר די\"ס עשר ולא י\"א כו' והיינו משום שבא\"ס ב\"ה נאמר בזוהר כבוצינא דא דאתפשטין מיני' נהורין לכל סטר בחי' ומדריגות בלי קץ ממש ולא עשר לבד ולכן הכתר שיש בו מבחי' התחתונה שבמאציל הוא למעלה מן העשירות שהם בחי' י\"ס משא\"כ באו\"א אמר אח\"כ עשרים שנה שכל א' יש בו י\"ס עשר ולא ט' כו' (אך צ\"ל דא\"כ הי' ראוי להיות ההתחלקות מבחי' כתר בלי קץ ומספר כלל ולא מאה לבד. והענין הוא דלפי."],["5793","14","<b>ברוך ר\"ת</b>: ראה ערה\"כ (לבעל סדה\"ד) מערכת ברוך."]]],[2100490136,"שהכתר נק' בחי' ממוצע<sup data-n=\"425\">15</sup> בין המאציל לנאצלי' וענין הממוצע שלו היינו שיש בו מב' הפכי' ממהות ועצמות המאציל וממהות הנאצלים כידוע ומצד שהוא כלול מעצמות המאציל לבד הנה הוא למעלה עדיין מגדר התחלקות לי\"ס וי' לי' עד שבכללם הוא מספר מאה כידוע אלא מתחלק עד אין שיעור וגם מה שמתחלק כאלו אינם במציאות כלל כנ\"ל מפני שכלולין להיות בבחי' אור הפשוט של המאציל הנק' בוצינא חדא כו' וכנ\"ל בפי' המאמר וכד תסתכל לא תשכח כו' אך מצד בחי' התחתונה שבכתר שהוא כלול מבחי' הנאצלים ג\"כ להיות להם לראש ולשרש כידוע הנה הוא מתחלק לי\"ס דוקא ויו\"ד לי' עד שכללותם נק' מאה ואעפ\"י שעדיין גם זאת ההתחלקות אינה בבחי' גילוי גמור אלא רק בבחי' שרש ומקור עדיין כי לכך נק' כתר על שהוא בחי' הכותרת והמקפת להיותו בבחי' מקור הנאצלים כו' מ\"מ מאחר שהוא בחי' שורש ומקור לנאצלים בהכרח שימצא בו שורש כל פרטי התחלקות שלהם בכלל עכ\"פ והוא מספר מאה כי מה שכל ספירה כלולה מי' בלבד זהו בדרך כלל בלבד כידוע וד\"ל. וזהו פי' מאה שנה מאה הוא בחי' התחתונה שבכתר שמתחלק לי' ויו\"ד לי' מצד שהוא שרש ומקור להן כו'<sup data-n=\"e15\">**</sup> ופי' שנה שהוא ל' יחיד כאלו אינו אלא במספר א' דהיינו שנה א' בלבד היינו מצד בחי' הארת עצמות המאציל שיש בו שהוא למעלה מעלה מגדר התחלקות ליו\"ד דוקא אלא או מתחלק עד אין שיעור או שכל ההתחלקות כלא חשיבי ואינם אלא כבוצינא חדא ושניהם אמת דאעפ\"י שמתחלקים עד אין שיעור עכ\"ז המה כלולים בתכלית היחוד להיות רק בבחי' אור א' פשוט בלבד וע\"כ נק' מספר המאה כנ\"ל רק בשם שנה אחת בלבד ע\"ש בחי' היחוד שיש בו שאינו אלא כבוצינא חדא כו' ולהיות שהכתר הוא ממוצע מב' הפכים ע\"כ הוא כלול מב' המדריגות יחד דהיינו שהוא כלול ממספר מאה וגם הוא בבחי' היחוד להיות נקראים רק שנה אחת מצד בחי' אור עצמות המאציל שיש שם שמייחד אותם בתכלית היחוד ותכלית ההתכללות וד\"ל ובכל זה מובן פי' התחלת המאמר הנ\"ל מאה שנה כולא חד קודב\"ה דאתכליל מאתר עילאה סתימא דכל סתימי' הוא ברזא דמאה וביחודא חד כו' פי' סתימאה דכל סתימין היינו הארת עצמו' המאציל וקוב\"ה וקודב\"ה הוא בחי' אריך (או בחי' מל' שבכת\"ר כו'). דאתכליל גם מבחי' עצמו' המאציל שנק' אתר עילאה ואעפ\"כ הוא שרש וראש לי\"ס הנאצלים ע\"כ הוא ברזא דמאה ברכאן כו' ומ\"מ הוא ביחודא חד מאה שנה כולא חד כללא דכולא כו' וד\"ל<sup data-n=\"e16\">*</sup>.",[["425","15","<b>שהכתר. . ממוצע</b>: ראה ע\"ח שער (מב) דרושי אבי\"ע פ\"א. סידור שו, ב. לעיל ע' ה."],["e15","**","<b>כו'</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: ומ\"מ להיותו למעלה מהי\"ס עצמן ע\"כ המספר בו ביותר בחי' מאה כו'"],["e16","*","<b>וד\"ל</b>: בכת\"י 70 נכתב בסיום המאמר קיצור מכ\"ק אדמו\"ר הצ\"צ וכנראה קיצור לס\"א (חלוקת הסעיפים שונה בהבוך מהנדפס) אחר תיבות וד\"ל (בשו\"ה וד\"ל).\nקיצור. ספירות לשון בהירות, ג' שכליים וז' מדות שבנפש אע\"פ שנחשבים עצמיות הנפש לגבי ג' לבושים מחודומ\"ע עכ\"ז לגבי מהות הנפש נחשבים ג\"כ לבושים דהיינו שהם כלים שבהם ועל ידם פועלת הנפש, שע\"י השכל משכיל איך לעשות הדבר, וג' בחי' חב\"ד מתלבשים בחג\"ת כו', והם מתלבשים במחדומ\"ע שהם נקראים לבושים נפרדים ע\"ד כלבוש תחליפם ויחלופו, והנמשל שלכן ע\"ס שהם דוגמת שכל ומדות נקראו עשרה תקונים, שהם בחי' כלים שבהם ועל ידם פועל א\"ס ב\"ה בעולמות (הג\"ה ולכן אמר בס\"י ע\"ס במספר עשר אצבעות כי עיקר הפעולה גשמיות הוא ע\"י האצבעות וז\"ש כי אראה שמים מעשה אצבעותייך עכ\"ה) ולכן נק' ג\"כ ספירות ע\"ד זכוכית בהירה שעל ידה מתפשט כח הראי' (ומה שצריך לספירה שבה ועל ידה יביט, והלא היוצר עין הלא יביט כמ\"כ המאציל הספירות יכול להביט בעצמו מבלעדי הספירות אלא ע\"ד שנתבאר בת\"א פ' מקץ בד\"ה כי עמך מקור חיים בענין השקיפה ממעון קדשך מן השמים וברך את עמך, כי ע\"י בחינה זו נהי' אנחנו נתראים לפניו לדבר חשוב. [בגוכי\"ק חסר סיום החצע\"ג]."]]],[2100490137,"ב) <b>ועשרים</b> שנה כתיב שנה דלא אתפריש מחשבה ויובלא כו'. הנה ידוע דאו\"א נק' תרין ריעין<sup data-n=\"426\">16</sup> דלא מתפרשין כו' וזיווגייהו תדיר להחיות העולמות וידוע ענין ההפרש בין א\"א לאו\"א דא\"א להיותו עדיין רק בחי' שרש ומקור כללי לכל ההשתלשלו' דאצי' לא יתכן לומר בו ענין יחוד משפיע ומקבל ממש<sup data-n=\"427\">17</sup> אלא הוא יחידי בעצם רק מפני שהוא שרש כל ע\"כ בהכרח שימצא בו כל פרטי ההשתלשלות עכ\"פ בדרך כלל כנ\"ל והן רזא דמאה ברכאן כנ\"ל אבל חו\"ב דאצי' אחר שכבר נאצלו בבחי' יש מאין כמ\"ש והחכ' מאין תמצא<sup data-n=\"428\">18</sup> וכידוע א\"כ בהכרח שיש בהם בחי' יחוד משפיע ומקבל וע\"כ נק' תרין ריעין שהן שנים עכ\"פ אך שהמה מתייחדי' תמיד כו' וכמ\"ש במ\"א ולזה הטעם ג\"כ יובן מה שאינם נחשבים רק במספר עשיריו' ולא במספר מאה כי העשירית הוא כאשר המדה מיוחדת רק לעצמה בפרט ומפני שהיא נחלקת לי\"ס כידוע ע\"כ היא במספר עשיריו' וכך הענין בחו\"ב דאצי' מאחר שהמה נאצלים בדרך פרט ואינם ענינים כוללים הכל רק לעצמם ע\"כ נק' עשרים ב\"פ עשר בלבד משא\"כ אור הכתר להיותו בבחי' אור כולל הכל כנ\"ל והרי בהכרח שימצא בו מציאות כל הפרטי' בדרך כלל עכ\"פ כנ\"ל ע\"כ נק' מאה מטעם שכולל כל הי\"ס שמחולקים כאו\"א ליו\"ד כידוע וד\"ל.\n<b>ואמנם</b> עדיין י\"ל למה ישתנה מעלת החכ' מן הכתר והלא ידוע דאין התלבשות אור א\"ס אלא בחכ'<sup data-n=\"429\">19</sup> דוקא מטעם שהוא בחי' ביטול כח מ\"ה<sup data-n=\"430\">20</sup> כו' והרי גם כל עיקר יתרון מעלת אור הכתר היינו שהוא בחי' ממוצע ויש בו הארת בחי' עצמו' אא\"ס כנ\"ל וא\"כ מהו ההפרש ביניהם. אך הענין יובן עפ\"י דוגמא ממה שמצינו במשה שהי' שרש נשמתו מבחי' אור אבא<sup data-n=\"431\">21</sup> כמ\"ש ונחנו מה<sup data-n=\"432\">22</sup> דהיינו מבחי' מ\"ה דחכ' כידוע וע\"כ נאמר בו והאיש משה עניו מאד<sup data-n=\"433\">23</sup> כו' ואעפ\"כ לא נתגלה בו אור א\"ס כמו שהוא",[["426","16","<b>דאו\"א נק' תרין ריעין</b>: ראה זהר ויקרא ד, א."],["427","17","<b>א\"א. . לא יתכן. . ומקבל ממש</b>: ראה פע\"ח שער הק\"ש ספי\"א. שער הכוונות ענין הק\"ש."],["428","18","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["429","19","<b>התלבשות אור א\"ס אלא בחכ'</b>: ראה תניא פל\"ה בהג\"ה."],["430","20","<b>בחכ'. . כח מ\"ה</b>: זח\"ג לד, א."],["431","21","<b>במשה. . נשמתו. . אבא</b>: ראה לקו\"ש ח\"ו ע' 244 ואילך."],["432","22","<b>ונחנו מה</b>: בשלח טז, ז-ח."],["433","23","<b>והאיש משה עניו מאד</b>: בהעלותך יב, ג."]]],[2100490138,"ממש שהרי נאמר לו וראית אחורי<sup data-n=\"434\">24</sup> ופני לא יראו כו' וכמ\"ש כי לא יראני האדם וחי<sup data-n=\"435\">25</sup> כו' וזה לכאורה פלאי לפי הכלל הנ\"ל דאין התלבשות אא\"ס אלא בחכ' כו'.\n<b>אך</b> זה הענין יתורץ עפ\"י הקדמה א' ממ\"ש הה\"מ ז\"ל ע\"פ ה'<sup data-n=\"436\">26</sup> בחכ' יסד ארץ דאינו מובן לכאורה לשון בחכ' בבית השימוש כו' אך הענין הוא דהתלבשו' אא\"ס בחכ' אין הענין שמתגלה בה כמו שהוא ממש רק שמפני שהחכ' איננה דבר מסתיר ומנגד דהיינו להיות בבחי' יש ודבר היפוך האור האלקי ע\"כ יכול האור האלקי לשכון בו משא\"כ בבחי' יש נפרד אמרו אין אני והוא<sup data-n=\"437\">27</sup> יכולים לדור כו' וא\"כ אין החכ' יתרון מעלתה רק במה שיכולה להיות בבחי' כלי מכון לשבתו ית' אבל ענין שבתו ומשכנה בה הוא בדרך התלבשו' בודאי כי מאחר שהחכ' כבר נאצלה בבחי' יש מאין וכמ\"ש והחכ' מאין תמצא והגם שהחכ' מושללת מבחי' היש הנפרד ונק' אין לגביו וכידוע דהחכ'<sup data-n=\"438\">28</sup> נק' אין והבינה יש כו'<sup data-n=\"439\">29</sup> מ\"מ לגבי עצמות אור המאציל אין** ערוך כלל וכעשי' ממש נחשבת<sup data-n=\"440\">**</sup> משא\"כ באור הכתר מאחר שהוא בחי' ממוצע ויש בו מבחי' הארת עצמות המאציל זאת ההארה היא בו בבחי' עצמיו' דהיינו שהארת עצמי' המאציל כמו שהוא ממש בבלתי לבוש וירידת המדריגה כמו בהתלבשותו בחכ' כו' והוא להיות הכתר בחי' מקור הכל ולא בבחי' התגלות גמור עדיין כנ\"ל וד\"ל. וזהו שאמר ה' בחכ' בבית השימוש כלומר ה' שהוא אא\"ס מתלבש בתוך החכ' בדרך ההתלבשו' כאדם הדר בבית כו'. ובכ\"ז יתורץ מה שלא ראה משה הגם שהי' מבחי' מ\"ה דחכ' לבחי' פנימי' המאציל וכמ\"ש למשה ופני לא יראו כו'. ובזה יובן ג\"כ הטעם והתירוץ לקושי' הנ\"ל למה ישתנה מעלת החכ' להיות בירידת המדריגה ממעלת ומדריגת הכתר עד שא' בכתר מאה שנה ובחו\"ב עשרי' שנה כו' וד\"ל. אך עכ\"ז אמר במאמר הנ\"ל דגם בחו\"ב שנק' מחשבה ויובלא משום דגם הן לא מתפרשין כו' ונק' עשרים שנה ברזא דיחודא כו' כי להיות שאור החכ' תמידי' היא בבחי' הביטול דכח מ\"ה ע\"כ יחוד או\"א ג\"כ תמידי מפני שתמיד אור המאציל מתלבש בה ובעצמו' המאציל היחוד נצחי מטעם שהוא עצם אור א' פשוט כנ\"ל בפי' כד תסתכל לא תשכח אלא בוצינא חד כו' וד\"ל.\n<b>ושבע</b> שנים, אילין אתפרשאן ונפקין מכללא סתימאה דלעילא כו' דמתפרשין בדינא ורחמי כו' הנה עיקר ההפרש בין ג\"ר לז\"ת הוא במה שבג\"ר יש שם בחי' הביטול בתמידות כנ\"ל ע\"כ זיווגייהו תדיר כו' ואור המאציל שוכן שם בתמידו' כנ\"ל אבל בחי' ז\"ת שהן המדות חג\"ת נהי\"מ כו' לא יש בהם בחי' הביטול בתמידות כמו בג\"ר רק לפרקים ע\"כ גם בחי' היחוד שהוא התגלו' אור המאציל בהן אינו אלא לפרקים שונים כמו ג' מועדי רגלים שהן חג\"ת בלבד דכתיב ג'<sup data-n=\"441\">30</sup> פעמים בשנה יראה",[["434","24","<b>וראית אחורי</b>: ראה תשא לג, כג."],["435","25","<b>כי לא יראני האדם וחי</b>: שם שם, כ."],["436","26","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["437","27","<b>אין אני והוא</b>: ראה סוטה ה, א."],["438","28","<b>דהחכ' נק' אין</b>: ראה איוב כח, יב. וראה שערי אורה (לר\"י גיקטלייא) שער יו\"ד (קב, ב). תניא ליקוט פירושים פ\"ח ע' שכא."],["439","29","<b>כו'</b>: בכת\"י 1156 נוסף: ולא כמו שהוא בעצמו כו', וכ\"ק אדמו\"ר הצ\"צ עשה סוגריים לתיבות אלו."],["440","**","<b>אין ערוך כלל וכעשי' ממש נחשבת</b>: בכת\"י 1156 רשום: גם אור החכ' כמו יש כידוע. וכ\"ק אדמו\"ר הצ\"צ עשה סוגריים לתיבות אלו. ואולי הכוונה להוציא."],["441","30","<b>ג' פעמים בשנה</b>: ראה טז, טז."]]],[2100490139,"כל זכורך את פני הוי' אלקיך כו' או בכל ר\"ח ושבת ושעת העמידה דש\"ע בכל יום וכיוצא ולא בזמנים זולת אלה כידוע בכתבי האריז\"ל והוא מפני שאין שם מ\"ה כ\"כ מאיר במדות מפני שהן יוצאים ונמשכים בבחי' פירוד והתחלקות יותר מבחי' ג\"ר שהרי מבשרי אחזה כו' דהתפשטו' החסד הוא קו הימין כידוע והתפשטות מדת הגבורה והדין שהוא קו השמאל הרי הן מפורדים זמ\"ז לגמרי שהרי אין מרחמים בדין<sup data-n=\"442\">31</sup> ואין עונשין בשעת החסד כו' וגם מדת התפארת שהוא כלול משניהם בחו\"ג כי הוא מדה\"ר דמשפט איהו רחמי והגם שבעצמות המאציל אמר ולא משפט ידיעא<sup data-n=\"443\">32</sup> אבל כשמתגלים המדות באצי' גם המשפט ידיעה ויצא לחלק למדה מיוחדת בפ\"ע וכמ\"ש מלך במשפט יעמיד ארץ<sup data-n=\"444\">33</sup> כו' כידוע וא\"כ גם מדת המשפט יוצא ונמשך למטה בבחי' פירוד מאחר שאיננו בא כ\"א אחרי התגלו' שתי המדות חו\"ג כי לפי ערך התגלות הגבורות והדין כך יתעורר במדה\"ר לומר דאעפ\"כ ראוי להטיב לו מפני הרחמנות ואם ירבו הכחות של הדין יותר מדאי לא תוכל שאת מדה\"ר כו' הרי דגם מדה\"ר במדה וקצבה באה למטה ויש בה ב' המדות דחו\"ג בהתגלות גמור אך שהמה כלולים יחד אבל בבחי' הפירוד וההתחלקות היא באה כמו שארי המדות המסתעפי' מג\"ר כו' וד\"ל. וז\"ש ז' שנים דמתפרשין ונפקין מכללא דסתימאה כו' פי' כי מפני שיוצאין בבחי' פירוד קצת זמ\"ז ואין בהם בחי' הביטול להתכלל יחד כמו בג\"ר ע\"כ בחי' הארת עצמו' המאציל שנק' סתימאה אינו מאיר בהם כ\"כ כמו בג\"ר ולכן לא נמצא בהם היחוד רק לפרקים שונים כנ\"ל וע\"כ נק' ז' שנים ולא שנה ברזא דיחודא כנ\"ל כי עפ\"י הרוב אינם מיוחדים כנ\"ל וד\"ל.\nג) <b>(בסוף</b> המאמר הנ\"ל) ויהיו חיי שרה דהוו ממש דאתבריאו וקיימו לעילא עכ\"ל. הנה יש לדקדק בפי' הפסוק עצמו במה שכפל ב' פעמים להזכיר חיי שרה הא' בתחלתו שאמר ויהיו חיי שרה כו' והב' מה שבסוף הפסוק כפל עוד הפעם לומר שני חיי שרה שכבר אמרו ותיבות אלו שני חיי שרה מיותרין הן לגמרי. אך הענין יובן בהקדי' שרש ענין שרה מהו הנה פי' שרה הוא לשון וענין השתררות<sup data-n=\"445\">34</sup> כידוע והענין הוא לפי שאברהם ושרה הוא בחי' מ\"ה וב\"ן אברהם אב\"ר מ\"ה<sup data-n=\"446\">35</sup> כו' א\"ב ר\"ם<sup data-n=\"447\">36</sup> כידוע ושרה הוא בחי' ב\"ן<sup data-n=\"448\">37</sup> הנק' מלכות<sup data-n=\"449\">38</sup> ונק' מטרוניתא ואימא תתאה וע\"כ אמרו בלשון שרה אמנו כו' כמ\"ש בחוה כי היא היתה אם כל חי<sup data-n=\"450\">39</sup> וידוע הענין שהוא בחי' כח הפועל האלקי בנפעל להחיות העולמות כולן מאין ליש בדוגמת האם לבנים שהיא הולידה אותם כך נאמר כי הייתה אם כל חי כו' וכמ\"ש ואתה מחי'<sup data-n=\"451\">40</sup> את כולם וגם בחי' שרה אימנו להיות כי הייתה בחי' מרכבה לבחי' מל' דאצי' נק' שרה כו' ומפני שהיא הנק'",[["442","31","<b>אין מרחמים בדין</b>: כתובות פד, א."],["443","32","<b>דמשפט איהו רחמי. . ידיעא</b>: ראה הקדמת ת\"ז (יז, ב)."],["444","33","<b>מלך במשפט יעמיד ארץ</b>: משלי כט, ד."],["445","34","<b>שרה הוא לשון. . השתררות</b>: ראה רש\"י נח יא, כט. ברכות יג, א. ב\"ר פמ\"ז, א."],["446","35","<b>אברהם אב\"ר מ\"ה</b>: זח\"א ד, א."],["447","36","<b>א\"ב ר\"ם</b>: ראה זח\"א (סתרי תורה) עט, ב."],["448","37","<b>ושרה הוא בחי' ב\"ן</b>: ראה אוה\"ת בראשית (כ\"ב) תמז, ב. תמה, א. (כ\"א) מ, ב."],["449","38","<b>ושרה. . מלכות</b>: ראה לקו\"ת להאריז\"ל ח\"ש כג, ב."],["450","39","<b>כי. . כל חי</b>: ראה בראשית ג, כ."],["451","40","<b>ואתה מחי'</b>: נחמי' ט, ו."]]],[2100490140,"מטרוניתא לשון שררה כי מלכותו בכל משלה<sup data-n=\"452\">41</sup> כידוע וע\"כ אמר ויהיו חיי שרה כלומר מאלה השנים הנזכרים בסמוך מאה שנה ועשרים שנה וז' שנים הן הן ערך חיי שרה כו'. וביאור הדברים הנה ידוע מ\"ש כל הנחלים<sup data-n=\"453\">42</sup> הולכים אל הים כו' שבחי' המל' הנק' בשם ים<sup data-n=\"454\">43</sup> כידוע מקבלת היא מכל הנחלים העליונים דאצי' וגם מה שלפני האצי' הכל נמשכים ויורדי' בה מפני שהיא בחי' הכלי לקבל כל נהורין כמ\"ש בזוהר כעשישתא דמקבלת<sup data-n=\"455\">44</sup> כו' וכידוע עד\"מ המראה כו' וכמ\"ש במ\"א והנה הגם שבאצי' עצמו יש מדריגות חלוקות זה למעלה מזה ואין בתחתון ממה שבעליון הימנו ובדרך כלל הנה השנים הנזכרים מאה שנה הן בבחי' א\"א דוקא ועשרים שנה באו\"א דוקא וז' שנים בז\"א כו' וכאו\"א מיוחד בפ\"ע אעפ\"י שהן באין בהשתלשלו' מא\"א לאו\"א כו' אבל בבחי' מל' כלולים כל השנים הנ\"ל ויש בה גם מאה שנה דא\"א וגם עשרים שנה דאו\"א וגם ז' שנים דז\"א כו' ולא מנין שנים ממדריג' אחת בלבד כי היא בחי' הכוללת הכל מטעם הנ\"ל דנק' עשישת' כו' וכל ההמשכות העליונות שנמשכים בה ואינה מקבלת דבר פרטי אלא מקבלת הכל כו' וד\"ל. והנה כל אלה השנים דהיינו מאה שנים דא\"א הנ\"ל ועשרים שנה דאו\"א וז' שנים דז\"א כולהו חיי איקרו ונק' חיי שרה כי הרי מהן נתמלאה וקיבלה ונעשית בנין פרצוף שלם כו' ולהיות כי סוף מעשה<sup data-n=\"456\">45</sup> עלה במח\"ת כי כל עיקר רצון המאציל בהשתלשלו' האצי' הי' רק בשביל הסוף מעשה דהיינו להיות בחי' מל' דאצי' מחי' בי\"ע כו' ע\"כ אמר ויהיו חיי שרה פי' כמ\"ש דהוו ממש דאתבריאו וקיימא לעילא ר\"ל דלעילא בעצמות המאציל הוכנו ואתבריאו ועלו במח' כו' ואח\"כ ירדו דהיינו למטה להיות הכתר כלול מק' ברכאן הנק' מאה שנים ואח\"כ באו\"א עשרים ובז\"א ז' שנים כו' כנ\"ל והכל בשביל המל' הנק' שרה כנ\"ל להיות לה לחיים שרשיי' בכדי שתוכל להשפיע למטה אח\"כ מאין ליש בבי\"ע כו' וד\"ל. וזהו תוכן כוונת המאמר בקצרה בפי' הפסוק שאמר ויהיו חיי שרה כו'.\n<b>ולהבין</b> זה בביאור יותר הנה ידוע דהמל' הוא בחי' מקור הזמן כמ\"ש מלך מלך וימלוך<sup data-n=\"457\">46</sup> כו' כי עולם שנה כו' וכמ\"ש בע\"ח בפי' המשנה<sup data-n=\"458\">47</sup> מצות עשה שהזמן גרמא נשים פטורות כו' שהענין הוא דהזמן גרמא בבחי' המל' שנק' נוק' דז\"א דשם נשים פטורות מפני שבחי' מקור הזמן בנוק' דוקא כנ\"ל וע\"כ מצ\"ע שהזמן גרמא דוקא נשים פטורות כו' ע\"ש וד\"ל. ולמעלה מבחי' מקור הזמן הוא באצי' עצמו כמו בבחי' ז\"א ואו\"א וא\"א כו' מפני שבבחי' האצי' עדיין אין מקור לזמן אלא הי' הוה ויהי' כא' כמשמעות שם הוי'<sup data-n=\"459\">48</sup> כידוע ולהיות כן הרי כשנמשך בחי' הארות והמשכות מכל הפרצופים דאצי' ולמעלה מהאצי' דהיינו מן המאציל במל' ה\"ז כמו ענין ההמשכה",[["452","41","<b>מלכותו בכל משלה</b>: ע\"ד תהלים קג, יט."],["453","42","<b>כל הנחלים</b>: קהלת א, ז."],["454","43","<b>המל' הנק' בשם ים</b>: ראה מאו\"א מערכת ים."],["455","44","<b>כעשישתא דמקבלת</b>: ראה זהר תצוה קפו, ב."],["456","45","<b>סוף מעשה</b>: ראה פיוט לכה דודי."],["457","46","<b>מלך מלך וימלוך</b>: ראה זח\"א לד, א."],["458","47","<b>בפי' המשנה</b>: קידושין כט, א. וראה טעמי המצות (להאריז\"ל) פ' בראשית. ע\"ח שער (נ) קיצור אבי\"ע פ\"ד. כנפי יונה חלק ראשון פע\"א. אוה\"ת פנחס ע' א'קצט. בא ע' שמט. ביאוה\"ז להצ\"צ ויגש ע' קמח."],["459","48","<b>כמשמעות שם הוי'</b>: ראה זח\"ג רנז, ב."]]],[2100490141,"מלמעלה מן הזמן לבחי' זמן בדרך כלל וזהו הטעם שנק' השנים הנ\"ל בשם חיי שרה כדוגמת ומשל חיי נפש האדם בגופו שבאה ונמשכת בזמן מלמעלה מן הזמן וכמ\"ש ימים יוצרו<sup data-n=\"460\">49</sup> כו' וכידוע ומבואר במ\"א וד\"ל. והנה בכל הנ\"ל מתורץ גם הקושי' הנ\"ל בפי' הכפל שהכפיל לומר עוד הפעם שני חיי שרה כו', כי הנה מבואר למעלה בפי' המאמר דהוו ממש דאתבריאו כו' משום דסוף מעשה עלה במח\"ת כו' וא\"כ בזה הטעם יתורץ ג\"כ מה שהמל' דוקא כלולה מכל השנים ולא זולתה כו' וכנ\"ל ואעפ\"י שמקבלת רק מז' שנים דז\"א אבל מצד שרשה במח\"ת כלולה מהכל דוקא וזהו פי' ויהיו חיי שרה דהוו ממש פי' דהוו כבר כו' אמנם לאחרי שעכשיו כבר קיבלה כל האורות העליונים כמו שעלה במח\"ת כו' הנה עיקר הכוונה עתה הוא שיושפע ממנה למטה להחיות רוח שפלים דוקא וכנ\"ל ע\"כ זהו שכפל אח\"כ ואמר שני חיי שרה כלומר מאלה השנים הנזכרים שהיו שרשיי' לשרה נמשך מזה אח\"כ מה שנמשך משרה עצמה שנים וחיים למטה בבי\"ע ג\"כ כדוגמת השנים הנזכרים ונקראים שני חיי שרה פי' מה שנמשך משרה למטה כדוגמת משל חיי נפש האדם בגופו שנקראים חיי' ושנים כו' וכך אמר שני חיי שרה מפני שהן שלה לאחר שיורדת חיות למטה להיות נק' אימא ע\"ד שנא' בחוה כי הייתה אם כל חי כו' משא\"כ בשנים הנזכרים תחלה אמר ויהיו חיי שרה משום דהוו כבר כו' ולא נק' שני חיי שרה אך משום דהא בהא תלי' ע\"כ אמר כסדר ויהיו חיי שרה דהיינו בתחלת המחשבה מאה שנה וכו' ואז ממילא נעשה מהם למטה שני חיי שרה (ופי' זה דשני חיי שרה הוא היפך פי' חיי שרה הראשון דחיי שרה הראשון הוא מלמעלה מן הזמן לזמן בכלל ופי' חיי שרה האחרון הוא מבחי' מקור הזמן דמל' למטה להחיות רוח שפלים מאין ליש כנ\"ל וד\"ל).\n<b>ותמת</b> שרה בקרית ארבע כו' ויבא אברהם לספוד לשרה ולבכותה<sup data-n=\"461\">50</sup> כו'. דהנה מבואר למעלה דדוקא בבחי' המל' יש מכל מה שיש למעלה גם מבחי' הכתר מפני שסוף מעשה דוקא עלה במח\"ת כו' וא\"כ גם בחי' הסתלקות שלה עולה למעלה מעלה ברום המעלות ביותר ובדרך דוגמא אנו מוצאים כמה מיני מדריגות של מס\"נ בנשמות שמבחי' מל' דוקא וכמו ר\"ע שיצאה נשמתו באחד<sup data-n=\"462\">51</sup> בבחי' העלאת מ\"נ כו' והוא מפני בחי' יחידה בכל מאדך כו' וזהו דוגמא להבין שיש גם בחי' כתר במל' כו' ואמנם הרי הוא בחי' או\"ח דכתר כו' וד\"ל. וזהו ותמת שרה בקרית ארבע פי' שם ב\"ן דשרה כנ\"ל עלה ונסתלק למעלה בבחי' או\"ח מלמטה למעלה מעלה דהיינו במקור חוצבה במח\"ת כו' ולהיות כי עולה היא במעלת עצמו' המאציל ע\"כ אמר לאחר שמתה שרה ונסתלקה בא אברהם לספוד לשרה ולבכותה כו' כי הנה ארז\"ל אגרא דהספדא דלויי<sup data-n=\"463\">52</sup> פי' דלויי הן העלאות כענין דלה דלה לנו<sup data-n=\"464\">53</sup> כו' וידוע ענין ההספד לנשמה שנסתלקה הוא כדי להעלות אותה בזה במקור חוצבה ולתקן אותה בזה ההספד כדי שיהי' ממנה עוד תיקון להבא והוא שתוכל לחזור ולבא בעולם לתקן דבר ולקיים ע\"י תומ\"צ כמבו' בס' הגלגולים כו' וכך בדרך כלל הי' ענין הספד",[["460","49","<b>ימים יוצרו</b>: תהלים קלט, טז."],["461","50","<b>ותמת. . ולבכותה</b>: חיי שרה כג, ב."],["462","51","<b>ר\"ע שיצאה נשמתו באחד</b>: ראה ברכות סא, ב."],["463","52","<b>אגרא דהספדא דלויי</b>: ברכות ו, ב."],["464","53","<b>דלה דלה לנו</b>: שמות ב, יט."]]]]});
